(window.GIM_TS=window.GIM_TS||{})["Bava Metzia.5"]={"from":120,"a":[["\u0003\"וחי אחיך עמך\"\u0004 (ויקרא כה, לו), והוא מלמדנו: \u0003אהדר ליה כי היכי דניחי\u0004 \u0005[החזר לו כדי שיחיה].\u0006","ושואלים: \u0003ור' יוחנן, האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"וחי אחיך עמך\" מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה בו],\u0006 כיצד מפרש הוא אותו לשיטתו? ומשיבים: \u0003מבעי ליה לכדתניא\u0004 \u0005[צריך הוא אותו לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003שנים שהיו מהלכין בדרך\u0004 במקום שומם \u0003וביד אחד מהן קיתון של מים, אם שותין שניהם\u0004 — \u0003מתים,\u0004 שאין המים מספיקים לשניהם. \u0003ואם שותה אחד מהן\u0004 בלבד — \u0003מגיע לישוב. דרש בן פטורא: מוטב שישתו שניהם וימותו, ואל יראה אחד מהם במיתתו של חבירו. עד שבא ר' עקיבא ולימד:\u0004 מה שנאמר \u0003\"וחי אחיך עמך\",\u0004 משמעו: \u0003חייך קודמים לחיי חבירך.\u0004","על דעה זו שריבית שניטלה איננה חייבת בהשבה \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003הניח להם אביהם מעות של רבית, אף על פי שיודעים\u0004 הבנים \u0003שהן של רבית\u0004 — \u0003אינן חייבין להחזירן.\u0004 ונדייק מן הלשון: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אביהן\u0004 עצמו \u0003חייב להחזיר!\u0004","ודוחים: \u0003בדין\u0004 \u0005[הדין]\u0006 \u0003הוא\u0004 \u0003דאבוהון נמי לא מיחייב\u0004 \u0005[שאביהם גם כן איננו חייב]\u0006 \u0003להחזיר,\u0004 \u0003ואיידי דקא בעי למתני סיפא\u0004 \u0005[ומתוך שרוצה לשנות בסוף]:\u0006 \u0003הניח להן אביהן פרה וטלית וכל דבר המסוים\u0004 (דבר מוגדר, שמכירים אותו), אם היה זה חפץ גזול \u0003חייבין להחזיר\u0004 לבעליו \u0003מפני כבוד אביהם,\u0004 שאם לא כן, בכל פעם שיראו אנשים את הפרה או הטלית ייזכרו שהאב גזל אותם, ועל כן \u0003תני נמי רישא בדידהו\u0004 \u0005[שנה גם כן בתחילה בהם]\u0006 ולא באב.","ושואלים לגוף הענין האחרון: \u0003והני\u0004 \u0005[ואלה],\u0006 \u0003מפני כבוד אביהם מי מיחייבי\u0004 \u0005[האם הם חייבים]\u0006 לעשות לכבודו? \u0003קרי\u0004 \u0005[קרא]\u0006 \u0003כאן\u0004 במקרה זה את הכתוב: \u0003\"ונשיא בעמך לא תאר\"\u0004 (שמות כב, כז), ודייקו מן הכתוב \"בעמך\" לומר: \u0003בעושה מעשה עמך.\u0004 שאיסור זה חל רק אם הנשיא נוהג ככשרים בישראל, וכאן במקרה זה שהאב היה רשע ומלוה בריבית — מדוע חייבים הבנים בכבודו?","ומשיבים: צריכים להבין זאת \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003ר' פנחס משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא\u0004 לענין אחר: מדובר \u0003ב\u0004אופן \u0003שעשה תשובה, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בשעשה\u0004 האב \u0003תשובה,\u0004 ולכן צדיק הוא וראוי לכבוד. ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003עשה תשובה, מאי בעי גביה\u0004 \u0005[מה עושה אצלו]\u0006 חפץ גזול? ומשיבים: מדובר באופן \u0003שלא הספיק להחזיר עד שמת.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 \u0003הגזלנין ומלוי רבית, אף על פי שגבו\u0004 כספם — \u0003מחזירין.\u0004 ותחילה מבררים את לשון הברייתא: \u0003גזלנין, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אף על פי שגבו איכא\u0004 \u0005[יש\u0006 בהם\u0005]?\u0006 מה שייך בהם לשון \"גביה\"? \u0003אי גזול\u0004 \u0005[אם גזלו]\u0006 — \u0003גזול\u0004 \u0005[גזלו],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא גזול\u0004 \u0005[גזלו]\u0006 — \u0003גזלנין קרית להו\u0004 \u0005[אתה קורא אותם]?!\u0006 \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ופרש כך: \u0003גזלנין, מאי ניהו\u0004 \u0005[מה הם]\u0006 — \u0003מלוי רבית, אף על פי שגבו\u0004 — \u0003מחזירין.\u0004 ומכאן שיש להחזיר את הריבית!","ומשיבים: בעיקרו של דבר נושא זה כולו \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 זו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' נחמיה ור' אליעזר בן יעקב פוטרין את המלוה ואת הערב\u0004 מעונש מלקות על מצות \"לא תעשה\" של ריבית, \u0003מפני שיש בהן \"קום עשה\"\u0004 וכלל הוא שכל עבירה שיש לה תיקון על ידי מעשה — אין לוקים עליה. ומעתה נברר \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 \u0003\"קום עשה\"\u0004 זה? \u0003לאו\u0004 \u0005[האם\u0006 \u0003לא]\u0004 \u0003משום דאמרינן להו קומו אהדורו\u0004 \u0005[עמדו והחזירו]?\u0006","ואם זו דעת חכמים אלה, אם כן \u0003מכלל\u0004 דבריהם אתה למד שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]\u0006 כי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בני אהדורי נינהו\u0004 \u0005[החזרה הם]\u0006 ואין בזה \"קום עשה\"! את הפירוש הזה דוחים: \u0003לא, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"קום עשה\"\u0004 — \u0003לקרוע שטרא\u0004 \u0005[את השטר]\u0006 שכתובה בו הריבית\u0005.\u0006 ושואלים: מה מועיל הדבר?","\u0003מאי קסבר\u0004 \u0005[מה סבור]\u0006 אותו חכם? \u0003אי קסבר\u0004 \u0005[אם סבור\u0006 הוא\u0005]\u0006 כי \u0003שטר העומד לגבות כגבוי דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 אם כן \u0003הא עבדו איסורייהו\u0004 \u0005[הרי\u0006 כבר \u0005עשו את האיסור שלהם]\u0006 בכתיבת השטר, ולא יועיל להם כשיקרעוהו. \u0003ואי לאו\u0004 \u0005[ואם לא]\u0006 \u0003כגבוי דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא עבוד\u0004 \u0005[עשו]\u0006 \u0003ולא כלום\u0004 כל עוד לא גבו את הריבית. ובכל אופן אין תיקון בקריעת השטר!","ומשיבים: \u0003לעולם קסבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003שטר העומד לגבות\u0004 — \u0003לאו כגבוי דמי\u0004 \u0005[נחשב],\u0006 \u0003והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו]\u0006 כאן \u0003דשומא מילתא היא\u0004 \u0005[שהשומה,\u0006 ההערכה, היא עצמה \u0005דבר\u0006 חשוב \u0005הוא],\u0006 כלומר, שכיון שנכתב שטר, ועשו שומא = הערכה של נכסי החייב — הרי זה נחשב למעשה.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לפרש לפי הענין, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ואלו עוברים ב\u0004איסור \u0003\"לא תעשה\"\u0004 של ריבית: \u0003המלוה והלווה, הערב והעדים.\u0004 ויש לשאול: \u0003בשלמא כולהו\u0004 \u0005[נניח כולם]\u0006 עוברים — שהרי \u0003עבוד\u0004 \u0005[עשו]\u0006 \u0003מעשה\u0004 ועליו הם נענשים. \u0003אלא עדים מאי עבוד\u0004 \u0005[מה עשו]\u0006 שיתחייבו? \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא נלמד מכאן]\u0006 \u0003דשומא מילתא היא\u0004 \u0005[שהשומה,\u0006 ההערכה, היא עצמה \u0005דבר\u0006 חשוב \u0005הוא]\u0006 ובענין זה עדים נעשים שותפים לעבירה, שלולא עדותם אין כאן שומא. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003אמר רב ספרא\u0004 לפי השיטה שכופים להחזיר ריבית, יש בדבר כמה כללים. \u0003כל\u0004 דבר שהוא חוזה ברור כזה, \u0003שאילו\u0004 היתה בו התחייבות של הלווה לתוספת ריבית על הקרן הרי \u0003בדיניהם\u0004 של אומות העולם (שאינן מוזהרות על הריבית) היו \u0003מוציאים\u0004 אותה בהכרח \u0003מ\u0004ן ה\u0003לוה למלוה\u0004 כפי שהתחייב, — \u0003בדינינו\u0004 ריבית כזו \u0003מחזירין מ\u0004יד ה\u0003מלוה ללוה. כל שאילו בדיניהם אין מוציאין מלוה למלוה,\u0004 שאינו הסכם ברור וחד משמעי, \u0003בדינינו אין מחזירין ממלוה ללוה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: וכללא\u0004 \u0005[ו\u0006כי \u0005כלל]\u0006 \u0003הוא\u0004 זה, כלומר, וכי כלל זה קיים תמיד? \u0003והרי\u0004 אם הלווה \u0003סאה בסאה\u0004 ובינתיים עלה מחיר הסאה — ש\u0003בדיניהם מוציאין מלוה למלוה, ובדינינו אין מחזירין ממלוה ללוה\u0004 שהרי אין זו ריבית מן התורה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אינהו\u0004 \u0005[הם\u0006 הגויים\u0005]\u0006 אינם רואים עיסקה כזו כהלוואה אלא \u0003בתורת פקדון אתא לידיה\u0004 \u0005[בא לידו]\u0006 ובדיניהם אין בכך ענין של החזרת הלוואה, אלא של השבת פקדון.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: והרי משכנתא בלא נכייתא\u0004 \u0005[ניכוי],\u0006 שממשכנים את שדה הלווה אצל המלוה, וכל עוד לא הוחזר החוב הוא אוכל מפירות השדה אבל אינו מנכה את הפירות הללו מן החוב, ונמצא שמקבל תוספת ריבית על הלוואתו (על ידי פירות אלה) ש\u0003בדיניהם מוציאין מלוה למלוה\u0004"],["\u0003ובדינינו אין מחזירין ממלוה ללוה,\u0004 שכיון שלא קבע ריבית קצובה מראש, ואף אין בטחון שיהיו לו פירות, נחשב הדבר כאבק ריבית. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אינהו\u0004 \u0005[הם,\u0006 הגויים\u0005]\u0006 אינם רואים זאת כהלוואה, ולדעתם \u0003בתורת זביני אתא לידייהו\u0004 \u0005[ממכר בא לידיהם]\u0006 שהשדה כאילו נמכר לזמן קצר למלוה, והוא חוזר ומוכרו ללווה כשיקבל את הכסף.","ושואלים: \u0003אלא\u0004 אם כן \u0003כל שאילו בדיניהן דקאמר\u0004 \u0005[שאמר]\u0006 \u0003רב ספרא\u0004 — \u0003מאי אתא לאשמועינן\u0004 \u0005[מה בא להשמיענו],\u0006 הרי מתברר שלא חידש דבר בדברים אלה! ומשיבים: \u0003הכי אתא לאשמועינן\u0004 \u0005[כך בא להשמיענו]:\u0006 \u0003כל שאילו בדיניהן מוציאין מלוה למלוה\u0004 — \u0003בדינינו מחזירין ממלוה ללוה, ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 — \u0003ברבית קצוצה, וכ\u0004שיטת \u0003ר' אלעזר.\u0004","\u0003כל שאילו בדיניהם אין מוציאין בדינינו אין מחזירין\u0004 — והוא \u0003רבית מוקדמת,\u0004 שנותן משהו כדי שיקבל הלוואה ו\u0003רבית מאוחרת\u0004 שנותן לו מתנה כגמול על ההלוואה, שדברים אלה אין נחשבים כהסכם מחייב ואף אנו איננו מוציאים.","ועוד בפירוש המשנה. שנינו בה: \u0003כיצד, לקח הימנו\u0004 (קנה ממנו) \u0003חטים בדינר זהב הכור וכן השער וכו'.\u0004 ושואלים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003אין לו יין מאי הוי\u0004 \u0005[מה יהיה],\u0006 מה ההבדל להלכה?","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין פוסקין\u0004 להבטיח מחיר \u0003על הפירות\u0004 שאדם קונה בשעת הגורן ומקבל לאחר זמן \u0003עד שיצא\u0004 וייקבע \u0003השער,\u0004 המחיר היציב לאותה תבואה, \u0003יצא השער\u0004 — \u0003פוסקין,\u0004 אף שאין ביד המוכר תבואה זו, כי \u0003אף על פי שאין לזה יש לזה\u0004 ויכול הקונה לקבל במחיר זה. ואם כן כיון שיש שער לדבר, וגם אם אינו מקבלו מיד — אין זה נחשב עוד כהלוואה בריבית!","\u0003אמר רבה: מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003בבא לחוב\u0004 את \u0003דמיהן עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שאילו היה ללווה יין באותה שעה, היה אכן נעשה קנין באותו יין בשעה שהסכימו ביניהם, והיה כאן מכר אמיתי. אבל כשאין לו יין — נתברר שלא היתה כאן עיסקת קניה כלל. וכאשר המלוה תובע את כספו כדי לקנות יין מבטיח לו הלווה כמות יין במחיר גבוה יותר, אף כי אין לו לעצמו כל יין.","\u0003וכדתניא\u0004 \u0005[וכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיה נושה בחבירו מנה, והלך ועמד על גורנו\u0004 של החבר, \u0003ואומר\u0004 לו: \u0003\"תן לי מעותי, שאני רוצה ליקח\u0004 (לקנות) \u0003בהם חטים. אמר לו: חטים יש לי\u0004 בגורן \u0003שאני נותן לך\u0004 מהן, \u0003צא ועשה\u0004 (חשב) \u0003עלי\u0004 את הכמות המגיעה לך \u0003כשער של עכשיו, ואני אעלה\u0004 (אספק) \u0003לך כל שנים עשר חדש\u0004 מן החיטים הללו לפי השער של עכשיו. דבר זה \u0003אסור\u0004 משום ריבית, \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003כאיסרו הבא לידו דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006 שכיון שאין הלווה הלוקח נותן למלוה אפילו איסר אחד בשעה זו, אין כאן מכר ממש, אלא ריבית היא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אי\u0004 \u0005[אם]\u0006 הנימוק הוא שפעולה זו היא ש\u0003לא כאיסרו הבא לידו, מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא שנה\u0005]\u0006 באופן ש\u0003אין לו? אפילו יש לו\u0004 יין \u0003נמי\u0004 \u0005[גם כן]\u0006 היה חייב כך משום ריבית, לפי שלא נתן כל כסף בשעת הקניה! \u0003אלא,\u0004 יש לדחות פירוש זה. ו\u0003אמר אביי: מתניתין\u0004 \u0005[משנתנו]\u0006 צריך להבינה \u0003כדתני\u0004 \u0005[כפי ששנה]\u0006 \u0003רב ספרא\u0004 ברייתא \u0003ב\u0004הלכות \u0003רבית,\u0004 שנשנתה \u0003דבי\u0004 \u0005[\u0006ב\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' חייא,\u0004","ושם שנינו: \u0003יש דברים שהם מותרין\u0004 בעצם מדין תורה, אבל \u0003אסורין מפני הערמת רבית. כיצד? אמר לו: הלויני מנה\u0004 (מאה דינרים)! \u0003אמר לו: מנה אין לי, חטין במנה יש לי שאני נותן לך. נתן לו חטין במנה, וחזר ולקחן הימנו\u0004 (קנה אותם ממנו) \u0003בעשרים וארבע סלע\u0004 שהן תשעים וששה דינרים — הרי זה \u0003מותר,\u0004 שהרי היתה פה קניה כפולה, אבל \u0003אסור לעשות כן מפני הערמת רבית.\u0004 וכיון שלא קנה קניה אמיתית, הרי היתה כאן רק הערמה על דיני ריבית.","\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 במשנה מדובר \u0003כגון\u0004 ש\u0003אמר\u0004 לו: \u0003הלויני שלשים דינרים אמר לו\u0004 חבירו: \u0003שלשים דינרים אין לי, חטין בשלשים דינרים יש לי שאני נותן לך.\u0004 אחר כך \u0003נתן לו חטין בשלשים דינרים, וחזר ולקחם הימנו בדינר זהב\u0004 (עשרים וחמשה דינרים). ומעתה, \u0003אי אית ליה חמרא\u0004 \u0005[אם יש לו יין]\u0006 \u0003ללוה\u0004 \u0003דיהיב ליה\u0004 \u0005[שנותן לו]\u0006 \u0003בשלשים דינר,\u0004 אם כן \u0003פירא הוא דקא שקיל מיניה, ולית לן\u0004 \u0005[פירות הוא שלוקח ממנו, ואין לנו\u0006 \u0003בה\u0004 איסור ריבית. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 \u0003כיון דלית ליה חמרא\u0004 \u0005[שאין לו יין]\u0006 — \u0003ודאי משקל זוזי מיניה, מחזי\u0004 \u0005[לקיחת כסף ממנו נראית],\u0006 על כל פנים \u0003כרבית.\u0004","\u0003אמר ליה\u0004 \u0005[אמר לו]\u0006 \u0003רבא: אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, אין דבר זה מדוייק בלשון המשנה, שהרי במשנה נאמר \u0003\"תן לי חיטי\",\u0004 ולפי פירושך \u0003\"\u0004תן לי \u0003דמי חיטי\" מבעי ליה\u0004 \u0005[צריך היה\u0006 לומר\u0005]!\u0006 ומשיבים: \u0003תני\u0004 \u0005[שנה,\u0006 תקן הגירסה\u0005]\u0006 \u0003\"דמי חיטי\".\u0004 ועוד הקשה: הלשון \u0003\"שאני מוכרן\"\u0004 אינה מדוייקת, \u0003\"שמכרתים לך\" מבעיא ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 ומתקנים: \u0003תני\u0004 \u0005[שנה]\u0006 \u0003\"שמכרתים לך\".\u0004 ועוד יש להקשות על הלשון נאמר שם: \u0003\"הרי חטיך עשויות עלי בשלשים דינרין\",\u0004 הלא \u0003מעיקרא נמי הכי אוקמינהו עילויה\u0004 \u0005[מתחילה גם כן כך העמיד,\u0006 קצב, \u0005עליו את\u0006 המחיר\u0005]!\u0006 ומשיבים: \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]:\u0006 \u0003בדמי חטיך שעשית עלי בשלשים דינר.\u0004","ומקשים שוב: לשון המשנה הוא \u0003\"הרי לך אצלי בהן יין ויין אין לו\", והא\u0004 \u0005[והרי]\u0006 \u0003\"בדינר זהב הכור וכן השער\" קתני\u0004 \u0005[שנה]!\u0006 \u0003אלא אמר רבא:\u0004 פירוש זה שאמר אביי איננו הולם את המשנה, אלא יש לתרץ באופן אחר, והעיר: \u0003כי שכיבנא\u0004 \u0005[כאשר אמות]\u0006 \u0003ר' אושעיא נפק לוותי\u0004 \u0005[ייצא לקראתי\u0006 בגן עדן\u0005]\u0006"],["\u0003דמתרצנא מתניתין כוותיה\u0004 \u0005[שאני מתרץ את משנתנו לפי שיטתו]\u0006 לפי הברייתות שהוא ערך.","\u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' אושעיא: הרי שהיה נושה בחבירו מנה, והלך ועמד על גורנו\u0004 של החבר \u0003ואמר\u0004 לו: \u0003תן לי מעותי, שאני רוצה ליקח\u0004 (לקנות) \u0003בהן חטין. ואמר\u0004 לו הלווה: \u0003חטין יש לי שאני נותן לך, צא ועשאן\u0004 (חשב אותן) \u0003עלי כשער\u0004 החטים \u0003של עכשיו. הגיע זמן חטין למכור, אמר לו\u0004 המלוה: \u0003תן לי חטין,\u0004 כיון \u0003שאני רוצה למוכרן וליקח בהן יין. אמר לו\u0004 הלווה: \u0003יש לי יין שאני נותן לך, צא ועשאן עלי\u0004 (חשב את היין הזה) \u0003כשער של עכשיו.\u0004","\u0003הגיע זמן יין למכור, ואמר לו: תן לי ייני שאני רוצה למוכרו וליקח בו שמן. אמר לו: שמן יש לי שאני נותן ל\u0004\u0003ך, צא ועשהו עלי כשער של עכשיו.\u0004 בכל הדברים הללו \u0003כולם, אם יש לו\u0004 ללווה באמת יין ושמן — \u0003מותר,\u0004 לפי שהיתה זו מכירה ממש. אבל אם \u0003אין לו\u0004 — \u0003אסור,\u0004 כיון שאינו יכול עכשיו לתת לו סחורה — הרי אם היא בינתיים תתייקר יהיה בזה משום תשלום נוסף עבור דחיית פרעון החוב. \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"לקח\"\u0004 שבמשנה — הכוונה \u0003לקח בהלואתו.\u0004","\u0003אמר רבא: שמע מינה\u0004 \u0005[למד ממנה]\u0006 מהלכה זו שאמר \u0003ר' אושעיא תלת\u0004 \u0005[שלושה\u0006 דברים\u0005]:\u0006 \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 ש\u0003מעמידין מלוה\u0004 (הלוואה) \u0003על גבי פירות,\u0004 כלומר, לווה יכול להבטיח לשלם למלוה דמי חובו מן הפירות במשך השנה לפי השער שנקבע בתחילת השנה, \u0003ולא אמרינן\u0004 \u0005[ואין אנו אומרים]\u0006 שדבר זה הוא ש\u0003לא כאיסרו הבא לידו\u0004 כעת, אלא כיון שיש פירות — הרי זה כאילו מסר לו עתה. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 הלכה נוספת; שדבר זה מותר ו\u0003הוא\u0004 ש\u0003יש לו\u0004 פירות אצלו. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 כי \u0003איתא\u0004 \u0005[יש]\u0006 בסיס \u0003ל\u0004דברי \u0003ר' ינאי.\u0004","ש\u0003אמר ר' ינאי: מה לי הן מה לי דמיהן,\u0004 שאם פסק עם חבירו לקבל תבואה לפי שער מסויים, יכול אחר כך לקחת לא את התבואה עצמה אלא אף את מחירה (דמיה), ואין בכך משום ריבית.","\u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו אמוראים בבעיה זו, \u0003רב אמר: עושין אמנה בפירות\u0004 שאדם יכול לעשות הסכם עם חבירו שימסור לו פירות לאחר זמן לפי השער שבשעת ההסכם. \u0003ואין עושין אמנה\u0004 כעין זו כשאינו לוקח ממנו פירות אלא ב\u0003דמים. ור' ינאי אמר: מה לי הן, ומה לי דמיהן.\u0004 וכשם שיכול לקבל הפירות ולמכרם בעצמו, כן יכול לקבל דמיהן במישרים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על רב ממה ששנינו: \u0003כולם, אם יש לו\u0004 — \u0003מותר,\u0004 משמע שכשיש לו אינו חייב לשלם בפירות עצמם! \u0003אמר רב הונא אמר רב:\u0004 שם מדובר \u0003בשמשך\u0004 ועשה קנין ממש באותם פירות. ותוהים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003ב\u0004אופן \u0003שמשך צריכא למימר\u0004 \u0005[נצרכה לומר]?\u0006 הרי היה כאן קנין ממש! \u0003אלא כגון שיחד לו קרן זוית\u0004 לפירות שפסק, ודי בכך לענין זה.","\u0003ושמואל אמר:\u0004 זו שאמרו אם יש לו מותר \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר: צד אחד ברבית מותר,\u0004 שאם נעשתה עיסקה שבה אמנם עשוי המלוה לקבל תוספת על מה שהלוה, אלא שבשעת ההסכם אין ודאות שאכן יגיעו הדברים לידי ריבית — מותר.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיה נושה בחבירו מנה, ועשה לו\u0004 הלווה את \u0003שדהו מכר\u0004 עבור מנה זה. \u0003בזמן שהמוכר אוכל פירות\u0004 במשך כל הזמן עד שיפרע חובו — \u0003מותר\u0004 בוודאי. אבל אם ה\u0003לוקח\u0004 (הקונה) \u0003אוכל פירות\u0004 — \u0003אסור,\u0004 שהרי הלוקח (המלוה) מקבל ריבית (את פירות השדה) כל עוד לא ישולם החוב. \u0003ר' יהודה אומר: אף בזמן שהלוקח אוכל פירות מותר.\u0004","ומסופר, \u0003אמר להם ר' יהודה\u0004 לחכמים: \u0003מעשה בביתוס בן זונין שעשה שדהו מכר על פי\u0004 הוראתו של \u0003ר' אלעזר בן עזריה\u0004 ובאותו מקרה \u0003לוקח אוכל פירות היה! אמרו לו:\u0004 וכי \u0003משם\u0004 מביא אתה \u0003ראיה?!\u0004 להיפך היה מעשה: \u0003מוכר אוכל פרות היה, ולא לוקח.\u0004","ושאלו: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם],\u0006 כלומר, באיזה עקרון נחלקו? \u0003אמר אביי: צד אחד ברבית איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 שלדעת ר' יהודה אם יש רק צד אחד בריבית — מותר. \u0003רבא אמר: רבית על מנת להחזיר איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שלדעתו גם ר' יהודה לא התכוון שהלוקח־המלוה יכול ליהנות ולאכול את הפירות ללא כל תמורה, אלא שאם יפרע הלווה את החוב אכן ישלם המלוה תמורת הפירות שאכל, ואילו חכמים סבורים שכיון שלא נגמר המכר יש באכילת הפירות בינתיים משום ריבית.","\u0003אמר רבא: השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003אמר ר' ינאי:\u0004"],["\u0003מה לי הן ומה לי דמיהן אמרינן\u0004 \u0005[אומרים אנו]\u0006 ואיננו דורשים שיהא התשלום בפירות ממש, כמו כן \u0003מה לי דמיהן ומה לי הן\u0004 — \u0003נמי אמרינן\u0004 \u0005[גם כן אומרים אנו]\u0006 \u0003ופוסקין על שער שבשוק;\u0004 שאפשר לקבל פירות תמורת כסף, גם אם אין העיסקה נגמרת מיד. ולכן, כשקובע עם חבירו שיתן לו פירות בעתיד לפי השער הקיים עתה בשוק \u0003ואף על פי שאין לו\u0004 פירות בשעה זו, מכל מקום סומכים על כך, שאם יכול לקנותם — הריהם כאילו היו בידו.","\u0003איתיביה\u0004 \u0005[הקשו לו]\u0006 \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרבא:\u0004 הרי במפורש שנינו, \u0003כולם, אם יש לו\u0004 — \u0003מותר, אם אין לו – אסור! אמר להו\u0004 \u0005[להם]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 מדובר ב\u0003הלואה\u0004 והעיסקה נעשתה לאחר ההלוואה כדי לפרוע חוב, \u0003הכא זביני\u0004 \u0005[כאן\u0006 יש \u0005מכר]\u0006 ממשי בלא הלוואה כלל, ואין צד ריבית בכך.","ואילו \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003אמרו רבנן\u0004 \u0005[חכמים]\u0006 ש\u0003פוסקין על שער שבשוק ואף על פי שאין לו\u0004 — \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 הקונה למוכר: \u0003שקילא טיבותיך ושדייא אחיזרי\u0004 \u0005[נטולה טובתך ומוטלת על הקוצים],\u0006 כלומר, אין אתה עושה לי כל טובה. שכן \u0003מאי אהנית\u0004 \u0005[מה הועלת]\u0006 \u0003לי?\u0004 \u0003אי הוו\u0004 \u0005[אם היו]\u0006 \u0003לי זוזי\u0004 \u0005[זוזים,\u0006 כסף\u0005]\u0006 \u0003בידי הוה מזבנינא\u0004 \u0005[הייתי קונה]\u0006 \u0003ב\u0004עיירה \u0003היני וב\u0004עיירה \u0003שילי בזולא\u0004 \u0005[בזול],\u0006 ואם כן מה שאני מקבל לפי השער של השוק היום — איננו רווח עבורי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: אלא מעתה,\u0004 אם משתמשים בנימוק זה, יהא \u0003מותר ללות סאה בסאה, משום דמצי אמר ליה\u0004 \u0005[שיכול לומר לו\u0006 המלוה ללווה\u0005]:\u0006 \u0003שקילא טיבותיך ושדייא אחיזרי\u0004 \u0005[נטולה טובתך ומוטלת על הקוצים],\u0006 שאין אני מרוויח דבר על ידי הסאה שנתת לי לאחר זמן, שהרי אם היו החיטים בגורן, בידי — גם אז היה מחירן עולה, ולא הרווחתי דבר על ידי ההלוואה, \u0003דאמר ליה\u0004 \u0005[ש\u0006הוא \u0005אומר לו]:\u0006 וכי \u0003חטי דקדחי באכלבאי\u0004 \u0005[החיטים נשרפות במחסן שלי]?!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: יש להבדיל בין הדברים, \u0003התם\u0004 \u0005[שם]\u0006 מדובר ב\u0003הלואה\u0004 ויש לחשוש לריבית, \u0003הכא\u0004 \u0005[כאן]\u0006 — \u0003זביני\u0004 \u0005[מכר].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אדא בר אבא לרבא:\u0004 מה שאמר בענין פוסק על שער שבשוק, הרי בכל זאת מרוויח הקונה מן הפסיקה, שאילו היה הולך לקנות במקום אחר \u0003והא בעי למיתב זוזי לספסירא\u0004 \u0005[והרי\u0006 הוא \u0005צריך לתת דינר לסרסור\u0006 המתווך\u0005]\u0006 ונמצא שמרוויח דינר זה על ידי הקדמת התשלום! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003דקא יהיב ליה נמי\u0004 \u0005[ש\u0006אכן \u0005נותן לו גם כן],\u0006 שצריך הקונה להוסיף עוד דמי תיווך. \u0003רב אשי אמר:\u0004 אין צריך להוסיף דמי תיווך כי \u0003זוזי דאינשי אינהו עבדי ליה ספסירותיה\u0004 \u0005[דינריו של אדם הם עושים לו את התיווך],\u0006 וכאשר יש לאדם כסף מזומן בידו אין לו צורך בתיווך.","ועוד הלכה בנושא קרוב, \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003האי מאן דיהיב זוזי אתרעא חריפא\u0004 \u0005[מי שנותן זוזים,\u0006 כסף, \u0005בשער החריף],\u0006 כלומר, נותן את הכסף בהקדם, והוא יכול משום כך לקנות בזול יותר לפני שייקבע השער הרגיל, \u0003צריך לאיתחזויי לבי דרי\u0004 \u0005[צריך להראות עצמו בגורן]\u0006 בשעה שהמוכר דש את התבואה.","ושואלים: \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה צורך\u0005]\u0006 הוא בא? \u0003אי למקנא\u0004 \u0005[אם לקנות]\u0006 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא קני\u0004 \u0005[קנה],\u0006 שהרי בראיה בלבד אין הקנין נעשה, \u0003אי לקבולי עליה\u0004 \u0005[אם\u0006 לעשות שהמוכר \u0005יקבל על עצמו]\u0006 קללת \u0003\"מי שפרע\"\u0004 אם יחזור בו מן העיסקה, \u0003כי לא מיתחזי נמי\u0004 \u0005[כאשר אינו מראה עצמו גם כן]\u0006 הריהו \u0003מקבל עליה\u0004 \u0005[עליו]\u0006 קללת \u0003\"מי שפרע\"\u0004 \u0005[עליו]!\u0006","ומסבירים: \u0003לעולם\u0004 תפרש שהוא בא \u0003לקבולי עליה\u0004 \u0005[לקבל עליו]\u0006 \u0003\"מי שפרע\",\u0004 \u0003ו\u0004אולם יש טעם בדבר: \u0003מאן דיהיב זוזי אתרעא חריפא\u0004 \u0005[מי שנותן כסף בשער החריף]\u0006 \u0003לבי תרי תלתא יהיב\u0004 \u0005[לשנים\u0006 או \u0005שלושה\u0006 אנשים \u0005הוא נותן],\u0006 שהרי רצונו להבטיח את עצמו ברווח, \u0003אי מיתחזי ליה\u0004 \u0005[אם\u0006 הוא \u0005מתראה לו]\u0006 לבעל התבואה — \u0003סמכא דעתיה\u0004 \u0005[סומכת דעתו]\u0006 של המוכר, והוא יודע שהמקח גמור ומוחלט, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 יבוא הקונה, \u0003אמר ליה\u0004 \u0005[אומר,\u0006 יכול המוכר לומר \u0005לו\u0006\u0005]:\u0006 \u0003אמינא דאשכחת פירי דשפירי מדידי ושקלת\u0004 \u0005[אמרתי\u0006 בלבי \u0005שמצאת פירות יפים משלי ולקחת]\u0006 ובטלת את ההסכם אתי, ולכן אם אין המוכר בטוח בקנין, רשאי הוא לחזור בו.","\u0003אמר רב אשי: השתא דאמרת\u0004 \u0005[עכשיו שאת אומר]\u0006 שהטעם הוא \u0003משום מסמך דעתא\u0004 \u0005[סמיכת הדעת],\u0006 כדי שיהא המוכר בטוח שהקונה אכן עומד בקניינו — אינו צריך ללכת דווקא לגורן, \u0003אלא\u0004 \u0003אפילו\u0004 אם \u0003אשכחיה בשוקא\u0004 \u0005[מצאו בשוק]\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 שעומד בדברו — גם כן \u0003סמכא דעתיה\u0004 \u0005[\u0006\u0005סומכת דעתו].\u0006","\u0003אמר רב נחמן; כללא דריביתא\u0004 \u0005[כלל\u0006 בדיני \u0005ריבית]\u0006 הוא: \u0003כל אגר נטר ליה\u0004 \u0005[שכר\u0006 עבור \u0005המתנה],\u0006 שמוסיף תשלום על שאין המלוה גובה את הכסף עכשיו — \u0003אסור. ואמר רב נחמן: האי מאן דיהיב זוזי לקיראה\u0004 \u0005[מי שנותן כסף למוכר\u0006 חלות \u0005שעוה]\u0006 \u0003וקא אזלי\u0004 \u0005[והם הולכים,\u0006 השער הוא\u0005]\u0006 \u0003ארבע ארבע\u0004 חלות בזוז, \u0003ואמר ליה\u0004 \u0005[לו]\u0006 המוכר: \u0003יהיבנא\u0004 \u0005[אני נותן]\u0006 \u0003לך חמש חמש\u0004 אם תשלם לי עכשיו, הרבה לפני זמן נתינת השעוה, אם \u0003איתנהו גביה\u0004 \u0005[ישנן אצלו]\u0006 חלות שעוה בשעה זו — \u0003שרי\u0004 \u0005[מותר],\u0006 שהוא מוכר בזול משום שהוא זקוק עתה לכסף מזומן. אבל אם \u0003ליתנהו גביה\u0004 \u0005[אינן אצלו]\u0006 — \u0003אסור,\u0004 שהרי הוא משלם חלה נוספת בריבית.","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 והרי זו ריבית ברורה! ודוחים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא למקרה \u0003דאית ליה\u0004 \u0005[שיש לו,\u0006 למוכר\u0005]\u0006 \u0003אשראי במתא\u0004 \u0005[בעיר]\u0006 ויכול לקבל שעוה מאנשים אחרים שמהם קנה. \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003אשראי במתא\u0004 \u0005[בעיר]\u0006 ויכול לקבל את השעוה הרי זה כמו האומר \u0003\"\u0004הלויני \u0003עד שיבא בני\" או \"עד שאמצא מפתח\" דמי\u0004 \u0005[נחשב],\u0006 שמותר לתת לו כסף, שאין אנחנו רואים בכך הלוואה, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב נחמן כי \u0003כיון דמחסרי גוביינא\u0004 \u0005[ש\u0006עדיין \u0005חסרים גבייה]\u0006 — \u0003כמאן דליתנהו דמי\u0004 \u0005[כמי שאינם הם נחשבים],\u0006 ויש בהוזלת המחיר משום ריבית.","\u0003ו\u0004עוד \u0003אמר רב נחמן: האי מאן דאוזיף פשיטי מחבריה\u0004 \u0005[מי שלווה מטבעות מחבירו]\u0006 ואחר כך כשספר \u0003אשכח ביה טופיינא\u0004 \u0005[מצא בהן תוספת]\u0006 שנתן לו יותר ממה שאמר \u0003אי\u0004 \u0005[אם]\u0006 התוספת היתה \u0003ב\u0004שיעור \u0003כדי שהדעת\u0004 יכולה להיות \u0003טועה,\u0004 ויש לשער שהמלוה טעה בחשבון — \u0003מיחייב לאהדוריה ליה\u0004 \u0005[חייב להחזיר לו],\u0006 \u0003ואי לאו\u0004 \u0005[ואם לא],\u0006 שהיה ההבדל גדול יותר, עד שברור שלא היתה כאן טעות — \u0003מתנה בעלמא\u0004 \u0005[סתם]\u0006 \u0003הוא דיהיב ליה\u0004 \u0005[שנתן לו].\u0006","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק]\u0006 הוא המקרה שאנו אומרים \u0003\"בכדי שהדעת טועה\"? אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף:\u0004"],["\u0003בעישורייתא וחומשייתא\u0004 \u0005[בעשרות וחמישיות],\u0006 שיש לשער שבעל הכסף מנה עשר עשר או חמש חמש וטעה בספירה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: ואי\u0004 \u0005[ואם]\u0006 הנותן \u0003איניש תקיפא\u0004 \u0005[אדם תקיף]\u0006 \u0003הוא דלא יהיב\u0004 \u0005[שאיננו\u0006 נוהג \u0005לתת]\u0006 בדרך כלל \u0003מתנה מאי\u0004 \u0005[מה\u0006 נאמר\u0005]?\u0006 האם נניח שהיתה זאת טעות? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דלמא מיגזל גזליה ואבלע ליה\u0004 \u0005[שמא\u0006 פעם \u0005גזל ממנו ו\u0006עכשיו \u0005הבליע לו]\u0006 \u0003בחשבון\u0004 את דמי הגזילה בלא לפרש שהוא משיב לו את גזילו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הגוזל את חבירו והבליע לו\u0004 את סכום הגזילה \u0003בחשבון\u0004 של סכום אחר שחייב לו, והחזיר לו בדרך זו — \u0003יצא\u0004 ידי חובת השבת הגזילה.","ושואלים: \u0003ואי איניש דאתי מעלמא,\u0004 \u0005[אם\u0006 היה הנותן \u0005אדם שבא מבחוץ]\u0006 ש\u0003לא שקיל וטרי בהדיה, מאי\u0004 \u0005[נשא ונתן אתו, מה]?\u0006 האין זו הוכחה שהיתה זו טעות? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דלמא איניש אחרינא גזליה,\u0004 \u0005[שמא אדם אחר,\u0006 ממכריו \u0005גזלו]\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 לאיש הזה: \u0003כי יזיף\u0004 \u0005[כאשר ילוה]\u0006 \u0003פלוני פשיטי מינך\u0004 \u0005[מטבעות\u0006 כסף \u0005ממך]\u0006 — \u0003אבלע ליה\u0004 \u0005[הבלע לו]\u0006 \u0003בחשבון,\u0004 שיתכן שנקט בדרך זו של השבת הגזילה כדי שלא להתבייש בכך.","\u0003אמר רב כהנא: הוה יתיבנא בשילהי פרקי\u0004 \u0005[הייתי יושב בקצה\u0006 בית \u0005המדרש]\u0006 של \u0003רב, ושמעית דקאמר \"קרי קרי\"\u0004 \u0005[ושמעתי שאמר \"דלעות דלעות\"]\u0006 \u0003ולא ידענא מאי קאמר\u0004 \u0005[ידעתי מהו אומר],\u0006 שלא שמע במה היה מדובר. \u0003בתר דקם\u0004 \u0005[אחר שעמד]\u0006 \u0003רב\u0004 ממקומו ויצא, \u0003אמרי להו\u0004 \u0005[אמרתי להם]\u0006 לתלמידים: \u0003מאי \"קרי קרי\" דקאמר\u0004 \u0005[מה הן \"דלעות דלעות\" שאמר]\u0006 \u0003רב?\u0004","\u0003אמרו לי: הכי קאמר\u0004 \u0005[כך אמר]\u0006 \u0003רב: האי מאן דיהיב זוזי לגינאה אקרי\u0004 \u0005[מי שנתן כסף לגנן\u0006 עבור \u0005דלעות],\u0006 \u0003וקא אזלי עשרה קרי בני זרתא\u0004 \u0005[והולכות,\u0006 המחיר הרגיל שמשלמים הוא, \u0005עשר דלעות בנות\u0006 אורך של \u0005זרת]\u0006 בדינר \u0003ואמר ליה\u0004 \u0005[לו]\u0006 הגנן לקונה: אם תיתן לי עכשיו את הכסף \u0003יהבינא לך בני גרמידא\u0004 \u0005[אתן לך\u0006 דלעות באורך \u0005אמה]\u0006 לאחר זמן באותו מחיר, במקרה זה, אם \u0003איתנהו\u0004 \u0005[ישנן\u0006 בידו\u0005]\u0006 — \u0003שרי\u0004 \u0005[מותר],\u0006 ואם \u0003ליתנהו\u0004 \u0005[אינן\u0006 בידו\u0005]\u0006 — \u0003אסור,\u0004 שאם יתן לו דלעות גדולות לאחר זמן במחיר של דלעות קטנות יש בכך משום ריבית.","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא, ומה חידש רב? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון דממילא קא רבו\u0004 \u0005[שמעצמן הן גדלות]\u0006 — \u0003שפיר דמי\u0004 \u0005[יפה הדבר],\u0006 שאין הגנן בא ומוסיף דבר חדש אלא רק ממתין לגידול הדלעות מעצמן ואינו עושה מעשה, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב שאף זה נקרא ריבית.","ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 היא הלכה זו שאמר רב בענין הדלעות — \u0003כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ההולך לחלוב את עזיו, ולגזוז את רחליו, ולרדות את כוורתו, מצאו חבירו ואמר לו\u0004 החקלאי לחבר: \u0003מה שעזי חולבות מכור לך, מה שרחלי גוזזות מכור לך, מה שכוורתי רודה מכור לך,\u0004 וכל זאת בעד סכום מסויים, בלא לדעת בדיוק כמה יקבל הקונה — הרי זה \u0003מותר.\u0004","\u0003אבל אם אמר לו: מה שעזי חולבות, כך וכך מכור לך, מה שרחלי גוזזות כך וכך מכור לך, מה שכוורתי רודה כך וכך מכור לך\u0004 — \u0003אסור,\u0004 שכן הוא מוסיף על הכמות בשל הקדמת התשלום. \u0003ואף על גב דממילא קא רבו\u0004 \u0005[ואף על פי שמעצמם הם גדלים],\u0006 \u0003כיון דליתנהו בההיא שעתא\u0004 \u0005[שאנם\u0006 נמצאים \u0005באותה שעה]\u0006 — \u0003אסור.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003אמר רבא:\u0004 ההלכה היא \u0003כיון דממילא קא רבו\u0004 \u0005[שמעצמם הם גדלים]\u0006 — \u0003שפיר דמי\u0004 \u0005[יפה הדבר,\u0006 מותר\u0005]\u0006 ואין בכך משום ריבית. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שאם אמר לו \u0003\"\u0004מה שעיזי חולבות... \u0003כך וכך\"\u0004 — \u0003אסור!\u0004","ומשיבים: יש לחלק, \u0003התם לאו מיניה קא רבו\u0004 \u0005[שם\u0006 בחלב ובצמר \u0005לא ממנו\u0006 עצמו \u0005הוא גדל],\u0006 שאינו נותן לו בעתיד מן החלב הנמצא כעת, \u0003דשקלי ליה להאי ואתי אחרינא בדוכתיה\u0004 \u0005[ש\u0006הרי \u0005לוקחים\u0006 חלב \u0005זה ובא אחר במקומו].\u0006 \u0003הכא מיניה קא רבו\u0004 \u0005[כאן,\u0006 כגון בדלעות, \u0005ממנו\u0006 עצמו \u0005הן גדלות],\u0006 \u0003דכי שקלי ליה להאי\u0004 \u0005[ש\u0006הרי \u0005כאשר\u0006 לוקחים מזה] \u0003לא אתי אחרינא בדוכתיה\u0004 \u0005[בא אחר במקומו],\u0006 ולכן כשמוכר לו את הפרי עכשיו הרי כל שמוסיף וגדל פרי זה — כאילו היה כל הזמן ברשות הקונה.","\u0003אמר אביי: שרי ליה לאיניש למימר ליה לחבריה\u0004 \u0005[מותר לו לאדם לומר לו לחבירו]:\u0006 \u0003הילך ארבעה זוזי אחביתא דחמרא\u0004 \u0005[זוזים\u0006 עבור \u0005חבית יין],\u0006 \u0003אי תקפה\u0004 \u0005[אם תחמיץ]\u0006 — הרי היא \u0003ברשותך\u0004 ואחריותך עליה, \u0003אי יקרא אי זילא\u0004 \u0005[אם תתייקר או תוזל]\u0006 — הרי היא \u0003ברשותי,\u0004 שאני מקבל עלי את אחריות ההפסד אם יוזל המחיר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שרביא לאביי:\u0004"],["\u0003האי\u0004 \u0005[זה]\u0006 עסק \u0003קרוב לשכר ורחוק להפסד הוא,\u0004 שהרי את חשש ההחמצה מקבל המוכר על עצמו וכבר אמרנו שכל עיסקה כזו אינה אלא ריבית! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003כיון\u0004 ש\u0003מקבל עליה זולא\u0004 \u0005[עליו\u0006 הקונה את ההפסד אם \u0005יוזל\u0006 המחיר\u0005],\u0006 אם כן \u0003קרוב לזה ולזה הוא,\u0004 שיש כאן גם סיכוי של רווח וגם הפסד, ויש לראות בכך עיסקה הוגנת.","\u0003המלוה את חבירו לא ידור בחצרו\u0004 של הלווה \u0003חנם, ולא ישכור ממנו\u0004 לדור בחצר \u0003בפחות\u0004 מן השכר הרגיל — \u0003מפני שהוא רבית,\u0004 שהרי נמצא שהוא מקבל ממנו בצורה זו ריבית.","\u0003אמר רב יוסף בר מניומי אמר רב נחמן: אף על פי שאמרו\u0004 חכמים ש\u0003הדר בחצר חבירו שלא מדעתו\u0004, בלא שבעל החצר יודע — \u0003אינו צריך להעלות לו שכר\u0004 (לשלם) אם ההוא אינו מפסיד דבר על ידי כך, מכל מקום אם \u0003הלוהו ודר בחצירו\u0004 — \u0003צריך להעלות לו שכר.\u0004 ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]?\u0006 הלא \u0003תנינא\u0004 \u0005[שנינו]\u0006 זאת במפורש במשנה: \u0003המלוה את חבירו לא ידור בחצירו חנם, ולא ישכור ממנו בפחות, מפני שהוא רבית!\u0004","ודוחים: משם אין ראיה, \u0003אי ממתניתין הוה אמינא\u0004 \u0005[אם ממשנתנו הייתי אומר\u0006 ומפרש\u0005]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003בחצר דקיימא לאגרא\u0004 \u0005[העומדת להשכרה],\u0006 \u0003וגברא דעביד למיגר\u0004 \u0005[ובאדם העומד לשכור],\u0006 שאם לא ימצא דירה שם — ישכור במקום אחר, ואז ברור שהוא חייב לשלם. \u0003אבל חצר דלא קיימא לאגרא, וגברא דלא עביד למיגר\u0004 \u0005[חצר שאינה עומדת להשכרה, ואדם שאינו עומד לשכור]\u0006 כרגיל, שאז לכאורה לא הפסיד בעל החצר דבר, והדייר אינו מרוויח דבר — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ישלם כלל, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבמקרה זה עליו לשלם שלא ייראה כריבית.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 בנוסח אחר: \u0003אמר רב יוסף בר מניומי אמר רב נחמן: אף על פי שאמרו\u0004 כי \u0003הדר בחצר חבירו שלא מדעתו\u0004 — \u0003אינו צריך להעלות לו שכר,\u0004 אם אמר לו \u0003\"הלויני ודור בחצרי\"\u0004 — \u0003צריך להעלות לו שכר.\u0004","ומסבירים את ההבדל בין שתי הנוסחות: \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שחייב בתשלום אם \u0003הלוהו\u0004 — \u0003כל שכן\u0004 כאשר אמר במפורש \u0003\"הלויני\",\u0004 שעשה זאת כתנאי וכעין ריבית. אבל ל\u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 על הנוסח \u0003\"הלויני\",\u0004 הרי דווקא כזה אמר, \u0003אבל אם הלוהו\u0004 ולא פירש לו — \u0003לא. מאי טעמא\u0004 \u0005[מה טעם]?\u0006 — \u0003כיון דמעיקרא לאו אדעתא דהכי אוזפיה\u0004 \u0005[שמתחילה לא על דעת זה הלווהו]\u0006 — \u0003לית לן בה\u0004 \u0005[אין לנו בו\u0006 איסור\u0005]\u0006 ואפשר לומר שאין קשר בין ההלוואה ובין הדירה בחצרו.","מסופר: \u0003רב יוסף בר חמא\u0004 אביו של רבא \u0003תקיף עבדי דאינשי דמסיק בהו זוזי, ועביד בהו עבידתא\u0004 \u0005[היה תופס עבדיהם של אנשים ש\u0006הוא \u0005נושה בהם כסף ו\u0006היה \u0005עובד בהם עבודה],\u0006 שכאשר ראה שהם הולכים בטל היה כופה אותם לעבוד עבורו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בריה\u0004 \u0005[בנו]:\u0006 \u0003מאי טעמא עביד מר הכי\u0004 \u0005[מה טעם עושה אדוני כך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003כרב נחמן סבירא לי\u0004 \u0005[סובר אני],\u0006 ש\u0003אמר רב נחמן: עבדא, נהום כריסיה לא שוי\u0004 \u0005[העבד, את הלחם\u0006 שהולך \u0005לכרסו איננו שווה],\u0006 שעבודת עבדים אינה משתלמת כלל. משום כך, אם אני לוקח עבד ומעבידו ומפרנס אותו — אינני מרוויח רווח ממשי בדבר, ולכן יכול אני לעשות כן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר רב נחמן\u0004 דבר זה — \u0003כגון דארי עבדיה דמרקיד בי כובי\u0004 \u0005[עבדו שהיה רוקד בבית מרזח]\u0006 ובאמת לא היה שווה לאדוניו, אבל בענין \u0003עבדי אחריני מי\u0004 \u0005[עבדים אחרים האם]\u0006 \u0003אמר\u0004 כן? \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביו: \u0003אנא, כי הא\u0004 \u0005[אני, כזו]\u0006 שאמר \u0003רב דניאל בר רב קטינא\u0004 ש\u0003אמר\u0004 בשם \u0003רב סבירא לי\u0004 \u0005[אני סובר].\u0006 ש\u0003אמר: התוקף\u0004 (האוחז) \u0003עבדו של חבירו ועשה בו מלאכה\u0004 — \u0003פטור.\u0004 ואין לראות בכך משום גזילה, משום"],["\u0003דניחא ליה\u0004 \u0005[שנוח לו,\u0006 לבעל העבד\u0005]\u0006 בכך כדי ש\u0003לא נסתרי עבדיה\u0004 \u0005[יתקלקל עבדו],\u0006 שיתרגל ללכת בטל בלא עבודה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003היכא דלא מסיק ביה זוזי\u0004 \u0005[שאינו נושה בו כספים],\u0006 אבל \u0003מר\u0004 \u0005[אדוני]\u0006 \u0003כיון דמסיק בהו זוזי מחזי\u0004 \u0005[ש\u0006הוא \u0005נושה בהם כספים, נראה\u0006 הדבר\u0005]\u0006 \u0003כרבית.\u0004 שהרי \u0003אמר רב יוסף בר מניומי אמר רב נחמן: אף על פי שאמרו\u0004 ש\u0003הדר בחצר חבירו שלא מדעתו\u0004 — \u0003אינו צריך להעלות לו שכר,\u0004 בכל זאת אם \u0003הלוהו ודר בחצירו\u0004 — \u0003צריך להעלות לו שכר.\u0004 משמע, שאפילו דבר המותר באופן אחר, במקרה של הלוואה, אסור מפני חשש ריבית. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הדרי בי\u0004 \u0005[חוזר אני בי]\u0006 ולא אעשה כן עוד.","\u0003אמר אביי: האי מאן דמסיק זוזי דריביתא בחבריה\u0004 \u0005[מי שנושה כספים של ריבית בחבירו],\u0006 \u0003וקא אזלי חטי\u0004 \u0005[והולכים,\u0006 נמכרים, \u0005חיטים]\u0006 ב\u0003ארבעה גריוי בזוזא בשוקא\u0004 \u0005[סאים בזוז בשוק],\u0006 \u0003ויהיב ליה איהו\u0004 \u0005[ונותן לו הוא,\u0006 הלווה\u0005]\u0006 \u0003חמשה\u0004 סאים בסלע כתשלום הריבית, \u0003כי מפקינן מיניה\u0004 \u0005[כאשר מוציאים אנו\u0006 בבית דין \u0005ממנו]\u0006 את הריבית שלקח — \u0003ארבעה\u0004 סאים \u0003מפקינן מיניה\u0004 — \u0005[אנחנו מוציאים,\u0006 לוקחים \u0005ממנו]\u0006 כי \u0003אידך\u0004 \u0005[השאר],\u0006 הסאה הנוספת — \u0003אוזולי\u0004 \u0005[הוזלה]\u0006 \u0003הוא דקא מוזיל גביה\u0004 \u0005[שהוזיל לו]\u0006 ואם כי עשה לו טובה, אין לראות בזה חלק מן הריבית. ואילו \u0003רבא אמר: חמשה\u0004 סאים\u0005]\u0006 \u0003מפקינן מיניה\u0004 \u0005[\u0006\u0005מוציאים אנו ממנו],\u0006 \u0003דמעיקרא בתורת ריביתא אתאי לידיה\u0004 \u0005[שמתחילה בתורת ריבית בא\u0006 הדבר \u0005לידו]\u0006 ואם כן הכל ריבית.","\u0003ו\u0004עוד \u0003אמר אביי: האי מאן דמסיק\u0004 \u0005[מי שנושא]\u0006 \u0003ארבעה זוזי דריביתא בחבריה\u0004 \u0005[זוזים של ריבית בחבירו]\u0006 \u0003ויהיב ליה\u0004 \u0005[ונותן לו]\u0006 \u0003גלימא בגוייהו\u0004 \u0005[יחד אתם],\u0006 \u0003כי מפקינן מיניה\u0004 \u0005[כאשר מוציאים אנו ממנו]\u0006 את הריבית שקיבל שלא כדין — \u0003ארבעה\u0004 זוזים \u0003מפקינן מיניה\u0004 \u0005[מוציאים אנו ממנו],\u0006 את ה\u0003גלימא לא מפקינן מיניה\u0004 \u0005[אין אנו מוציאים ממנו],\u0006 ורואים זאת כעיסקה של מכירה. \u0003רבא אמר:\u0004 את ה\u0003גלימא מפקינן מיניה\u0004 \u0005[מוציאים אנו ממנו].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 — \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא לימרו\u0004 \u0005[יאמרו]\u0006 שה\u0003גלימא דמכסי וקאי\u0004 \u0005[ש\u0006פלוני \u0005מתכסה והולך]\u0006 בה \u0003גלימא דריביתא הוא\u0004 \u0005[של ריבית היא].\u0006","\u0003אמר רבא: האי מאן דמסיק תריסר זוזי דריביתא בחבריה\u0004 \u0005[מי שנושה שנים עשר זוזים של ריבית בחבירו]\u0006 \u0003ואגר ליה\u0004 \u0005[והשכיר לו]\u0006 הלווה \u0003חצר דמתגרא\u0004 \u0005[שנשכרת\u0006 כרגיל\u0005]\u0006 \u0003בעשרה\u0004 זוזים \u0003ואוגריה נהליה בתריסר\u0004 \u0005[והשכירה לו בתריסר]\u0006 וסכום זה היווה את תשלום הריבית, \u0003כי מפקינן מיניה\u0004 \u0005[כאשר מוציאים אנו ממנו,\u0006 מן המלווה\u0005]\u0006 את הריבית — \u0003תריסר מפקינן מיניה\u0004 \u0005[שנים עשר זוזים מוציאים אנו ממנו],\u0006 שהרי זה היה סכום הריבית שנתחייב לו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 המלווה ללווה: אם הייתי שוכר אותה עכשיו הייתי מוכן לוותר לו, \u0003כי אגרא הכי\u0004 \u0005[כששכרתי כך]\u0006 במחיר גבוה יותר כיון \u0003דהוה קא משתרשי לי\u0004 \u0005[שהיה לי רווח\u0006 בה\u0005]\u0006 משום הריבית, \u0003השתא דלא משתרשי לי כדאגרי כולי עלמא הוא דאגרנא\u0004 \u0005[\u0006\u0005עכשיו שאינני\u0006 מרוויח בריבית, \u0005כמו ששוכרים כל העולם הוא שאני שוכר],\u0006 והרי הכל שוכרים בעשרה! ודוחים: \u0003משום\u0004 ש\u0003אמר ליה\u0004 \u0005[\u0006\u0005שאומרים לו]\u0006 למלווה\u0005:\u0006 הרי \u0003סברת וקבלת\u0004 על עצמך, ומדעתך, להחשיב זאת בתריסר.","\u0003מרבין על השכר\u0004 ומוסיפים כסף אם משלמים את דמי השכירות במאוחר \u0003ואין מרבין על המכר. כיצד? השכיר לו את חצרו, ואמר לו\u0004 המשכיר: \u0003\"אם מעכשיו אתה נותן לי\u0004 את דמי השכירות — \u0003הרי הוא לך בעשר סלעים לשנה, ואם של חודש בחודש\u0004 אתה משלם לי \u0003סלע לחודש\",\u0004 שנמצא מקבל במשך השנה שנים עשר סלעים הרי זה \u0003מותר,\u0004 אף שהוא מקבל יותר בשל איחור בתשלום. ואולם אם \u0003מכר לו את שדהו, ואמר לו: \"אם מעכשיו אתה נותן לי\u0004 — \u0003הרי היא שלך באלף זוז,\u0004 ו\u0003אם ל\u0004שעת ה\u0003גורן\u0004 אתה נותן לי הרי היא \u0003בשנים עשר מנה\u0004 (אלף ומאתיים זוז) \u0003\"\u0004— \u0003אסור\u0004 משום ריבית.","שואלים: \u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[במה שונה ההתחלה ובמה שונה הסוף],\u0006 מדוע בשכירות הדבר מותר, ובמכר נחשב הדבר לריבית? ומשיבים: \u0003רבה ורב יוסף, דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 כלל הוא ש\u0003שכירות אינה משתלמת אלא בסוף,\u0004 שמעיקר הדין זמן תשלום עבור שכירות הוא בסוף לאחר שגומרים את השכירות, \u0003והאי\u0004 \u0005[וזה]\u0006 \u0003כיון\u0004 ש\u0003לא מטא זמניה למיגבא\u0004 \u0005[הגיע זמנו לגבות]\u0006 בתחילה ההשכרה — \u0003לאו אגר נטר ליה\u0004 \u0005[לא שכר של המתנה לו]\u0006 הוא שמקבל, אלא להיפך, \u0003משווא הוא דהכי שויא\u0004 \u0005[זה הוא השווי שהוא שווה]\u0006 כפי המחיר הגבוה יותר, \u0003והאי דקאמר ליה\u0004 \u0005[וזה שאומר לו]\u0006 \u0003\"אם מעכשיו אתה נותן לי\u0004 — \u0003הרי הוא לך בעשר סלעים לשנה\"\u0004 — \u0003אוזולי\u0004 \u0005[הוזלה]\u0006 \u0003הוא דקא מוזיל גביה\u0004 \u0005[שמוזיל אצלו],\u0006 משום שמקבל כסף הרבה לפני הזמן, ואין זו ריבית.","ואילו \u0003סיפא\u0004 \u0005[בסוף],\u0006 \u0003כיון דזביני נינהו\u0004 \u0005[שמכר הוא]\u0006 \u0003ובעי למשקל דמי\u0004 \u0005[וצריך לקחת כסף]\u0006 \u0003מעכשיו\u0004 אם משלם לו יותר לאחר זמן, \u0003הלכך אגר נטר ליה\u0004 \u0005[שכר\u0006 המתנה לו] \u0003הוא, ואסור.\u0004 \u0003אמר רבא: דקו בה רבנן בהא מילתא ואוקמוה אקרא\u0004 \u0005[דקדקו חכמים בדבר זה והעמידוהו,\u0006 למדוהו, \u0005מן הכתוב],\u0006 שנאמר: \u0003\"כשכיר שנה בשנה\"\u0004 (ויקרא כה, נג), ללמד: \u0003שכירות של שנה זו אינה משתלמת אלא בשנה אחרת,\u0004 הרי שיש בכתוב ראיה למה שאמרנו קודם.","שנינו במשנה שאם ימתין וישלם לו בשעת ה\u0003גורן בשנים עשר מנה\u0004 — \u0003אסור. אמר רב נחמן: טרשא שרי\u0004 \u0005[הסכם מכירה מותר].\u0006 כלומר, מותר לעשות חוזה מכירה שתהיה בו תוספת מחיר עבור תשלום מאוחר, אם איננו מפרש שבשכר המתנת הכסף הוא מקבל יותר, אלא קוצב סתם מחיר וזמן פרעון.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רמי בר חמא לרב נחמן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב עוקבא בר חמא\u0004 שהקשה \u0003לרב נחמן,\u0004 שנינו: \u0003ואם לגורן בשנים עשר מנה\u0004 — \u0003אסור! אמר ליה\u0004 \u0005[לו]:\u0006 יש להבדיל; \u0003התם\u0004 \u0005[שם]\u0006 — \u0003קץ ליה\u0004 \u0005[קצץ לו],\u0006 שהרי פירש ואמר שלאחר זמן יהא מחיר גבוה יותר, והרי זו ריבית, \u0003הכא\u0004 \u0005[כאן]\u0006 — \u0003לא קץ ליה\u0004 \u0005[קצץ לו]\u0006 ויש בכך תוספת בלא ריבית ברורה.","\u0003אמר רב פפא: טרשא דידי שרי\u0004 \u0005[הסכם מחירה שלי\u0006 שאני עושה בשיכר בוודאי \u0005מותר],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003שכראי לא פסיד\u0004 \u0005[השיכר שלי איננו נפסד]\u0006 אם הייתי משאיר אותו ברשותי למשך זמן ומוכר אותו אז ביוקר, \u0003זוזי לא צריכנא\u0004 \u0005[כסף אין אני צריך]\u0006 כעת, אלא \u0003אנא\u0004 \u0005[אני]\u0006 \u0003הוא דקא עבידנא מילתא גבי לוקח\u0004 \u0005[שעושה דבר,\u0006 טובה, \u0005לקונה]\u0006 שאני מוכר לו בלא לקבל כסף מיד. ואם כן, בעצם אין כאן רווח של ריבית.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי לרב פפא: מאי חזי מר דקא אזלת בתר דידך\u0004 \u0005[מה רואה אדוני שאתה הולך אחרי עצמך]\u0006 אחרי הצד שלך בנושא, שמבחינתך אין בכך רווח של ריבית?! \u0003זיל בתר דידהו\u0004 \u0005[לך אחר הצד שלהם]\u0006 של הקונים ממך, ש\u0003אילו הוו להו זוזי\u0004 \u0005[היו להם זוזים,\u0006 כסף\u0005]\u0006 — \u0003הוו שקלי כי השתא\u0004 \u0005[היו לוקחים כפי\u0006 המחיר של \u0005עכשיו],\u0006 \u0003השתא דלית להו זוזי\u0004 \u0005[עכשיו שאין להם זוזי,\u0006 כסף\u0005]\u0006 — \u0003שקלי כיוקרא דלקמיה\u0004 \u0005[הם לוקחים לפי היוקר\u0006 שיהיה \u0005בעתיד\u0006\u0005],\u0006 ונמצא שהם משלמים ריבית עבור ההמתנה בפרעון הכסף!","\u0003אמר רב חמא: טרשא דידי\u0004 \u0005[הסכם המכירה שלי]\u0006 \u0003ודאי שרי\u0004 \u0005[מותר],\u0006 שהיה עושה הסכמי מכירה במקום שבו הסחורה בזול, והיה מוכר אותה לפי השער של מקום שהיא עולה ביוקר, והקונים היו מביאים את סחורתם למקום בו היא עולה ביוקר ומוכרים אותה שם במחיר הגבוה ביותר, והוא היה מקבל עליו אחריות מסויימת עבור הסיכונים שבדרך, ומשום כך יש בכך משום עיסקת שותפות מכירה ולא ריבית.","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003ניחא להו דליקו ברשותי\u0004 \u0005[נוח להם\u0006 שתהא הסחורה נחשבת \u0005כעומדת ברשותי],\u0006 שב\u0003כל היכא דקא אזלי\u0004 \u0005[מקום שהם הולכים]\u0006 — \u0003שבקי להו מכסא ונקוט להו שוקא\u0004 \u0005[מניחים להם\u0006 מן \u0005המכס ומחזיקים להם את השוק],\u0006 שנותנים להם זכות קדימה במכירה, לפי שהיה רב חמא מחכמי בית ראש הגולה, והיו הכל מסייעים בידו. ונמצא שהם מרוויחים בעיסקה זו, ואף שהם משלמים יותר — הרי הם משלמים עבור הרווח שיש להם על ידי העיסקה אתו."],["\u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כרב חמא\u0004 שטרשא שעשה מותרת, \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כר' אלעזר\u0004 שריבית קצוצה מוציאים מן המלוה אף בבית דין, \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כר' ינאי,\u0004 ש\u0003אמר מה לי הן ומה לי דמיהן,\u0004 שאם מוסר לחבירו חפץ או כסף עבור מה שהלווהו יש בכך משום מכר ולא ריבית.","\u0003מכר לו את השדה, ונתן לו\u0004 הקונה \u0003מקצת דמים, ואמר לו\u0004 המוכר לקונה: \u0003אימתי שתרצה הבא מעות\u0004 שאתה חייב לגמור התשלום \u0003וטול את שלך\u0004 — \u0003אסור,\u0004 כי בינתיים משתמש המוכר בשדה, ויש כאן כעין ריבית. אם \u0003הלוהו\u0004 כסף \u0003על שדהו, ואמר לו: אם אי\u0004 (אין) \u0003אתה נותן לי מכאן ועד שלש שנים\u0004 את פרעון החוב — \u0003הרי היא,\u0004 השדה, \u0003שלי\u0004 — \u0003הרי היא,\u0004 השדה, \u0003שלו. וכך היה ביתוס בן זונין עושה\u0004 בהלוואותיו \u0003על פי\u0004 דעת \u0003חכמים.\u0004","הלכה זו במשנה אינה ברורה למדי, כי יש כאן מקום לשאלה עיקרית: במכר זה, שהקונה שילם רק מקצת דמים \u0003מי אוכל פירות\u0004 השדה הזה בזמן הביניים עד לביצועו של התשלום כולו? \u0003רב הונא אמר: מוכר אוכל פירות\u0004 עד שיקבל את כל דמי השדה. \u0003רב ענן אמר:\u0004 בינתיים \u0003משלשין\u0004 (מפקידים) \u0003את הפירות.\u0004 ומעירים: \u0003ולא פליגי\u0004 \u0005[נחלקו]\u0006 רב הונא ורב ענן, \u0003הא דאמר\u0004 \u0005[זה\u0006 מדובר \u0005כשאומר\u0006 המוכר\u0005]:\u0006 \u0003לכי מייתית קני\u0004 \u0005[כאשר תביא\u0006 הכל \u0005תקנה\u0006 את השדה\u0005],\u0006 ולכן כל עוד לא הביא את יתרת הסכום עדיין שייכת השדה למוכר ורשאי הוא לאכול מפירותיה. \u0003הא דאמר\u0004 \u0005[\u0006ו\u0005זה כשאומר]:\u0006 \u0003לכי מייתית קני\u0004 \u0005[כאשר תביא\u0006 את הכסף \u0005קנה]\u0006 לך \u0003מעכשיו.\u0004","ומספרים: \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב ספרא ב\u0004הלכות \u0003רבית\u0004 שנשנו בברייתא \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' חייא\u0004 סיכום זה: \u0003פעמים ששניהם מותרין,\u0004 שאין בכך כל איסור ריבית, \u0003פעמים ששניהם אסורין, ופעמים שהמוכר מותר ולוקח אסור, ופעמים שהלוקח מותר ומוכר אסור.\u0004","כאשר שנה רב ספרא ברייתא זו, \u0003עני\u0004 \u0005[ענה]\u0006 \u0003רבא בתריה\u0004 \u0005[אחריו]\u0006 והסביר את הדברים: \u0003פעמים ששניהם מותרין\u0004 — כשעשו הסכם כגון \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המוכר: \u0003קני\u0004 \u0005[קנה]\u0006 לך מהשדה \u0003כשיעור זוזך\u0004 \u0005[כספך],\u0006 שאז למעשה הוא קונה חלקים קטנים של השדה מעט מעט, ובזה ודאי שאין איסור. \u0003פעמים ששניהם אסורין\u0004 — \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המוכר: \u0003לכי מייתית קני\u0004 \u0005[כאשר תביא\u0006 את הכסף \u0005תקנה]\u0006 את הכל \u0003מעכשיו,\u0004 שאם המוכר ממשיך לאכול פירות ברור שיש כאן ריבית.","\u0003פעמים\u0004 ש\u0003מוכר מותר ולוקח אסור,\u0004 שמצד המוכר אין כאן ריבית אבל מבחינת הלוקח יש, כגון \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המוכר: \u0003לכי מייתית קני\u0004 \u0005[כאשר תביא\u0006 את הכסף \u0005תקנה]\u0006 את השדה. \u0003ופעמים שהלוקח מותר ומוכר אסור\u0004 — כגון \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המוכר: \u0003קני\u0004 \u0005[קנה]\u0006 \u0003מעכשיו וזוזאי להוו\u0004 \u0005[והכסף שלי\u0006 שאתה עוד חייב \u0005יהא]\u0006 בתורת \u0003הלואה גבך\u0004 \u0005[אצלך],\u0006 שנמצא המוכר האוכל פירות נהנה מן ההלוואה.","ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור שיש כאן אופן ש\u0003שניהם אסורין? אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 זהו ש\u0003לא\u0004 \u0003כ\u0004שיטת \u0003ר' יהודה. דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' יהודה, הא\u0004 \u0005[הרי]\u0006 \u0003אמר\u0004 ר' יהודה: \u0003צד אחד ברבית מותר.\u0004 כלומר, שאם היה הסכם שלפיו אמנם צד אחד מקבל רווח מן ההלוואה שנטל ואולם האחר איננו מפסיד דבר — זה איננו קרוי ריבית.","עוד שנינו בברייתא: \u0003משכן לו בית\u0004 או \u0003משכן לו שדה\u0004 לחבירו עבור הלוואה שלוה ממנו, \u0003ואמר לו \"לכשתרצה למוכרם\u0004 — \u0003לא תמכרם אלא לי בדמים הללו\u0004 שאנחנו קוצבים עכשיו \u0003\"\u0004— הרי זה \u0003אסור,\u0004 שיש מקום לחשוב שמחיר השדה גדול משווי ההלוואה, ונמצא משלם ריבית. אבל אם אמר לו \u0003\"\u0004לא תמכרם אלא לי, אבל \u0003בשוייהן\u0004 \u0003\"\u0004— אז \u0003מותר.\u0004","ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור שכשאומר \u0003\"בדמים הללו\" אסור? אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 זהו ש\u0003לא כ\u0004שיטת \u0003ר' יהודה, דאי\u0004 \u0005[שאם]\u0006 תאמר שזהו כשיטת \u0003ר' יהודה, האמר\u0004 \u0005[הרי אמר]\u0006 \u0003צד אחד ברבית\u0004 — \u0003מותר,\u0004 כי לא ברור שיגיעו הדברים לידי מכירה של ממש.","עוד שנינו בברייתא: \u0003מכר לו בית\u0004 או \u0003מכר לו שדה\u0004 ונתן \u0003לו הקונה את דמי כל השדה,\u0004 \u0003ואמר לו\u0004 המוכר: \u0003\"לכשיהיו לי מעות החזירם לי\u0004 וטול בחזרה את מעותיך \u0003\"\u0004— הרי זה \u0003אסור,\u0004 שהרי בינתיים הקונה־המלווה אוכל את פירות השדה. ואם אמר לו הקונה מעצמו \u0003\"לכשיהיו לך מעות אחזירם לך\"\u0004 — \u0003מותר.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן? \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 זהו ש\u0003לא\u0004 כשיטת \u0003ר' יהודה. דאי\u0004 \u0005[שאם]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה, האמר\u0004 \u0005[הרי אמר]\u0006 \u0003צד אחד ברבית\u0004 — \u0003מותר.\u0004","ושואלים: \u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[מה שונה בראש,\u0006 במקרה הראשון, \u0005ומה שונה בסוף]\u0006 שגרם לשינוי ההבדל בהלכה? \u0003אמר רבא: רישא\u0004 \u0005[בתחילה]\u0006 מדובר באופן ש\u0003לא אמר ליה מדעתיה\u0004 \u0005[לו\u0006 שיחזיר לו \u0005מדעתו],\u0006 שנמצא שיכול תמיד לבטל את המכר, ונמצא שהיתה זו מעיקרה רק הלוואה. \u0003סיפא\u0004 \u0005[בסוף]\u0006 מדובר כש\u0003אמר ליה\u0004 \u0005[לו]\u0006 שיחזיר לו \u0003מדעתיה\u0004 \u0005[מדעתו\u0006 ומרצונו\u0005],\u0006 שכיון שיתכן שלא ירצה ולא יחזיר — היה כאן מכר גמור.","מסופר: \u0003ההוא גברא דזבין ליה ארעא לחבריה\u0004 \u0005[אדם אחד מכר קרקע לחבירו]\u0006 \u0003שלא באחריות,\u0004 \u0003חזייה דהוה קא עציב\u0004 \u0005[ראה אותו,\u0006 את הקונה, \u0005שהוא עצוב]\u0006 וחושש שמא השדה ממושכן כבר ויילקח ממנו, ונמצא מפסיד את כספו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי עציבת\u0004 \u0005[מדוע אתה עצוב]?\u0006 \u0003אי טרפו לה מינך,\u0004 \u0003מגבינא\u0004 \u0005[אם יטרפו\u0006 יקחו בעלי המשכון \u0005אותה,\u0006 את השדה \u0005ממך אשלם]\u0006 \u0003לך שופרא, שבחא, ופירי\u0004 \u0005[ממיטב\u0006 ואת מה שהוצאת \u0005בהשבחה ו\u0006את \u0005הפירות\u0006 שיטרפו ממך\u0005].\u0006 לאחר זמן נתעוררה הבעיה מה תוקפה של הבטחה כזאת.","\u0003אמר אמימר:\u0004"],["\u0003פטומי מילי בעלמא\u0004 \u0005[פיטום דברים בלבד]\u0006 \u0003הוא,\u0004 כלומר, דברים אלה נועדו רק ל\"פטם\" ולפתות את הקונה ואין בהם משום התחייבות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: טעמא מאי\u0004 \u0005[מה הטעם]\u0006 — \u0003כיון\u0004 שה\u0003לוקח\u0004 (הקונה) \u0003בעי לאתנויי\u0004 \u0005[צריך\u0006 היה \u0005להתנות]\u0006 תנאי זה של אחריות, ולא התנה, \u0003והכא\u0004 \u0005[וכאן]\u0006 ה\u0003מוכר קא מתני\u0004 \u0005[הוא שמתנה],\u0006 \u0003אמרת פטומי מילי בעלמא\u0004 \u0005[אומר אתה\u0006 ש\u0005פיטום דברים בלבד]\u0006 \u0003הוא.\u0004","\u0003אלא\u0004 לפי זה \u0003מתניתא, דקתני\u0004 \u0005[הברייתא ששנינו]\u0006 שכשאמר \u0003\"לכשיהיו לך מעות אחזיר לך\u0004 — \u0003מותר\",\u0004 שבמקרה זה ה\u0003מוכר הוא דבעי לאתנויי\u0004 \u0005[ש\u0006היה \u0005צריך להתנות]\u0006 תנאי זה, ואילו ה\u0003מוכר לא אתני\u0004 \u0005[התנה]\u0006 \u0003ו\u0004ה\u0003לוקח קא מתני\u0004 \u0005[הוא\u0006 ש\u0005מתנה].\u0006","\u0003ואמרינן\u0004 \u0005[ואמרנו]:\u0006 \u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[במה שונה ההתחלה ובמה שונה הסוף]?\u0006 \u0003ואמר רבא: סיפא\u0004 \u0005[הסוף]\u0006 מדובר באופן ש\u0003אמר ליה מדעתיה\u0004 \u0005[לו מדעתו].\u0006 ונדייק מאותם דברים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אמר ליה\u0004 \u0003מדעתיה\u0004 \u0005[לו מדעתו],\u0006 \u0003הא\u0004 \u0005[הרי אם]\u0006 \u0003לא אמר ליה מדעתיה\u0004 \u0005[לו מדעתו]\u0006 — \u0003לא אמרינן פטומי מילי בעלמא\u0004 \u0005[\u0006היינו \u0005אומרים שפיטום דברים בלבד]\u0006 \u0003הוא.\u0004 משמע, שגם אם עושה תנאי לרעת עצמו — תנאי זה קיים ואינו נחשב כדיבור ללא התחייבות!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 לא כך יש להבין, אלא הטעם באמת הוא כפי שאמרנו שתנאי שלא התנה האיש הנכון — אינו תנאי קיים, ועל כך הוסיף רבא הערתו, שאז המצב הוא כי \u0003נעשה כמאן\u0004 \u0005[כמי]\u0006 ש\u0003אמר ליה מדעתיה אתמר\u0004 \u0005[לו מדעתו נאמר]\u0006 ולא שזהו הטעם לדבר.","מסופר: \u0003ההוא שכיב מרע\u0004 \u0005[חולה אחד]\u0006 ש\u0003כתב לה גיטא לדביתהו\u0004 \u0005[גט לאשתו]\u0006 כדי לשחררה מחובת חליצה אם ימות, ובאותה שעה \u0003אנגיד ואתנח\u0004 \u0005[נאנק ונאנח]\u0006 על שהוא מגרשה. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי קא מתנחת\u0004 \u0005[מדוע אתה\u0006 \u0003נאנח]?\u0004 \u0003אי קיימת\u0004 \u0005[אם תעמוד]\u0006 מחולי זה — \u0003דידך אנא\u0004 \u0005[שלך אני],\u0006 כלומר, אתחתן אתך מחדש. והתעוררה השאלה מה תוקפה של הבטחה זו. \u0003אמר רב זביד: פטומי מילי בעלמא\u0004 \u0005[פיטום דברים בלבד]\u0006 \u0003הוא\u0004 ואין לו תוקף חוקי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: ואי לאו פטומי מילי מאי\u0004 \u0005[ואם לא היה\u0006 זה סתם \u0005פטפוט\u0006 דברים\u0005]\u0006 אלא תנאי שקויים בשבועה או בקנין, וכי היה בו ממש, וכי \u0003בדידה קיימא למישדי תנאה בגיטא\u0004 \u0005[בה תלוי להטיל תנאים בגט]?\u0006 הרי אין האשה יכולה לעשות כן, אלא \u0003בדידיה קיימא למשדי תנאה\u0004 \u0005[בו תלוי להטיל תנאי]\u0006 וכיון שהוא לא התנה כן במפורש — אין תוקף לכל תנאי שהיא מקבלת על עצמה! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003הוא גופיה\u0004 \u0005[עצמו]\u0006 \u0003אדעתא דידה קא גמיר ויהיב גיטא\u0004 \u0005[על דעתה גמר\u0006 בלבו \u0005ונתן לה גט]\u0006 וכאילו הוא קבע תנאי זה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין זה נחשב.","שנינו במשנה: \u0003הלוהו\u0004 סכום כסף \u0003על שדהו\u0004 ואמר לו שאם לא יפרע לו את החוב עד שלוש שנים תהא השדה שלו (של המלוה) — הרי השדה קנוי למלוה. \u0003אמר רב הונא:\u0004 אם \u0003בשעת מתן מעות\u0004 התנה — \u0003קנה הכל,\u0004 ואם הלווה לא ישלם נקנה השדה למלוה. ואם אמר \u0003לאחר מתן מעות\u0004 — \u0003לא קנה אלא כנגד מעותיו,\u0004 כלומר, קנה רק לפי הכסף שכבר נתן. \u0003ורב נחמן אמר: אפילו לאחר מתן מעות קנה הכל\u0004 ואין חילוק מתי נאמר התנאי.","מסופר: \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003רב נחמן עובדא גבי ריש גלותא כשמעתיה\u0004 \u0005[מעשה אצל ראש הגולה כהלכתו],\u0006 לפי השיטה שלו, שגם לאחר זמן מתן מעות קנה הכל. הגיע הדבר לדין לפני רב יהודה, ו\u0003קרעיה\u0004 \u0005[וקרעו]\u0006 \u0003רב יהודה לשטריה\u0004 \u0005[את השטר שלו,\u0006 שעשה\u0005],\u0006 שטען ששטר זה אין לו תוקף. \u0003אמר ליה\u0004 \u0003ריש גלותא\u0004 \u0005[לו ראש הגולה]\u0006 לרב נחמן: \u0003רב יהודה קרע לשטרך\u0004 \u0005[את שטרך].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: וכי \u0003דרדקא קרעיה\u0004 \u0005[האם ילד קרע אותו]?\u0006 הלא \u0003גברא רבה קרעיה\u0004 \u0005[אדם גדול קרע אותו],\u0006 ודאי \u0003חזא ביה טעמא וקרעיה\u0004 \u0005[ראה בו\u0006 איזה \u0005טעם\u0006 לפסול \u0005וקרע אותו]!\u0006","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 נוסח אחר, ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003דרדקא קרעיה\u0004 \u0005[ילד קרע אותו],\u0006 כלומר, אין להתחשב בדבר, \u0003דכולי עלמא לגבי דידי בדינא דרדקי נינהו\u0004 \u0005[שכל העולם כלפי בדיני\u0006 ממונות \u0005ילדים הם],\u0006 שרב נחמן היה בקי בדינים אלה מכל בני דורו, ואין דעותיהם נחשבות כנגדו.","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר\u0004 \u0003רב נחמן\u0004 לאחר שעיין בדבר, דעה הפוכה: \u0003אפילו בשעת מתן מעות\u0004 — \u0003לא קנה ולא כלום. איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו במשנתנו: \u0003אם אי\u0004 (אין) \u0003אתה נותן לי מכאן ועד שלש שנים הרי הוא שלי\u0004 — \u0003הרי היא שלו.\u0004 משמע שתנאי כזה יש לו תוקף ועושה קנין!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אני\u0004 הייתי \u0003אומר\u0004 בכלל \u0003אסמכתא קניא\u0004 \u0005[קונה],\u0006 שכל התחייבות שהיא כעין קנס, או יתירה מערך הדברים שקיבל אדם — יש לה תוקף, ולפי זה התנאי עושה קנין, וכפי שאמר מתחילה. ואולם \u0003מניומי אמר: אסמכתא לא קניא\u0004 \u0005[אינה קונה]\u0006 וקנין זה אסמכתא הוא.","וכיון ששכנע אותי בעיקר שיטתו — חזרתי בי מדברי. ושואלים: אם כן, \u0003ולמניומי קשיא מתניתין\u0004 \u0005[קשה משנתנו]!\u0006 ומתרצים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 ותרץ כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 כשיטת \u0003ר' יוסי היא,\u0004 וידוע ש\u0003אמר\u0004 בכלל ש\u0003אסמכתא קניא\u0004 \u0005[קונה],\u0006 אבל דעת יחיד היא בלבד."],["\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 שבמשנה מדובר במקרה \u0003ש\u0004\u0003אמר ליה קני\u0004 \u0005[לו קנה]\u0006 \u0003מעכשיו\u0004 ואכן, עשה קנין. וכיון שעשה קנין באותה שעה הרי זה קנין גמור ואינו אסמכתא עוד.","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003מר ינוקא\u0004 \u0005[הצעיר]\u0006 \u0003ומר קשישא\u0004 \u0005[הזקן]\u0006 \u0003בני\u0004 \u0005[בניו]\u0006 של \u0003רב חסדא לרב אשי: הכי אמרי נהרדעאי משמיה\u0004 \u0005[כך אמר חכמי נהרדעא משמו]\u0006 של \u0003רב נחמן\u0004 \u0003האי\u0004 \u0005[זו]\u0006 ה\u0003אסמכתא, בזמניה\u0004 \u0005[בזמנה]\u0006 — \u0003קניא\u0004 \u0005[\u0006היא \u0005קונה],\u0006 \u0003בלא זמניה\u0004 \u0005[זמנה]\u0006 — היא \u0003לא קניא\u0004 \u0005[קונה]\u0006 והדברים הובנו במשמעות זו: שאם נעשתה האסמכתא לפני זמן הפרעון — אינה קונה.","\u0003אמר להו\u0004 \u0005[להם]:\u0006 אם כן אין בכך כל חידוש, \u0003כל מידי\u0004 \u0005[דבר]\u0006 כך הוא, \u0003בזמניה קני\u0004 \u0005[בזמנו\u0006 הוא \u0005קונה],\u0006 \u0003בלא זמניה\u0004 \u0005[זמנו]\u0006 הוא \u0003לא קני\u0004 \u0005[קונה].\u0006","\u0003דלמא הכי קאמריתו\u0004 \u0005[שמא כך אתם אומרים],\u0006 כך נתכוונתם לומר: אם \u0003אשכחיה בגו זמניה\u0004 \u0005[מצא אותו בתוך זמנו]\u0006 \u0003ואמר ליה קני\u0004 \u0005[לו קנה]\u0006 — \u0003קני\u0004 \u0005[\u0006הריהו \u0005קונה],\u0006 מצא אותו \u0003בתר זמניה\u0004 \u0005[אחר זמנו]\u0006 \u0003ואמר ליה קני\u0004 \u0005[לו קנה]\u0006 — הוא \u0003לא קני\u0004 \u0005[קונה].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003מחמת כיסופא\u0004 \u0005[בושה]\u0006 \u0003הוא דקאמר ליה\u0004 \u0005[שאמר לו]\u0006 לפי שלא פרע לו את החוב, ובאמת לא התכוון בלבו להקנות.","ומעירים: \u0003ולא היא,\u0004 אין ההלכה כן, ש\u0003אפילו בגו זמניה נמי\u0004 \u0005[בתוך זמנו גם כן]\u0006 הוא \u0003לא קני\u0004 \u0005[קונה]\u0006 \u0003והאי דקאמר ליה \"קני\"\u0004 \u0005[וזה שאמר לו \"קנה\"]\u0006 — \u0003קא סבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003כי מטי זמניה\u0004 \u0005[כאשר יבוא זמנו\u0006 לפרוע\u0005]\u0006 ש\u0003לא ליתי ליטרדן\u0004 \u0005[יבוא להטריד אותי]\u0006 ובינתיים ארוויח קצת זמן עד לפרעון.","\u0003אמר רב פפא: האי\u0004 \u0005[זו]\u0006 ה\u0003אסמכתא, זימנין קניא וזימנין לא קניא\u0004 \u0005[פעמים היא קונה, ופעמים אינה קונה],\u0006 כיצד? \u0003אשכחיה דקא שתי שכרא\u0004 \u0005[מצא אותו\u0006 הלווה \u0005שהוא שותה שיכר]\u0006 — הרי זה \u0003קני\u0004 \u0005[קונה],\u0006 שאם הלווה הסכים להעביר את השדה במצב כזה, שנראה שאיננו דחוק, כיון שהסכים וקיבל על עצמו אז — הרי זה מקנה בלב שלם, ואין בכך פגם. ואם הבטיח לו כן כשמצאו \u0003דקא\u0004 \u0005[שהוא]\u0006 \u0003מהפך\u0004 ומחפש \u0003אזוזי\u0004 \u0005[זוזים,\u0006 \u0005כספים\u0006\u0005]\u0006 כדי לשלם — \u0003לא קני\u0004 \u0005[\u0006\u0005אינו קונה],\u0006 משום שברור שלא נעשה הדבר מרצונו הגמור.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא:\u0004 מה שאמר רב פפא שאם מצא אותו שותה שיכר קונה — \u0003דלמא לפכוחי פחדיה קא שתי\u0004 \u0005[שמא לפכח את פחדו\u0006 ודאגתו \u0005הוא שותה]\u0006 אבל באמת הוא דחוק מאד מבחינה כספית, \u0003אי נמי: איניש אחרינא אסמכיה אזוזי\u0004 \u0005[או גם כן,\u0006 אולי \u0005אדם אחר הבטיח לו כספים]\u0006 ואז, אף שמסוגל לפרוע — מכל מקום דחוק הוא, והבטחתו היא רק אסמכתא! \u0003אלא אמר רבינא: אי קפיד בדמי\u0004 \u0005[אם מקפיד במחיר],\u0006 שלא למכור בפחות מן הערך המקובל — \u0003ודאי קני\u0004 \u0005[קונה],\u0006 שהרי אז ברור שאיננו דחוק כל כך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: דלמא סבר\u0004 \u0005[שמא סבור\u0006 הוא\u0005]\u0006 כשמראה שמקפיד בכך \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא תיתזיל ארעיה\u0004 \u0005[יוזל\u0006 מחיר \u0005קרקעותיו]\u0006 האחרות, שאם ידעו שאין בידו הכסף ילחצו גם הם עליו, אבל באמת לא היתה בידו ברירה ולא מרצון שלם מכר. \u0003אלא אמר רב פפא: אי קפיד בארעא\u0004 \u0005[אם\u0006 הוא \u0005מקפיד בקרקע]\u0006 שלא למכור קרקע אחרת אפילו בשוויה, משמע שאיננו דחוק, ובמקרה כזה \u0003ודאי קני\u0004 \u0005[קונה].\u0006","\u0003ואמר רב פפא: אף על גב דאמור רבנן\u0004 \u0005[אף על פי שאמרו חכמים]\u0006 ש\u0003אסמכתא לא קניא\u0004 \u0005[קונה]\u0006 ואם העמיד קרקע לגבות ממנה — לא נקנתה לו, מכל מקום, קרקע זו \u0003אפותיקי הויא למיגבא מינה\u0004 \u0005[כמשכון היא לגבות ממנה],\u0006 שאף שלא נקנתה כולה למלוה — יכול הוא לגבות כדי חובו מקרקע זו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן לרב פפא: מי קאמר ליה קני לגוביינא\u0004 \u0005[האם אמר\u0006 לו \u0005קנה לשם גביה]\u0006 כדי לגבות את הלוואתך ממנה? וכיון שלא אמר זאת — כל זכות שיש למלוה בקרקע היא רק בגדר אסמכתא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי לרבינא: ואי אמר קני למיגבא מיניה\u0004 \u0005[ואם היה אומר לו קנה לשם גבייה]\u0006 וכי \u0003קני\u0004 \u0005[קונה]?\u0006 \u0003סוף סוף אסמכתא היא\u0004 זו, וכלל הוא ש\u0003אסמכתא לא קניא.\u0004","ושואלים: אם כן, \u0003אלא אפותיקי\u0004 ש\u0003אמר רב פפא מאי\u0004 \u0005[מה]\u0006 \u0003היא,\u0004 שהרי לפי הקושיות שהקשינו נמצא שאין הבדל אם אמר או לא אמר. ומשיבים: דברי רב פפא קיימים כגון באופן ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 הלווה למלוה: לא רק שנותן לו הקרקע אם לא ישלם, אלא גם אם ישלם \u0003לא יהא לך פרעון אלא מזו,\u0004 ועל ידי נתינת קרקע ישלם לו. שאף שצד האסמכתא בטל, מכל מקום הבטחת הפרעון משדה זה — לא בטלה.","מסופר: \u0003ההוא גברא דזבין ליה ארעא לחבריה\u0004 \u0005[אדם אחד מכר לו קרקע לחבירו]\u0006 \u0003באחריות.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הקונה: \u0003אי טרפו ליה מנאי מגבית\u0004 \u0005[אם יטרפו אותה,\u0006 את הקרקע \u0005ממני\u0006 האם \u0005תגבה,\u0006 תשלם\u0005]\u0006 \u0003לי מ\u0004שדות \u0003עידי עידית,\u0004 מובחר שבמובחר, בקרקעות \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003לך?\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 המוכר: \u0003מעידי עידית לא מגבינא\u0004 \u0005[אינני משלם]\u0006 \u0003לך, דבעינן למיקם קמאי\u0004 \u0005[שאני רוצה שתהיה אצלי],\u0006 \u0003אלא מגבינא\u0004 \u0005[אגבה]\u0006 \u0003לך מ\u0004שדות \u0003עידית אחרים דאית\u0004 \u0005[שיש]\u0006 \u0003לי.\u0004 \u0003לסוף\u0004 \u0005[לבסוף]\u0006 \u0003טרפוה,\u0004 את השדה, \u0003מיניה\u0004 \u0005[ממנו,\u0006 מקונה את השדה\u0005],\u0006 ובינתים \u0003אתא בדקא שקיל\u0004 \u0005[בא שטף מים ולקח,\u0006 שטף\u0005],\u0006 את \u0003עידי\u0004 ה\u0003עידית\u0004 של המוכר, ונשארו ברשותו רק שדות העידית האחרים ולא רצה לתת אותם לקונה, אלא רצה להחזיר לו מבינונית, כפי המקובל.","\u0003סבר\u0004 \u0005[חשב]\u0006 \u0003רב פפא למימר\u0004 \u0005[לומר]:\u0006 \u0003מ\u0004כיון שמ \u0003עידית אמר ליה\u0004 \u0005[לו]\u0006 שיגבה לו \u0003והא קיימא\u0004 \u0005[והרי\u0006 היא \u0005קיימת]\u0006 — ישלם ממנה, כהבטחה ראשונה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 המוכר לקונה: \u0003כי אמרי\u0004 \u0005[כאשר אמרתי]\u0006 \u0003לך אנא מגבינא\u0004 \u0005[אני מגבה,\u0006 משלם\u0005]\u0006 \u0003לך\u0004 מן העידית — \u0003דהוה\u0004 \u0005[שהיתה]\u0006 שדה \u0003עידי עידית קיימא\u0004 \u0005[עומדת,\u0006 קיימת\u0005],\u0006 \u0003השתא קיימא ליה\u0004 \u0005[עכשיו עומדת לה]\u0006 אצלי ה\u0003עידית במקום עידי עידית,\u0004 שהיא כעת המובחר שבשדותי ואיני חייב לתת לך את המובחר שבשדותי.","מסופר: \u0003רב בר שבא הוה מסיק ביה\u0004 \u0005[היה נושה בו]\u0006 \u0003רב כהנא זוזי\u0004 \u0005[כסף].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב בר שבא: \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא פרענא\u0004 \u0005[אפרע]\u0006 \u0003לך\u0004 את חובי עד \u0003ליום פלוני\u0004 — \u0003גבי מהאי חמרא\u0004 \u0005[גבה מיין זה].\u0006 \u0003סבר\u0004 \u0005[חשב]\u0006 \u0003רב פפא למימר\u0004 \u0005[לומר]:\u0006 \u0003כי אמרינן\u0004 \u0005[כאשר אומרים אנו]\u0006 ש\u0003אסמכתא לא קניא\u0004 \u0005[קונה]\u0006 \u0003הני מילי בארעא, דלאו לזבוני קיימא\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005בקרקע שאינה עומדת למכירה]\u0006 ולכן בטלה ההבטחה, שבוודאי לא גמר והקנה בשלמות. \u0003אבל חמרא\u0004 \u0005[יין]\u0006 \u0003כיון דלזבוני קאי\u0004 \u0005[שלמכירה\u0006 הוא \u0005עומד]\u0006 — \u0003כזוזי דמי\u0004 \u0005[ככסף\u0006 הוא \u0005נחשב]\u0006 ויכול לגבות מיין כמו משאר שווה כסף.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרב פפא: הכי אמרינן משמיה\u0004 \u0005[כך אומרים אנו משמו]\u0006 של \u0003רבה:\u0004 \u0003כל \"דאי\"\u0004 \u0005[\"שאם\"]\u0006 — \u0003לא קני\u0004 \u0005[קונה],\u0006 שכל הסכם שאין בו התחייבות מיידית, אלא נאמר שאם יקרה דבר מסויים אעשה כך — אסמכתא הוא ואינו קונה, שאין קנין אלא בהסכם מפורש ומבורר משעה ראשונה.","\u0003אמר רב נחמן: השתא דאמור רבנן\u0004 \u0005[עכשיו שאמרו חכמים]\u0006 והסכימו ש\u0003אסמכתא לא קניא\u0004 \u0005[קונה],\u0006 הרי במקרה כזה כמו במשנתנו שהבטיח לו קרקע לגבות ממנה חובו, אם גבה \u0003הדר ארעא והדרי פירי\u0004 \u0005[חוזרת הקרקע וחוזרים הפירות]\u0006 שאכל המלוה בינתים מקרקע זו. ושואלים: \u0003למימרא דסבר\u0004 \u0005[האם לומר\u0006 מכאן \u0005שסבר]\u0006 \u0003רב נחמן\u0004 ש\u0003מחילה בטעות לא הויא\u0004 \u0005[איננה\u0006 נחשבת\u0005]\u0006 \u0003מחילה?\u0004 כלומר, שאם אדם מחל לחבירו על סכום כסף, והתברר שבטעות מחל לו, שאינו נחשב מחילה ומקבל את כספו בחזרה?","\u0003והאיתמר\u0004 \u0005[והרי נאמר]\u0006 שנחלקו בדבר, ששנינו: \u0003המוכר פירות דקל\u0004 לפני גמר בישולם \u0003לחבירו. אמר רב הונא: עד שלא באו\u0004 הפירות \u0003לעולם\u0004 — \u0003יכול לחזור בו\u0004 ולבטל את המכר, לפי שהפירות עדיין אינם מצויים כלל. \u0003משבאו לעולם,\u0004 ואפילו אינם בשלים — \u0003אין יכול לחזור בו,\u0004 שהרי מכר דבר המצוי בעינו. \u0003ורב נחמן אמר: אף משבאו לעולם יכול לחזור בו,\u0004 שאין אדם מקנה דבר שלא בא לעולם, ומעיקרו לא הועיל הקנין.","אבל \u0003אמר רב נחמן: מודינא, דאי שמיט ואכיל\u0004 \u0005[מודה אני שאם שמט\u0006 ונטל הקונה \u0005את הפירות ואכל]\u0006 — \u0003לא מפקינן מיניה\u0004 \u0005[אין אנחנו מוציאים ממנו],\u0006 שאנו אומרים שכיון שהמוכר הסכים למכר תחילה, אף שהיתה כאן טעות בדין, אנחנו אומרים שמחל לו! ודוחים: אין זו קושיה; \u0003התם זביני\u0004 \u0005[שם\u0006 מדובר ב\u0005מכירה],\u0006 ובמכירה אפשר לומר שיש מחילה. \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר ב\u0003הלואה,\u0004 ובמקום שיש הלוואה — מחילה כזו יש בה משום חשש ריבית.","\u0003אמר רבא:\u0004"],["\u0003הוה יתיבנא קמיה\u0004 \u0005[הייתי יוב\u0006 אז \u0005לפני]\u0006 \u0003רב נחמן\u0004 כשאמר שמחילה כטעות בקנין — מחילה היא, \u0003ובעי לאותביה\u0004 \u0005[ורציתי להקשות לו]\u0006 מדין \u0003אונאה, ואודיק\u0004 \u0005[והסתכל\u0006 בי\u0005],\u0006 והבין מה רצוני לומר, \u0003חזיתן\u0004 \u0005[\u0006ו\u0005הראה לי]\u0006 בדין \u0003איילונית.\u0004 ומסבירים את הדברים; שרצה רבא לשאול: \u0003והרי אונאה\u0004 ש\u0003מחילה בטעות היא\u0004 בשעת מכר, ויודעים אנו ש\u0003לא הויא\u0004 \u0005[אין היא]\u0006 \u0003מחילה! ואודיק\u0004 \u0005[והסתכל\u0006 בי\u0005],\u0006 \u0003חזיתן\u0004 \u0005[\u0006ו\u0005הראה\u0006 \u0003לי]\u0004 דין \u0003איילונית,\u0004 ועניינו: \u0003הרי איילונית\u0004 ש\u0003מחילה בטעות היא, והויא\u0004 \u0005[והרי היא]\u0006 \u0003מחילה,\u0004","\u0003דתנן:\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 \u0003הממאנת,\u0004 ילדה שהשיאוה קרוביה, שנישואיה הם רק מדברי סופרים יכולה למאן בבעלה כשאומרת שאינה רוצה בו ויוצאת ממנו בלא גט, וכן \u0003השנייה,\u0004 קרובת משפחה שיש רק איסור מדברי חכמים לשאתה לאשה, וכן \u0003האיילונית,\u0004 אשה שמבחינת התפתחותה המינית יש בה פגם כזה שאיננה מסוגלת כלל להוליד, כשהן יוצאות מבעליהן \u0003אין להן לא כתובה\u0004 שכתב להן הבעל, \u0003ולא פירות\u0004 מנכסיה שאכל במשך זמן הנישואין, \u0003ולא מזונות ולא בלאות\u0004 (החזרת בגדיה שהשתמשה בהם). הרי שאוכל הבעל את הפירות ואינו מחזיר, שאף שהנישואין היו בטעות — אנו אומרים שמחלה לו על מה שאכל!","ומעירים על כך: כשמעיינים בדבר מתברר כי \u0003לא הויא\u0004 \u0005[אינו כן]:\u0006 \u0003לא\u0004 דין \u0003אונאה הויא תיובתיה\u0004 \u0005[הוא קושיה עליו],\u0006 \u0003ולא\u0004 דין \u0003איילונית מסייע ליה\u0004 \u0005[לו],\u0006 לפי שיש הבדל בין המקרים.","ומסבירים: \u0003לא אונאה תיובתיה\u0004 \u0005[קושיה עליו]\u0006 — \u0003דלא ידע דאיתיה\u0004 \u0005[שאינו יודע\u0006 בשעת המכר \u0005שיש\u0006 כאן\u0005]\u0006 \u0003אונאה דמחיל גביה\u0004 \u0005[שימחול לו],\u0006 ואם כן אין כאן מחילה כלל. \u0003ולא\u0004 דין \u0003איילונית מסייע ליה\u0004 \u0005[לו],\u0006 לפי שיש בה מחילה מדעת ולא בטעות, \u0003דניחא\u0004 \u0005[שנוח]\u0006 \u0003לה דתיפוק עלה שמא\u0004 \u0005[שייצא עליה שם]\u0006 של \u0003אישות\u0004 שיאמרו שהיתה נשואה פעם, ולכן היא מוותרת ביודעין על הפירות שלקח הבעל.","מסופר: \u0003ההיא איתתא דאמרה ליה לההוא גברא\u0004 \u0005[אשה אחת אמרה לאיש אחד]:\u0006 \u0003זיל זבין\u0004 \u0005[לך קנה]\u0006 \u0003לי ארעא מקריביי\u0004 \u0005[קרקע מקרוביי].\u0006 \u0003אזל זבן\u0004 \u0005[הלך\u0006 ו\u0005קנה]\u0006 \u0003לה.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 המוכר לשליח: \u0003אי הוו\u0004 \u0005[אם יהיו]\u0006 \u0003לי זוזי מהדרת לה ניהלי\u0004 \u0005[כספים\u0006 האם \u0005תחזיר לי אותה,\u0006 את השדה\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 הלא \u0003את ונוולא אחי\u0004 \u0005[אתה והיא קרובים]\u0006 אתם, ומן הסתם תוכלו שניכם להגיע לידי הסכם בדבר. והשאלה היתה מה המשמעות ההלכתית של תשובה זו.","\u0003אמר רבה בר רב הונא: כל\u0004 ביטוי כגון \u0003\"את ונוולא אחי\"\u0004 \u0005[\"אתה והיא קרובים\"]\u0006 ש\u0003אמר, סמכא דעתיה, ולא גמר ומקני\u0004 \u0005[סומכת דעתו\u0006 שיוכל להתפשר עם קרובתו, \u0005ואינו גומר בלבו ומקנה]\u0006 את השדה בשלמות.","ומעירים במקרה כזה: \u0003ארעא הדרה\u0004 \u0005[הקרקע\u0006 עצמה \u0005חוזרת]\u0006 לבעלים, ואולם \u0003פירי\u0004 \u0005[הפירות]\u0006 שאכל הקונה ביתיים \u0003מאי\u0004 \u0005[מה\u0006 דינם\u0005]?\u0006 האם \u0003רבית קצוצה הוו\u0004 \u0005[הם]\u0006 \u0003ויוצאין בדיינין, או דילמא\u0004 \u0005[שמא]\u0006 \u0003כי אבק רבית הוו\u0004 \u0005[כמו אבק ריבית הם]\u0006 \u0003ואין יוצאין?\u0004","\u0003אמר רבא בר רב הונא: מסתברא\u0004 \u0005[מסתבר]\u0006 שרק \u0003כי\u0004 \u0005[כמו]\u0006 \u0003אבק רבית הוו\u0004 \u0005[הם]\u0006 \u0003ואין יוצאין בדיינין. וכן אמר רבא: כי\u0004 \u0005[כמו]\u0006 \u0003אבק רבית הוו ואין יוצאין בדיינין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבה: משכנתא,\u0004 אם משכן הלווה למלוה שדה, והמלוה ירד לשדה, עיבדו ואכל מפירותיו, בלא שיהא הסכם על כך, \u0003מאי\u0004 \u0005[מה\u0006 דינה\u0005]?\u0006 האם \u0003התם טעמא מאי\u0004 \u0005[שם מה הוא הטעם]\u0006 שנחשב הדבר רק אבק ריבית — \u0003משום\u0004 ש\u0003לא קץ ליה\u0004 \u0005[קצץ לו]\u0006 סכום ידוע כריבית, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003לא קץ ליה\u0004 \u0005[קצץ לו].\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003התם זביני, הכא\u0004 \u0005[או שמא שם\u0006 מדובר \u0005במכר, כאן]\u0006 ב\u0003הלואה,\u0004 ויש לחשוש יותר משום ריבית?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם טעמא מאי\u0004 \u0005[שם מהו הטעם]\u0006 — \u0003משום\u0004 ש\u0003לא קץ ליה\u0004 \u0005[קצץ לו]\u0006 סכום מסויים \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003לא קץ ליה\u0004 \u0005[קצץ לו]\u0006 ואין זו ריבית גמורה.","\u0003אמר רב פפי: עבד\u0004 \u0005[עשה]\u0006 \u0003רבינא עובדא\u0004 \u0005[מעשה]\u0006 בענין כזה, \u0003וחשיב ואפיק פירי\u0004 \u0005[וחישב והוציא\u0006 את \u0005הפירות]\u0006 שאכל אותם המלוה בינתים, וש\u0003לא כ\u0004דעת \u0003רבה בר רב הונא.\u0004","\u0003אמר מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: הא\u0004 \u0005[זו]\u0006 ה\u0003משכנתא\u0004 שהמלוה מקבל מהקרקע כמשכנתא ואוכל פירות, \u0003באתרא דמסלקי\u0004 \u0005[במקום שמסלקים]\u0006 במקום שבו נוהגים שהלווה יכול להחזיר את הכסף בכל עת שירצה, ולקבל מיד את קרקעו. הרי, אם \u0003אכל\u0004 המלוה מפירות השדה בדיוק כ\u0003שיעור זוזי\u0004 \u0005[הכסף]\u0006 שהלוה — \u0003מסלקינן ליה\u0004 \u0005[מסלקים אנו אותו],\u0006 ורואים את הפירות כתשלום מלא להלוואה.","ואם הספיק ו\u0003אכל טפי\u0004 \u0005[יותר]\u0006 מדמי ההלוואה — \u0003לא מפקינן מיניה\u0004 \u0005[\u0006\u0005אין מוציאים מידו]\u0006 שמה שאכל — אכל. וכן \u0003לא מחשבינן משטרא לשטרא\u0004 \u0005[אין מחשבים משטר לשטר],\u0006 שאם אותו לווה היה חייב לאותו מלווה בכסף בשטר אחד, אין אנו מחשיבים את מה שהוסיף ואכל כחלק מפרעונו של השטר השני, אלא כל הלוואה נדונה בפני עצמה.","אבל \u0003בדיתמי\u0004 \u0005[ב\u0006שדה \u0005של יתומים]\u0006 אם \u0003אכל\u0004 מפירות השדה כ\u0003שיעור זוזי\u0004 \u0005[הכסף],\u0006 מיד \u0003מסלקינן ליה\u0004 \u0005[מסלקים אנו אותו]\u0006 מן השדה, \u0003אכל טפי\u0004 \u0005[יותר]\u0006 — \u0003מפקינן מיניה\u0004 \u0005[מוציאים ממנו]\u0006 מה שאכל, \u0003ומחשבינן משטרא לשטרא\u0004 \u0005[ומחשבים משטר לשטר].\u0006 וטעמו — שבדרך כלל נחשב מה שאכל יותר כדבר שמחל בעל השדה, אבל בשדה של יתומים, כיון שהם קטנים ואינם יכולים למחול — יש לנהוג לפי מדת הדין.","\u0003אמר רב אשי: השתא דאמרת\u0004 \u0005[עכשיו שאתה אומר]\u0006 שאם \u0003אכל טפי\u0004 \u0005[יותר]\u0006 \u0003לא מפקינן מיניה\u0004 \u0005[אין מוציאים ממנו]\u0006 ואין הדבר נחשב אלא כאבק ריבית, הרי יש לומר שאם \u0003אכל שיעור זוזי\u0004 \u0005[הכסף]\u0006 — \u0003נמי לא מסלקינן ליה\u0004 \u0005[גם כן אין אנו מסלקים אותו]\u0006 \u0003בלא זוזי\u0004 \u0005[כסף]\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003סלוקי בלא זוזי אפוקי מיניה\u0004 \u0005[לסלק אותו בלא כסף\u0006 — \u0005כהוצאה ממנו]\u0006 \u0003הוא.\u0004 שהרי נמצא כמוציא את דמי הפירות מן המלוה, וכיון שפירות אלה \u0003הוי\u0004 \u0005[הרי הם]\u0006 כ\u0003אבק רבית,\u0004 הרי אמרנו ש\u0003אבק רבית אינה יוצאה בדיינין.\u0004","ומספרים: \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003רב אשי עובדא\u0004 \u0005[מעשה]\u0006 בענין כזה אף \u0003ביתומים קטנים\u0004"],["\u0003כגדולים,\u0004 שאף שאכל מקבל המשכנתא כשיעור הממון, לא היה גובה, משום שהוא אבק ריבית שאינו יוצא בדיינין.","\u0003אמר רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: האי\u0004 \u0005[זו]\u0006 ה\u0003משכנתא, באתרא דמסלקי\u0004 \u0005[במקום שמסלקים]\u0006 את מקבל המשכנתא כשמשלמים לו — \u0003לא ניכול\u0004 \u0005[יאכל]\u0006 המלוה \u0003אלא בנכייתא\u0004 \u0005[בניכוי]\u0006 שהוא מנכה לו מן החוב מה שהוא אוכל בפירות, \u0003וצורבא מדרבנן\u0004 \u0005[ותלמיד חכם],\u0006 שצריך לדקדק עם עצמו, \u0003אפילו בנכייתא\u0004 \u0005[בניכוי]\u0006 \u0003לא ניכול\u0004 \u0005[יאכל].\u0006 ושואלים: \u0003אלא במאי ניכול\u0004 \u0005[במה,\u0006 באיזה אופן, \u0005יאכל]?\u0006 ומשיבים: \u0003בקיצותא\u0004 \u0005[בקיצבה],\u0006 על ידי קביעת סכום קצוב.","ושואלים: \u0003הניחא למאן דאמר קיצותא שריא\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר\u0006 ש\u0005קיצבה מותרת],\u0006 \u0003אלא למאן דאמר קיצותא אסירא, מאי איכא למימר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר\u0006 ש\u0005קיצבה אסורה, מה יש לומר]?\u0006 \u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שבשאלה של \u0003קיצותא\u0004 \u0005[קיצבה]\u0006 \u0003פליגא\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 \u0003רב אחא ורבינא. חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: קיצותא שריא\u0004 \u0005[קיצבה מותרת],\u0006 \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: קיצותא אסירא\u0004 \u0005[קיצבה אסורה].\u0006 ושואלים: \u0003היכי דמי קיצותא\u0004 \u0005[כיצד בדיוק קיצותא\u0006 זו\u0005]?\u0006 ומסבירים: \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המלוה ללווה: \u0003עד חמש שנין\u0004 \u0005[שנים]\u0006 \u0003אכילנא לה בלא נכייתא\u0004 \u0005[אוכל\u0006 מן השדה \u0005בלא לנכות]\u0006 — \u0003מכאן ואילך שיימנא\u0004 \u0005[אשום,\u0006 אעריך\u0005]\u0006 \u0003לך כולהו פירי\u0004 \u0005[את כל הפירות]\u0006 שאני אוכל, ואנכה מסכום ההלוואה.","\u0003איכא דאמרי\u0004 \u0005[\u0006ו\u0005יש שאומרים]\u0006 נוסח אחר: \u0003כל\u0004 קבלת שדה \u0003בלא נכייתא\u0004 \u0005[ניכוי]\u0006 מן הכסף — \u0003אסור\u0004 משום ריבית, אבל \u0003היכי דמי קיצותא\u0004 \u0005[ואיך\u0006 היא \u0005בדיוק הקיצבה]\u0006 המותרת — \u0003דאמר ליה\u0004 \u0005[שאומר\u0006 הוא \u0005לו]:\u0006 \u0003עד חמש שנין\u0004 \u0005[שנים]\u0006 \u0003אכילנא בנכייתא\u0004 \u0005[אוכל בניכוי],\u0006 \u0003מכאן ואילך שיימנא\u0004 \u0005[אשום]\u0006 \u0003לך כולהו פירי\u0004 \u0005[את כל הפירות]\u0006 ונוריד מן ההלוואה.","ומעירים: \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אסר בקמייתא שרי בבתרייתא\u0004 \u0005[\u0006לפי נוסחה \u0005ראשונה מתיר באחרונה],\u0006 אבל \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אסר\u0004 אף \u0003בבתרייתא\u0004 \u0005[באחרונה],\u0006 אם כן \u0003היכי שרי למיכל\u0004 \u0005[איך מותר לאכול]\u0006 מפירות של משכון? ומשיבים: \u0003כי\u0004 \u0005[כמו]\u0006 \u0003משכנתא\u0004 של \u0003סורא,\u0004 \u0003דכתבי\u0004 \u0005[שכותבים]\u0006 \u0003בה הכי\u0004 \u0005[כך]:\u0006 \u0003במשלם שניא אילין תיפוק ארעא דא\u0004 \u0005[בהשלמת שנים אלה\u0006 שהוא אוכל פירות \u0005תצא קרקע זו]\u0006 \u0003בלא כסף\u0004 ותחזור לבעלים, משום שכל כספי ההלוואה ישולמו מהפירות.","\u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' יהושע אמרי תרוייהו\u0004 \u0005[אמרו שניהם]:\u0006 \u0003האי\u0004 \u0005[זו]\u0006 ה\u0003משכנתא, באתרא דמסלקי\u0004 \u0005[במקום שמסלקים]\u0006 את המלווה מן המשכון, בכל עת כשמחזירים לו את הכסף אינה נחשבת כלל כרכושו של המחזיק במשכנתא, ולכן \u0003אין בעל חוב גובה הימנה\u0004 את חובו מן המחזיק במשכון, \u0003ואין הבכור נוטל בה פי שנים\u0004 בירושתו, שהרי לא היתה שייכת ממש לאביו, \u0003ושביעית משמטתה\u0004 שבבוא שנת השמיטה בטל גם החוב הזה, ואין אנו רואים אותו כגבוי.","\u0003ובאתרא דלא מסלקי\u0004 \u0005[ובמקום שאין מסלקים]\u0006 אלא בזמן הקצוב לכך — \u0003בעל חוב גובה הימנו\u0004 (ממנו), \u0003ובכור נוטל בו פי שנים, ואין שביעית משמטתה.\u0004","\u0003ואמר מר זוטרא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב פפא: האי\u0004 \u0005[זו]\u0006 ה\u0003משכנתא, באתרא דמסלקי\u0004 \u0005[במקום שמסלקים]\u0006 את מחזיק המשכנתא — \u0003מסלקי ליה\u0004 \u0005[מסלקים אותו]\u0006 \u0003ואפילו\u0004 בתשלום \u0003מתמרי דאבודיא\u0004 \u0005[מ\u0006תוך \u0005תמרים שעל המחצלות\u0006 ששטחו עליהם את התמרים\u0005],\u0006 שאינו צריך לשלם דווקא בכסף, וגם תשלום בשווה כסף ראוי לכך. \u0003ואי אגבהנהו בסיסני, קננהו\u0004 \u0005[ואם הגביה אותם בתוך הסלים,\u0006 כבר \u0005קנה אותם]\u0006 בכך, והם שלו. \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 שאם נעשה הקנין על ידי \u0003כליו של לוקח ברשות מוכר\u0004 — \u0003קנה לוקח,\u0004 אם כן \u0003אפילו\u0004 כש\u0003לא אגבהנהו בסיסני\u0004 \u0005[הגביה אותם בסלים]\u0006 — \u0003קננהו\u0004 \u0005[קנה אותם],\u0006 שהרי נקנו לו כבר ללוקח בהיותם על המחצלות. ועוד כמה הלכות בענין של משכנתא.","\u0003פשיטא\u0004 \u0005[פשוט,\u0006 ברור לנו\u0005]\u0006 \u0003באתרא דמסלקי\u0004 \u0005[במקום שבו\u0006 כרגיל \u0005מסלקים\u0006 את המלווה בתשלום\u0005]\u0006 \u0003ואמר\u0004 המלוה בשעת מתן הכסף \u0003\"\u0004אני \u0003לא מסתלקנא\u0004 \u0005[אסתלק]\u0006 \u0003\"\u0004— \u0003הא קאמר דלא מסתלקנא\u0004 \u0005[הרי אמר אינני מסתלק],\u0006 ועל תנאי זה נתן את הכסף, ותנאו קיים. \u0003אלא\u0004 שיש לשאול \u0003באתרא דלא מסלקי,\u0004 \u0005[במקום שאין מסלקים\u0006 בו\u0005],\u0006 \u0003ו\u0004הוא \u0003אמר \"מסתלקנא\u0004 \u0005[אני מסתלק]\u0006 \u0003\"\u0004אם יקבל את הכסף, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 האם \u0003צריך למיקנא מיניה\u0004 \u0005[לקנות,\u0006 לעשות קנין, \u0005ממנו],\u0006 \u0003או לא,\u0004 שיש תוקף חוקי לאמירה בלבד?","\u0003רב פפא אמר: לא צריך למקנא מיניה\u0004 \u0005[לקנות ממנו].\u0006 \u0003רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי אמר: צריך למקנא מיניה\u0004 \u0005[לקנות ממנו].\u0006 ומסכמים, \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא: \u0003צריך למקנא מיניה\u0004 \u0005[לקנות ממנו].\u0006","אם \u0003אמר\u0004 הלווה למלווה: \u0003\"איזיל ואייתי זוזי\u0004 \u0005[אלך ואביא כסף]\u0006 \u0003\"\u0004— \u0003לא אכיל\u0004 \u0005[איננו\u0006 רשאי \u0005לאכול\u0006 עוד\u0005],\u0006 שהרי זה כסילוק. אבל אם אמר \u0003\"איזיל\u0004 \u0005[אלך]\u0006 \u0003ואטרח ואייתי זוזי\u0004 \u0005[ואביא כסף]\u0006 \u0003\",\u0004 במקרה זה נחלקו, \u0003רבינא אמר: אכיל\u0004 \u0005[אוכל],\u0006 שמותר למלוה לאכול עוד פירות, שהרי הלווה אינו בטוח שיביא, \u0003ומר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי אמר: לא אכיל\u0004 \u0005[אוכל].\u0006 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא: ש\u0003לא אכיל\u0004 \u0005[אוכל].\u0006","מסופר: \u0003רב כהנא ורב פפא ורב אשי לא אכלי בנכייתא\u0004 \u0005[היו אוכלים על ידי ניכוי],\u0006 שחששו משום ריבית שיש בכך. \u0003רבינא אכיל בנכייתא\u0004 \u0005[היה אוכל בניכוי].\u0006","\u0003אמר מר זוטרא: מאי טעמא דמאן דאכיל בנכייתא\u0004 \u0005[מה הטעם של זה שאוכל בניכוי]\u0006 — \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 בדין \u0003שדה אחוזה;\u0004 שאמרה התורה (ויקרא כז, יז-יט) שאם מקדיש אדם את שדה אחוזתו יכול הוא אחר כך לחזור ולפדותו מיד ההקדש כאשר הוא משלם סלע (ארבע זוזים) עבור כל שנה עד לשנת היובל. וכך למדים: \u0003שדה אחוזה, לאו אף על גב דקא אכיל פירי טובא\u0004 \u0005[\u0006האם \u0005לא אף על פי שהוא אוכל פירות הרבה]\u0006 במשך השנים, \u0003אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006"],["\u0003קא פריק לה\u0004 \u0005[\u0006ש\u0005הוא פודה אותה]\u0006 \u0003בארבעה זוזי\u0004 \u0005[זוזים]\u0006 לשנה, אף שהפירות שווים יותר, \u0003הכא נמי לא שנא\u0004 \u0005[כאן גם כן אינו שונה],\u0006 שכיון שקבע סכום קצוב לניכוי ואינו בטוח אם יקבלנו, מותר לו, אף אם מרוויח בכך.","\u0003ומאן דאסר\u0004 \u0005[ומי שאסר]\u0006 — \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך:\u0004 \u0003שדה אחוזה\u0004 בעצם \u0003הקדש היא, ורחמנא אוקמיה\u0004 \u0005והתורה העמידה אותו\u0006 ב\u0003פדיון,\u0004 וקבעו חכמים קיצבה לפרעונו הגמור כסכום זה. ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 — \u0003הלואה היא ומיחזי\u0004 \u0005[ונראית]\u0006 \u0003כרבית.\u0004","\u0003אמר רב אשי: אמרו לי סבי דמתא\u0004 \u0005[זקני העיר]\u0006 \u0003מחסיא:\u0004 \u0003סתם משכנתא\u0004 — \u0003שתא\u0004 \u0005[שנה].\u0006 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]?\u0006 ומסבירים: הכוונה היא \u0003דאי אכיל לה שתא\u0004 \u0005[שאם אכל ממנה\u0006 במשך \u0005שנה]\u0006 — \u0003מצי מסלק ליה\u0004 \u0005[יכול לסלק אותו],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא מצי מסלק ליה\u0004 \u0005[אינו יכול לסלק אותו],\u0006 שסתם משכנתא אינה פחות מזמן זה.","\u0003ואמר רב אשי: אמרו לי סבי דמתא\u0004 \u0005[זקני העיר]\u0006 \u0003מחסיא: מאי\u0004 \u0005[מה\u0006 לשון\u0005]\u0006 \u0003\"משכנתא\"\u0004 — \u0003דשכונה גביה\u0004 \u0005[ש\u0006היא \u0005שוכנת אצלו].\u0006 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה],\u0006 מה למדנו מדבר זה להלכה? ומשיבים: \u0003לדינא דבר מצרא\u0004 \u0005[ל\u0006ענין \u0005דין בר־מיצר]\u0006 שכיון שהמשכנתא נחשבת כשוכנת אצלו, הרי היא במידת מה כרכושו, ומשום כך נחשב הוא בר־מיצר לגבי כל שדה סמוך — שיש לו זכות קדימה לקנותו לפני אדם אחר שאין שדהו סמוך.","כסיכום לכמה מההלכות הללו שלא סוכמו במקומן \u0003אמר רבא: לית הלכתא\u0004 \u0005[אין הלכה]\u0006 \u0003לא כטרשי פפונאי\u0004 \u0005[כטרשא של רב פפא],\u0006 \u0003ולא כשטרי מחוזנאי\u0004 \u0005[בני\u0006 העיר \u0005מחוזא],\u0006 \u0003ולא כחכירי נרשאי\u0004 \u0005[כחכירות של נרש].\u0006","ומסבירים: \u0003כטרשי פפונאי\u0004 \u0005[כטרשא של רב פפא]\u0006 — \u0003כטרשי\u0004 של \u0003רב פפא\u0004 שנתן שכר וקיבל תשלום גבוה יותר, אף שהוא לא הרויח בכך.","\u0003שטרי מחוזנאי\u0004 מה הם — שהיו מלוים כסף לעיסקה משותפת, שהלווה עומד לסחור בה — \u0003דזקפי ליה לרווחא אקרנא, וכתבי ליה בשטרא\u0004 \u0005[שהיו זוקפים את הרווח\u0006 ומוסיפים \u0005לקרן\u0006 כאילו כבר נגמרה המכירה \u0005והיו כותבים בשטר]\u0006 את הסכום השלם, והטעם שאין עושים כן — \u0003מי יימר דהוה רווחא\u0004 \u0005[מי יאמר שיהיה רווח]?\u0006 ושמא יפסיד הלקוח בעיסקה, או שירויח פחות, ונמצא משלם ריבית.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר בר אמימר לרב אשי: אבא עביד הכי\u0004 \u0005[עושה ככה],\u0006 שבעיסקה הוא מוסיף את הרווח לסכום ההלוואה, \u0003וכי אתו לקמיה מהימן להו\u0004 \u0005[וכאשר באים לפניו\u0006 ואומרים לו שלא הרוויחו \u0005מאמין\u0006 הוא \u0005להם]\u0006 ומנכה כדי מה שהרויחו בפועל. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003תינח היכא דאיתיה לדידיה\u0004 \u0005[זה נוח במקום שהוא\u0006 עדיין \u0005נמצא],\u0006 אבל \u0003אי שכיב ונפל שטרא קמי יתמי\u0004 \u0005[אם ימות ויפול השטר לפני היתומים],\u0006 \u0003מאי\u0004 \u0005[מה]?\u0006 הרי הם אינם יודעים שבשטר נוסף הרווח, ויבואו לגבות את השטר במלואו, ויש בכך משום ריבית. ומעירים: \u0003הוי\u0004 \u0005[היה]\u0006 הדבר שאמר רב אשי לפי תומו \u0003\"כשגגה שיצא מלפני השליט\"\u0004 (קהלת י, ה) \u0003ונח נפשיה\u0004 \u0005[ונחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003אמימר\u0004 מיד לאחר מכן.","מה הם \u0003חכירי נרשאי\u0004 \u0005[חכירות של נרש]\u0006 — \u0003דכתבי הכי\u0004 \u0005[שכותבים כך]:\u0006 \u0003משכן ליה פלניא ארעיה לפלניא והדר\u0004 \u0005[לו פלוני,\u0006 הלווה את \u0005קרקעו לפלוני\u0006 המלוה, \u0005וחזר]\u0006 ו\u0003חכרה\u0004 \u0003מיניה\u0004 \u0005[ממנו]\u0006 בסכום מסויים. וסכום זה הוא כתוספת לתשלום ההלוואה. והפגם שיש בנושא זה: \u0003אימת\u0004 \u0005[אימתי]\u0006 \u0003קנאה\u0004 המלוה \u0003דאקנייה נהליה\u0004 \u0005[ש\u0006יוכל \u0005להקנות אותה לו]\u0006 ללווה? וכיון שכך הרי זו ריבית.","ומעירים: \u0003והאידנא דקא כתבי הכי\u0004 \u0005[ועכשיו\u0006 בימינו \u0005שכותבים\u0006 בנוסח \u0005זה]:\u0006 \u0003\"קנינא מיניה ושהינא\u0004 \u0005[קנינו ממנו ושהינו]\u0006 \u0003כמה עידני\u0004 \u0005[זמנים],\u0006 \u0003והדר\u0004 \u0005[וחזר]\u0006 ו\u0003חכרה\"\u0004 והלווה בסכום מסויים, ועל ידי נוסח זה שבו מודיעים שהמלוה קנה את השדה הרי הוא יכול מעתה להחכירו, ונעשה הדבר \u0003כדי שלא תנעול דלת בפני לווין\u0004 — \u0003שפיר דמי\u0004 \u0005[טוב הדבר],\u0006 שכאן אין נראה כהלוואה בריבית. ומסכמים: ואף על פי כן \u0003ולאו מלתא היא\u0004 \u0005[ואין זה דבר]\u0006 נכון, שאפילו השהה השדה ברשותו, כיון שלא קנאו קנין גמור הרי זו כריבית.","\u0003אין מושיבין חנוני למחצית שכר\u0004 שאסור לתת פירות לחנווני והחנווני מוכר בחנות, ומשלם למלוה בעד מחצית הרווחים, שאם קצב הנותן את מחיר הפירות מתחילה (שסכום זה יחזיר החנווני בכל מקרה) הרי זה כמלוה לו כסף בריבית. וכן \u0003לא יתן מעות ליקח\u0004 (לקנות) \u0003בהן פירות\u0004 שימכרם החנווני \u0003למחצית שכר, אלא אם כן נותן לו\u0004 המלוה לחנווני \u0003שכרו\u0004 (שכר עבודתו) שהוא עובד במכירת הפירות \u0003כפועל,\u0004 ולאחר ניכוי הוצאה זו מתחלקים ברווחים.","וכן \u0003אין מושיבין תרנגולין\u0004 לדגור על הביצים \u0003למחצה,\u0004 שנותן אדם לחבירו ביצים שידגיר אותן, וימכרו אפרוחים ויתחלקו ברווחים. שכיון שיש כאן צד הלוואה, יש בו חשש ריבית. \u0003ואין שמין עגלין וסייחין למחצה,\u0004 שאסור לתת לאדם שיגדל אותם על חשבונו, ואחר כך יקבל מחצית מן הרווחים שעלו אלה בשוויים כשגדלו, \u0003אלא אם כן נותן לו\u0004 למגדל \u0003שכר עמלו ומזונו\u0004 שמאכיל את בעלי החיים. וכל זה אמרו כשקוצב הנותן את מה שנתן במחיר קבוע ועומד על תשלום זה.","\u0003אבל מקבלין עגלין וסייחין למחצה\u0004 כעיסקה גמורה שבה כל צד משתתף בדבר מסויים, האחד בעגל והשני בעבודה ומזונות, \u0003ומגדלין אותן עד שיהו משולשין\u0004 (שיגיעו לשליש גדולם) ויימכרו אז. וכן מגדלים \u0003חמור עד שתהא טוענת,\u0004 שיגדל החמור עד כדי שיוכל לטעון עליו משא.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 מה שאמרו שנותן לו שכרו כפועל — כוונתו \u0003כפועל בטל.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כפועל בטל\"?\u0004"],["\u0003אמר אביי:\u0004 הכוונה היא \u0003כפועל בטל של אותה מלאכה\u0004 ש\u0003בטל מינה\u0004 \u0005[ממנה],\u0006 כמו שהיה אדם רוצה לקבל, אם יציעו לו, להתבטל מן המלאכה שהוא עוסק בה ולעסוק בעבודה קלה.","ומעירים: \u0003וצריכא\u0004 \u0005[ונצרכה],\u0006 שהיה צורך לומר שתי הלכות, גם בחנווני המקבל פירות וגם במקבל מעות. \u0003דאי תנא\u0004 \u0005[שאילו שנה]\u0006 \u0003חנוני\u0004 בלבד הייתי אומר כך: \u0003חנוני הוא דסגי ליה\u0004 \u0005[שדי לו]\u0006 לקבל שכר \u0003כפועל בטל, משום\u0004 ש\u0003לא נפיש טרחיה\u0004 \u0005[מרובה טרחתו],\u0006 שהרי הפירות מונחים עתה לפניו, ועליו רק למוכרם. \u0003אבל\u0004 אם נתן לו \u0003מעות ליקח בהן פירות, דנפיש טרחיה\u0004 \u0005[שמרובה טרחתו]\u0006 שצריך לחפש ולמצוא פירות ולהביאם לחנותו — \u0003אימא\u0004 \u0005[אמור]\u0006 שאולי \u0003לא סגי ליה\u0004 \u0005[די לו]\u0006 בתשלום \u0003כפועל בטל.\u0004","ולהיפך, \u0003ואי תנא\u0004 \u0005[ואילו שנה]\u0006 רק \u0003מעות ליקח בהן פירות\u0004 — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא דבעי\u0004 \u0005[שצריך]\u0006 לקבל \u0003כפועל בטל, משום דנפיש טרחיה\u0004 \u0005[שמרובה טרחתו],\u0006 \u0003אבל חנוני\u0004 ש\u0003לא נפיש טרחיה\u0004 \u0005[מרובה טרחתו]\u0006 — \u0003אימא סגי ליה\u0004 \u0005[אמור\u0006 שמא \u0005די לו]\u0006 \u0003במשהו בעלמא\u0004 \u0005[בלבד],\u0006 ש\u0003אפילו לא טבל עמו אלא בציר,\u0004 שבעל הפירות נתן לו הנאה מועטה זו שהרשה לו לטבול פת בציר, \u0003ולא אכל עמו אלא גרוגרת אחת\u0004 — \u0003זהו שכרו,\u0004 על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 ההלכה להיאמר בשני המקרים.","\u0003(כמה עיזי ותרנגולין מעלין סימן)\u0004","\u0003תנו רבנן\u0004 שנינו \"אלא אם כן נותן לו שכרו\". ונחלקו כבר התנאים מה הוא שכרו הראוי לו ששנו חכמים בברייתא: \u0003כמה הוא שכרו? בין מרובה בין מועט\u0004 כלומר, לפי מה שקוצבים ביניהם, אלו \u0003דברי ר' מאיר. ר' יהודה אומר: אפילו לא טבל עמו אלא בציר, ולא אכל עמו אלא גרוגרת אחת\u0004 — \u0003זהו שכרו. ר' שמעון בן יוחאי אומר: נותן לו שכרו משלם,\u0004 כלומר, כל השכר שמגיע לו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין שמין,\u0004 כלומר, אין נותנים בעלי חיים לגדל, לאחר שהעריכו את מחירם בסכום קצוב, \u0003לא את העזים ולא את הרחלים, ולא כל דבר שאינו עושה ואוכל\u0004 בחשבון רווחים \u0003למחצה\u0004 שכל הנוסף על השומה הראשונה יתחלק בין הבעלים ובין המגדל.","\u0003ר' יוסי בר' יהודה אומר: שמין את העזים מפני שחולבות, ואת הרחלים מפני שגוזזות,\u0004 כלומר, גוזזים מהן צמר, \u0003ו\u0004כן \u0003שוטפות\u0004 נשטף מהן הצמר בהיותן במים \u0003ומורטות\u0004 נמרט מהן צמר בקוצים ונמצא שהן עושות ואוכלות, \u0003ואת התרנגולת מפני שהיא עושה\u0004 (מטילה ביצים) \u0003ואוכלת.\u0004","ותוהים: \u0003ו\u0004ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 מה אומר הוא על כך? וכי לדעתו \u0003גיזה וחלב לא ספק\u0004 \u0005[אינו מצדיק]\u0006 כדי לשלם ל\u0003שכר עמלו ומזונו?\u0004 ומשיבים: אם אמנם הוא מקבל \u0003בגיזה וחלב\u0004 — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 שתשלום זה מספיק, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה רק \u0003בנסיובי ותותרי\u0004 \u0005[נסיוב,\u0006 מים הנשארים מן החלב\u0005,\u0006 ואת \u0005מריטת\u0006 העז\u0005],\u0006 כאשר הוא מקבל אותם.","ובכך נחלקו: \u0003תנא קמא סבר לה\u0004 \u0005[סבור]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון בן יוחי\u0004 ש\u0003אמר: נותן לו שכרו משלם\u0004 והנסיוב והמריטה אינם כדי כל שכרו, ו\u0003ר' יוסי בר' יהודה סבר לה כאבוה\u0004 \u0005[סבור כאביו]\u0006 ש\u0003אמר: אפילו לא טבל עמו אלא בציר, ולא אכל עמו אלא גרוגרת אחת\u0004 — \u0003זהו שכרו,\u0004 ואין מקפידים שיהיה השכר בדיוק כדי עמלו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003משכרת אשה לחברתה תרנגולת\u0004 שתדגור על הביצים בעד \u0003שני אפרוחים\u0004 מאלה שיבקעו מן הביצים. ואולם \u0003אשה שאמרה לחברתה: \"תרנגולת שלי וביצים שליכי\u0004 (שלך), \u0003ואני ואת נחלוק באפרוחים\"\u0004 — \u0003ר' יהודה מתיר ור' שמעון אוסר.\u0004","ושואלים: \u0003ור' יהודה לא בעי\u0004 \u0005[אינו צריך]\u0006 — שישלם לפחות משהו עבור \u0003שכר עמלו ומזונו?\u0004 ומשיבים: \u0003איכא\u0004 \u0005[יש]\u0006 \u0003ביצים מוזרות,\u0004 הביצים שאין אפרוחים בוקעים מהן, והביצים הללו נשארות לבעלת הביצים, ויש לה איפוא רווח מסויים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003מקום שנהגו להעלות שכר כתף\u0004 (סבל) \u0003למעות\u0004 שמשלמים למגדל \u0003בהמה\u0004 עבור טרחתו בנשיאת בעלי החיים הקטנים על כתפו — \u0003מעלין\u0004 ומחשיבים זאת בתשלום, \u0003ואין משנין ממנהג המדינה. רבן שמעון בן גמליאל אומר: שמין\u0004 — מעריכים \u0003עגל\u0004 הגדל \u0003עם אמו, וסיח\u0004 הגדל \u0003עם אמו\u0004 בחשבון אחד ומחלקים את הרווח, ואין מוסיפים על שכר טרחה, \u0003ואפילו במקום שנהגו להעלות\u0004 (לחשב) \u0003שכר כתף למעות.\u0004","ושואלים: \u0003ורבן שמעון בן גמליאל לא בעי\u0004 \u0005[איננו צריך]\u0006 אינו דורש כלל שישלם \u0003שכר עמלו ומזונו?\u0004 ומשיבים: הרי \u0003איכא\u0004 \u0005[יש]\u0006 \u0003גללים\u0004 שהבהמה מטילה, ויש בזה רווח מסוים למגדל. ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 מה הוא אומר? ומסבירים: שלדעתו \u0003גללים אפקורי מפקיר להו\u0004 \u0005[מפקיר\u0006 הוא \u0005אותם]\u0006 ואינו מחשיב אותם כלל, וכיון שהם שווים מעט מאוד, הריהם כהפקר.","\u0003אמר רב נחמן: הלכה כר' יהודה, והלכה כר' יוסי בר' יהודה, והלכה כרבן שמעון בן גמליאל\u0004 בדיני גידול בהמות בשכר.","מסופר: \u0003בני רב עיליש נפק עלייהו ההוא שטרא\u0004 \u0005[יצא עליהם שטר]\u0006 שהיה אביהם חתום עליו, והשטר הזה היה שטר עיסקה, \u0003דהוה כתיב ביה\u0004 \u0005[שהיה כתוב בו]\u0006 שהצדדים מתחלקים \u0003\"פלגא באגר, פלגא בהפסד\"\u0004 \u0005[\"חצי בשכר\u0006 ו\u0005חצי בהפסד\"].\u0006 \u0003אמר רבא: רב עיליש גברא רבה\u0004 \u0005[אדם גדול]\u0006 \u0003הוא\u0004 \u0003ואיסורא לאינשי\u0004 \u0005[ואיסור לאנשים]\u0006 \u0003לא הוי ספי\u0004 \u0005[היה מאכיל],\u0006 כלומר, ודאי לא היה עושה עיסקה שעל ידה ירוויח בה אדם כסף שיש בו משום ריבית, ועיסקה שמתחלקת כך — ריבית היא. על כן, \u0003מה נפשך\u0004 ככל מקרה בהכרח לומר שיש טעות בשטר. והתנאי היה \u0003אי פלגא באגר\u0004 \u0005[אם\u0006 היה שם \u0005חצי בשכר]\u0006 — היה כתוב שם שהצד השני יסכים לקבל על עצמו \u0003תרי תילתי\u0004 \u0005[שני שליש]\u0006 \u0003בהפסד,\u0004"],["\u0003אי פלגא\u0004 \u0005[או חצי ]\u0006 \u0003בהפסד\u0004 \u0003תרי תילתי באגר\u0004 \u0005[\u0006ו\u0005שני שליש בשכר].\u0006","\u0003אמר רב כהנא: אמריתא לשמעתא קמיה\u0004 \u0005[אמרתי הלכה זו לפני]\u0006 \u0003רב זביד מנהרדעא,\u0004 \u0003ואמר לי:\u0004 מהיכן יודעים אנו שמה שנכתב בשטר כלל את כל פרטי העיסקה? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003רב עיליש טובל עמו בציר הוה\u0004 \u0005[היה],\u0006 והרי אמרנו שלשיטת ר' יהודה אם הפועל נהנה משהו מהעבודה, אפילו טובל עמו בציר דיו בכך כדי להוציא עיסקת שותפות מחשש ריבית. \u0003ואמר רב נחמן: הלכה כר' יהודה! אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא: \u0003לאו הלכתא איתמר\u0004 \u0005[לא הלכה\u0006 כר' יהודה \u0005נאמר]\u0006 \u0003אלא שיטה איתמר\u0004 \u0005[נאמרה].\u0006","כלומר, רב נחמן בכלל לא קבע הלכה כדברי ר' יהודה אלא אמר שיש שיטה אחת המשותפת לר' יהודה, ולר' יוסי בר' יהודה ולרבן שמעון בן גמליאל, ואין בכך משום קביעת הלכה כמותם, אלא להיפך — שכל אלה הם שיטה אחת, שאינה כהלכה. ומעירים, \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 — \u0003למה ליה למיחשב ולמימר\u0004 \u0005[לו למנות ולומר]\u0006 \u0003הלכה\u0004 כפלוני \u0003הלכה\u0004 כפלוני? במקום זה \u0003לימא\u0004 \u0005[שיאמר]\u0006 רק \u0003הלכה כר' יהודה\u0004 שהוא \u0003מיקל מכולהו\u0004 \u0005[מכולם],\u0006 ובכלל דבריו דבריהם. ולכן, מסתבר שלא רצה לפסוק כמותם אלא רק לצרף את הדעות הללו לשיטה אחת.","\u0003אמר רב:\u0004 אם אמר לחבירו הרי אני נותן לך עגל לפטם, ונחלק את הרווח בינינו כשימכר, ו\u0003מותר שליש\u0004 — אם יהיה מחיר העגל אחר כך יותר משליש ממה שהוא שווה כעת, הרי כל המותר \u0003בשכרך\u0004 — דבר זה \u0003מותר,\u0004 משום שמתברר שהמגדל מקבל יותר ממחצית ואין זו ריבית. \u0003ושמואל אמר:\u0004 אינו כן, שהרי אם \u0003לא מצא מותר שליש,\u0004 כשיתברר שהעגל לא התפטם כל כך, וכי \u0003ילך לביתו ריקן,\u0004 ונמצא שהיה זה הסכם של ריבית! \u0003אלא אמר שמואל: קוצץ לו דינר,\u0004 כלומר, קובע לו נוסף לזה שכר של דינר עבור טרחתו, ובשאר יתחלקו.","ושואלים: והאם \u0003סבר רב אין קוצצין לו דינר? והאמר\u0004 \u0005[הרי אמר]\u0006 \u0003רב\u0004 דרך אחרת לעשות זאת: \u0003ריש עגלא לפטומא\u0004 \u0005[ראש העגל\u0006 נותנים \u0005למפטם],\u0006 כלומר, שמתחלקים בשווה ברווח, אבל ראש העגל ניתן כתוספת לאיש המפטם. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 כש\u0003אמר ליה\u0004 \u0005[לו]\u0006 גם כן \u0003מותר שליש בשכרך?\u0004","ודוחים: \u0003לא,\u0004 רב אמר \u0003דקאמר ליה\u0004 \u0005[שאמר לו]:\u0006 \u0003אי\u0004 \u0005[או]\u0006 שאתה מקבל \u0003מותר שליש, אי\u0004 \u0005[או]\u0006 שאתה מקבל את \u0003ריש עגלא לפטומא\u0004 \u0005[ראש העגל לפטם].\u0006 \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 דחיה אחרת: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב\u0004 שאם אמר לו \u0003מותר שליש בשכרך מותר\u0004 — הרי זה \u0003כגון דאית ליה\u0004 \u0005[שיש לו]\u0006 למפטם כבר \u0003בהמה לדידיה\u0004 \u0005[משלו]\u0006 \u0003דאמרי אינשי\u0004 \u0005[שאומרים אנשים]\u0006 בפגם מקובל: \u0003גביל לתורא גביל לתורי\u0004 \u0005[בלול\u0006 מאכל \u0005לשור, בלול\u0006 מאכל \u0005לשוורים],\u0006 כלומר, כיון שבין כה וכה צריך להכין אוכל עבור שור אחד, אם מוסיף מזון לשור נוסף אין זו טירחה והוצאה מרובה, ולכן די לו במותר שליש בלבד.","מסופר: \u0003ר' אלעזר מהגרוניא זבין\u0004 \u0005[היה קונה]\u0006 \u0003בהמה ויהיב ליה לאריסיה מפטים ליה, ויהיב ליה רישא באגריה, ויהיב פלגא רווחא\u0004 \u0005[ונותן לו לאריסו לפטם אותה, והיה נותן לו\u0006 את \u0005הראש בשכרו ונותן חצי הרווח].\u0006 \u0003אמרה ליה דביתהו\u0004 \u0005[לו אשתו\u0006 של האריס\u0005]:\u0006 \u0003אי משתתפת בהדיה יהיב לך נמי אליתא\u0004 \u0005[אם היית משתתף עמו\u0006 בקנית הבהמה \u0005היה נותן לך גם כן את האלייה],\u0006 וכך עשה האריס. \u0003אזל זבין בהדיה\u0004 \u0005[הלך וקנה יחד אתו],\u0006 \u0003פליג ליה מאליתא\u0004 \u0005[חלק לו\u0006 חצי \u0005מהאלייה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אלעזר: \u0003תא נפלגיה לרישא\u0004 \u0005[הבה\u0006 ו\u0005נחלוק את הראש]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 האריס: \u0003השתא כמעיקרא נמי לא\u0004 \u0005[עכשיו גם כן לא כמו קודם]?\u0006 הרי קודם כשלא הייתי שותף בבהמה, ורק קבלתיה לפטום היית נותן לי את כל הראש, ועכשיו אקבל רק מחציתו?","ענה לו: \u0003עד האידנא זוזי דידי הוו\u0004 \u0005[עכשיו הכספים היו שלי],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא הוה יהיבנא\u0004 \u0005[הייתי נותן]\u0006 \u0003לך טפי פורתא\u0004 \u0005[מעט יותר]\u0006 — \u0003מיחזי\u0004 \u0005[היה\u0006 זה \u0005נראה]\u0006 \u0003כרבית,\u0004 \u0003השתא שותפי אנן\u0004 \u0005[עכשיו שותפים אנחנו],\u0006 \u0003מאי קאמרת טרחנא טפי פורתא\u0004 \u0005[מה אומר אתה\u0006 שאתה \u0005טורח קצת יותר]\u0006 להכניס ולהוציא את הבהמה למרעה (שהרי בשכר המזונות מתחלקים עכשיו שניהם כשותפים), הרי \u0003אמרי אינשי\u0004 \u0005[אומרים אנשים]\u0006 בפתגם מקובל: \u0003סתם אריסא למרי ארעא קמשעבד נפשיה לאתויי ליה רעיא\u0004 \u0005[אריס משעבד עצמו לבעל הקרקע להביא לו מרעה],\u0006 ואם כן אנו שותפים שווים ומתחלקים בכל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003השם בהמה לחבירו\u0004 לגדלה, \u0003עד מתי חייב לטפל בה\u0004 אם לא הסכימו על כך במפורש? \u0003סומכוס אומר: באתונות שמונה עשר חדש, בגודרות\u0004 (בצאן) \u0003עשרים וארבעה חדש. ואם בא\u0004 אחד מהם \u0003לחלוק בתוך זמנו,\u0004 שרוצה למכור ולהתחלק ברווחים שנוצרו בינתיים — \u0003חברו מעכב עליו,\u0004 שיכול לומר שסתם הסכם זה הוא לתקופה ארוכה יותר. \u0003אבל אינו דומה טיפולה של שנה זו לטיפולה של שנה אחרת.\u0004","ושואלים: \u0003\"אבל\"\u0004 שאמר כאן \u0003מאי קאמר\u0004 \u0005[מה אמר,\u0006 מה פירושו\u0005]?\u0006 \u0003אלא\u0004 יש לתקן את הלשון כך: \u0003לפי שאינו דומה טיפולה של שנה זו לטיפולה של שנה אחרת\u0004 וכיון שיש שינוי בעבודה ובטיפול, אין דרך לחלק את הרווחים בדיוק בשווה במשך הזמן.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003השם בהמה לחבירו, עד מתי חייב לטפל בולדות\u0004 שנולדו לה? בבהמה \u0003דקה\u0004 — \u0003שלשים יום, ובגסה\u0004 — \u0003חמשים יום. ר' יוסי אומר: בדקה שלשה חדשים, מפני שטיפולה מרובה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"טיפולה מרובה\"\u0004 — \u0003מפני ששיניה דקות\u0004 (קטנות) וצריכים לחתוך בשבילה אוכל, מה שאין כן בבהמה גסה. \u0003מכאן ואילך\u0004 לאחר זמן זה \u0003נוטל\u0004 המגדל \u0003מחצה\u0004 מן הוולדות בחלק \u0003שלו,\u0004 שהרי חצי הבהמה היא שלו, \u0003וחצי מחצה בשל חבירו\u0004 בשכר טיפול וגידול.","מסופר: \u0003רב מנשיא בר גדא\u0004 קיבל לגדל בהמה, והוולדות \u0003שקל\u0004 \u0005[לקח]\u0006 \u0003מחצה שלו וחצי מחצה בשל חבירו. אתא לקמיה\u0004 \u0005[בא\u0006 הדבר \u0005לפני]\u0006 \u0003אביי.\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאן פלג\u0004 \u0005[מי חילק]\u0006 \u0003לך?\u0004 וכיון שעשית רק מדעת עצמך — שמא לא חילקת כהוגן. \u0003ועוד: מקום שנהגו לגדל\u0004 ולדות \u0003הוא\u0004 מקומנו, \u0003ותנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003מקום שנהגו לגדל\u0004 — \u0003יגדילו,\u0004 ולא יחלקו בינתים.","מסופר: \u0003הנהו תרי כותאי דעבוד\u0004 \u0005[אותם שני כותים,\u0006 שומרונים, \u0005שעשו]\u0006 \u0003עסקא\u0004 של שותפות \u0003בהדי הדדי\u0004 \u0005[זה עם זה].\u0006 \u0003אזיל חד מנייהו פליג זוזי\u0004 \u0005[הלך אחד מהם וחלק את כסף\u0006 השותפים\u0005]\u0006 \u0003בלא דעתיה דחבריה\u0004 \u0005[דעתו של חבירו].\u0006 \u0003אתו לקמיה\u0004 \u0005[באו\u0006 לדין \u0005לפני]\u0006 \u0003רב פפא.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא לתובע: \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מזה],\u0006 כלומר, מה קרה כאן ומה הפסדת? \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב נחמן: זוזי כמאן דפליגי דמו\u0004 \u0005[הכספים כמחולקים\u0006 הם \u0005נחשבים],\u0006 ולא כסכום אחד.","\u0003לשנה\u0004 אחרת \u0003זבון חמרא בהדי הדדי\u0004 \u0005[קנו\u0006 שני אלה \u0005יין יחד],\u0006 \u0003קם אידך פליג ליה\u0004 \u0005[עמד האחד וחלק]\u0006 \u0003בלא דעתיה דחבריה\u0004 \u0005[דעתו של חבירו],\u0006 ושוב \u0003אתו לקמיה\u0004 \u0005[באו\u0006 לדין \u0005לפני]\u0006 \u0003רב פפא.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא: \u0003מאן פלג\u0004 \u0005[מי חילק]\u0006 \u0003לך?\u0004 כלומר, לא עשית כשורה, שהרי לא קבלת רשות מחברך לחלוק! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו כותי: \u0003קא חזינא דבתר דידי קא אתי מר\u0004 \u0005[רואה אני שאחריי הולך אדוני]\u0006 כדי להציק לי, שהרי גם בשנה שעברה, כשלכאורה היה אותו מקרה גם בשנה שעברה, אמרת נימוק אחר — כדי להצדיק אותו, ועכשיו אתה משנה את שיטתך ושוב אתה מצדיק אותו! \u0003אמר רב פפא:\u0004"],["\u0003כהאי גונא\u0004 \u0005[במקרה זה]\u0006 ב\u0003ודאי צריך לאודועיה\u0004 \u0005[להודיעו]\u0006 את טעם הדברים, שאף שאין הדיין חייב תמיד להסביר לנדון מה טעם פסקו, כאן שנראה מקום לחשד, הסביר לו: \u0003זוזי, מי שקיל טבי ושביק חסרי\u0004 \u0005[\u0006ב\u0005כספים, האם לקח\u0006 את המטבעות \u0005הטובות והניח\u0006 לך את \u0005החסרות]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 הכותי: \u0003לא,\u0004 אלא חלק את הכסף סתם. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חמרא, כולי עלמא ידעי דאיכא דבסים ואיכא דלא בסים\u0004 \u0005[\u0006ב\u0005יין, הכל יודעים שיש\u0006 יין \u0005ערב\u0006 יותר \u0005ויש\u0006 שאינו \u0005ערב],\u0006 ולכן אי אפשר לחלק סתם חבית כנגד חבית, ומשום כך אמרתי שאין אתה רשאי לחלוק בלא חברך.","\u0003גופא,\u0004 לגופו של ענין שהוזכר קודם בדרך אגב, \u0003אמר רב נחמן: זוזי, כמאן דפליגי דמו\u0004 \u0005[כספים, כמחולקים הם נחשבים]\u0006 ואין צורך לחלקם דווקא במעמד שניהם ובהסכמה. ומעירים: \u0003הני מילי טבי וטבי, תקולי ותקולי\u0004 \u0005[דברים אלה\u0006 נאמרים כשהוא נותן זוזים \u0005טובים\u0006 כנגד זוזים \u0005טובים,\u0006 זוזים \u0005שקולים\u0006 כנגד זוזים \u0005שקולים],\u0006 שאז אין צורך לא בהערכה ולא בשיקול דעת. \u0003אבל טבי ותקולי\u0004 \u0005[טובים ושקולים]\u0006 — \u0003לא,\u0004 שאם למשל נותן זוזים טובים ושלמים, וכנגדם כספים שקולים, כיון שאין זו חלוקה פשוטה — אין שותף יכול לעשותה שלא מדעת חבירו.","מסופר: \u0003רב חמא הוה מוגר זוזי בפשיטא ביומא\u0004 \u0005[היה \"משכיר\" דינרים, בשמינית הדינר\u0006 עבור דינר \u0005ליום],\u0006 שראה בכך השכרה של חפץ לשימוש ולא הלוואה. ומספרים, לבסוף \u0003כלו זוזי\u0004 \u0005[הכספים]\u0006 של \u0003רב חמא\u0004 כעונש על שהיה מלווה בריבית. ומסבירים: \u0003הוא\u0004 עצמו \u0003סבר\u0004 \u0005[חשב]:\u0006 \u0003מאי שנא ממרא\u0004 \u0005[מה שונה\u0006 הדבר \u0005ממעדר]\u0006 שבעליו משכירו לשימוש ומקבל שכר, ואף כסף אפשר להשכיר, שהרי הוא פוחת בתוך השימוש. ומוסיפים: \u0003ולא היא\u0004 (ואינו כך), \u0003מרא הדרא בעינא וידיע פחתיה\u0004 \u0005[המעדר חוזר בעינו\u0006 לבעליו \u0005וניכר הפחת שבו],\u0006 ואילו \u0003זוזי לא הדרי בעינייהו\u0004 \u0005[הכספים אינם חוזרים בעינם],\u0006 שהרי אינו מחזיר לו אותם מטבעות עצמם \u0003ולא ידיע פחתיה\u0004 \u0005[נודע הפחת שבהם],\u0006 ועל כן אי אפשר לקרוא לכך השכרה כלל, אלא היא הלוואה בריבית.","\u0003אמר רבא: שרי ליה לאיניש למימר לחבריה\u0004 \u0005[מותר לו לאדם לומר לחבירו]:\u0006 \u0003הילך ארבעה זוזי\u0004 \u0005[זוזים]\u0006 \u0003ואוזפיה לפלניא זוזי\u0004 \u0005[זוזים והלווה לפלוני כסף]\u0006 שאף על פי שהמלוה מקבל תוספת כספים עבור ההלוואה — אינו אסור, כי \u0003לא אסרה תורה אלא רבית הבאה מלוה למלוה\u0004 ולא זו הבאה מצד שלישי. \u0003ואמר רבא: שרי ליה לאיניש למימר ליה לחבריה\u0004 \u0005[מותר לו לאדם לומר לחבירו]:\u0006 \u0003שקיל\u0004 \u0005[קח]\u0006 \u0003לך ארבעה זוזי\u0004 \u0005[זוזים]\u0006 \u0003ואמור ליה\u0004 \u0005[לו]\u0006 \u0003לפלוני לאוזפן זוזי\u0004 \u0005[להלוות לי כסף].\u0006 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003שכר אמירה קא שקיל\u0004 \u0005[הוא לוקח],\u0006 שארבעה זוזים אלה הם שכר התיווך בין הצדדים.","\u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003אבא מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב פפא\u0004 \u0003הוה שקיל אוגנא דקירא מקיראי\u0004 \u0005[היה לוקח אגן של שעווה מעושי השעווה],\u0006 \u0003ואמר ליה לאבוה\u0004 \u0005[והיה אומר לו לאביו]:\u0006 \u0003אוזפינהו זוזי\u0004 \u0005[הלווה להם כספים].\u0006 ומספרים: \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרב פפא: אכיל בריה דמר רביתא\u0004 \u0005[אוכל בנו של אדוני ריבית],\u0006 שהרי שעווה זו שהוא מקבל הוא תשלום של ריבית עבור ההלוואה! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כל כי האי רביתא ניכול\u0004 \u0005[ריבית כמו זו נאכל\u0006 כולנו\u0005],\u0006 שהדבר מותר לגמרי, \u0003לא אסרה תורה אלא רבית הבאה מלוה למלוה. הכא\u0004 \u0005[כאן]\u0006 — \u0003שכר אמירה קא שקיל, ושרי\u0004 \u0005[הוא לוקח, ומותר].\u0006","\u0003שמין פרה וחמור וכל דבר שהוא עושה ואוכל למחצה\u0004 שבעל החמור נותנו לאדם שיאכילנו ויטפל בו, והמקבל נהנה מעבודתו, והם מתחלקים אחר כך ברווח שמחמת עליית ערך הבהמה או מחמת ולדותיה, \u0003מקום שנהגו לחלוק את הולדות מיד\u0004 כשיוולדו — \u0003חולקין, מקום שנהגו לגדל\u0004 אותם אצל המחזיק — \u0003יגדילו.\u0004","\u0003רבן שמעון בן גמליאל אומר: שמין עגל עם אמו, וסיח עם אמו\u0004 ואין מחשיבים את הוצאות גידול הבהמה הצעירה. \u0003ו\u0004כן \u0003מפריז\u0004 הוא \u0003על שדהו,\u0004 שמוסיף ומרבה את המחיר, \u0003ואינו חושש משום רבית,\u0004 כאשר יבואר בגמרא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מפריז על שדהו ואינו חושש משום רבית, כיצד?\u0004 כגון \u0003השוכר את השדה מחבירו\u0004 ומתחייב לשלם לו \u0003עשרה כורים חטין לשנה. ואומר לו\u0004 השוכר למשכיר: \u0003תן לי מאתים זוז\u0004 בהלוואה \u0003ואפרנסנה\u0004 ואשקיע אותם בשדה לזבל ולעבד כראוי, \u0003ו\u0004אז \u0003אני אעלה לך שנים עשר כורין לשנה\u0004 — הרי זה \u0003מותר,\u0004 שאנו רואים במאתים הזוז השקעה משותפת של הבעלים והעובד בהשבחת השדה, ולא תשלום ריבית.","\u0003אבל אין מפריז לא על חנות\u0004 ששכר \u0003מחבירו\u0004 \u0003ולא על ספינה,\u0004 שאינו יכול ללוות ממנו כספים כדי לקנות סחורה ולמכור אותה בחנות או להוליכה בספינה ולהוסיף לו בשל אותה הלוואה על השכר.","\u0003אמר רב נחמן אמר רבה בר אבוה: פעמים שמפריז על חנות\u0004 כגון כאשר זקוק לכסף כדי \u0003לצור בה צורה\u0004 (לצייר בה ציור), או \u0003ספינה לעשות לה איסקריא\u0004 \u0005[מפרש\u0006 חדש\u0005].\u0006 ומסבירים: \u0003חנות לצור בה צורתא\u0004 \u0005[צורה]\u0006 — \u0003דצבו\u0004 \u0005[שרוצים]\u0006 \u0003בה אינשי והוי אגרא טפי\u0004 \u0005[אנשים\u0006 לבוא ולקנות בה \u0005ונעשה שכרה מרובה].\u0006 \u0003ספינה לעשות לה איסקריא\u0004 \u0005[מפרש],\u0006 \u0003כיון דשפירא איסקריא טפי\u0004 \u0005[שטוב המפרש יותר]\u0006 — \u0003אגרא טפי\u0004 \u0005[\u0006מרובה \u0005השכר יותר]\u0006 וכיון שכך הרי זו השקעה של ממש, ואינו ריבית.","כיון שהוזכר ענין זה של \u0003ספינתא\u0004 \u0005[ספינה]\u0006 מביאים מה ש\u0003אמר רב:\u0004 עבור הספינה משלמים \u0003אגרא ופגרא\u0004 \u0005[שכירות ודמי נזק],\u0006 שהמשכיר את ספינתו מקבל שכר שימוש בה, ומקבל גם את דמי הנזקים אם היא נשברת. \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא ורב אסי לרב: אי אגרא\u0004 \u0005[אם\u0006 יקבל \u0005שכר]\u0006 — ש\u0003לא\u0004 יקבל \u0003פגרא\u0004 \u0005[דמי שבירה],\u0006 \u0003אי פגרא\u0004 \u0005[אם\u0006 יקבל \u0005דמי שבירה]\u0006 — ש\u0003לא\u0004 יקבל \u0003אגרא\u0004 \u0005[שכר],\u0006 שאם הספינה באחריותו של המקבל, וגם משלם שכרה, הרי זה כריבית. \u0003שתיק\u0004 \u0005[שתק]\u0006 \u0003רב\u0004 ולא ענה כלל, והיה נראה כמי שאיננו יכול לענות על קושיה זו.","\u0003אמר רב ששת: מאי טעמא שתיק\u0004 \u0005[מה טעם שתק]\u0006 \u0003רב?\u0004 וכי \u0003לא שמיעא ליה הא דתניא\u0004 \u0005[שמע\u0006 הלכה \u0005זו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003אף על פי שאמרו אין מקבלין צאן ברזל מישראל,\u0004 שאסור לקבל צאן (או דברים אחרים) תוך קבלת אחריות גמורה לשלם את מחירם אם יאבדו אם יפגעו, וגם לקבל מחצית מן הרווחים, שכן דבר זה הוא ריבית, \u0003אבל מקבלין צאן ברזל מן הגוים\u0004 שהרי אין איסור ריבית בהם. \u0003אבל\u0004 עם זאת \u0003אמרו\u0004 חכמים: \u0003השם פרה לחבירו\u0004 לגדלה ולהתחלק ברווחים, \u0003ואמר לו\u0004 לבעל הפרה: \u0003הרי פרתך עשויה עלי\u0004 (מוערכת עבורי) \u0003בשלשים דינר\u0004 אם לא אשיב אותה לך, \u0003ואני אעלה לך\u0004 (אשלם) \u0003סלע בחדש\u0004 עבור השימוש בה — דבר זה \u0003מותר.\u0004 ומדוע — \u0003לפי שלא עשאה דמים,\u0004 שלא עשה זאת ענין של הלוואת כסף.","ותוהים: \u0003ולא עשאה?!\u0004 הלא בפירוש עשאה, שהרי קצב לה מחיר מסויים, ונמצא כמשלם ריבית על הלוואה של שלושים דינר! \u0003אמר רב ששת:\u0004 הכוונה היא \u0003לא עשאה דמים מחיים,\u0004 לא העריך את שוויה כעת, \u0003אלא לאחר מיתה\u0004 —","שהרי לא קיבל על עצמו אחריות להחזיר לו סכום קצוב זה אם ירד ערך הפרה, והתחייב רק להחזיר לו את הפרה (או את מחירה) אם תמות. ואם כן, על פי ברייתא זו הוא הדין אף בספינה שרשאי לקבל את דמי שכירתה, ואכן, \u0003אמר רב פפא: הלכתא\u0004 \u0005[הלכה היא]:\u0006 \u0003ספינה\u0004 אפשר לגבות עבורה \u0003אגרא ופגרא\u0004 \u0005[שכירות ודמי נזק].\u0006"],["\u0003ונהגו בני כופרא\u0004 \u0005[\"בני הזפת\",\u0006 כלומר, הספנים\u0005]\u0006 שמשלמים \u0003אגרא\u0004 \u0005[שכר]\u0006 \u0003בשעת משיכה, פגרא\u0004 \u0005[דמי שבירה]\u0006 לוקחים \u0003בשעת שבירה.\u0004 ושואלים: \u0003אטו במנהגא תליא מילתא\u0004 \u0005[וכי במנהג תלוי הדבר],\u0006 שאפשר לקחת מתי שרוצים ואיך שרוצים ואין הלכה בדבר? ומשיבים: \u0003משום דמתניתא תניא\u0004 \u0005[שהברייתא שנתה]\u0006 זאת — הרי זה \u0003מנהגא\u0004 \u0005[מנהג\u0006 כשר\u0005]\u0006 ומותר.","\u0003אמר רב ענן אמר שמואל: מעות של יתומים מותר להלוותן ברבית,\u0004 שכיון שהיתומים קטנים הם ופטורים ממצוות — אין איסור ריבית חל עליהם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: משום דיתמי נינהו ספינא להו איסורא\u0004 \u0005[שיתומים הם אנו מאכילים להם איסור]?!\u0006 ובלשון קשה הוסיף: \u0003יתמי דאכלי דלאו דידהו ליזלו בתר שבקייהו\u0004 \u0005[יתומים שאוכלים מה שאינו שלהם שילכו אחרי הנפטר שלהם]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לרב ענן: \u0003אימא לי איזו, גופא דעובדא היכי הוה\u0004 \u0005[אמור לי, ידידי, גופו של מעשה איך היה]?\u0006 כלומר, כיצד בדיוק שמעת את הדברים מפי שמואל?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ענן: \u0003ההוא דודא\u0004 \u0005[אותו\u0006 \u0003דוד]\u0004 שהיה שייך ל\u0003בני מר עוקבא\u0004 שהיו יתומים קטנים \u0003דהוה בי\u0004 \u0005[שהיה בבית]\u0006 \u0003מר שמואל\u0004 שהיה משכיר אותו, \u0003תקיל ויהיב ליה, תקיל ושקיל ליה\u0004 \u0005[\u0006היה \u0005שוקל ונותן לו, שוקל ולוקח אותו]\u0006 \u0003שקיל אגרא ושקיל פחתא\u0004 \u0005[\u0006היה \u0005לוקח שכר\u0006 עבור השימוש בדוד והיה \u0005לוקח\u0006 גם עבור \u0005הפחת]\u0006 והרי בדרך כלל אומרים אנו: \u0003אי אגרא\u0004 \u0005[אם\u0006 נוטל \u0005שכר]\u0006 — \u0003לא\u0004 נוטל \u0003פחתא\u0004 \u0005[פחת],\u0006 \u0003ואי פחתא\u0004 \u0005[ואם\u0006 נוטל \u0005פחת]\u0006 — \u0003לא\u0004 נוטל \u0003אגרא\u0004 \u0005[שכר]\u0006 ואם לוקח שניהם הריהי ריבית. ואם כן רואים ששמואל התיר ליתומים לקבל ריבית.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: משם אין ראיה, במקרה \u0003כי הא\u0004 \u0005[כגון זה]\u0006 — \u0003אפילו בדקנני נמי שרי למיעבד\u0004 \u0005[בבעלי זקנים,\u0006 באנשים מבוגרים, \u0005גם כן מותר לעשות]\u0006 \u0003דהא מקבלי עלייהו חוסכא דנחשא, דכמה דמקלי נחשא בציר דמיה\u0004 \u0005[שהרי\u0006 הבעלים \u0005מקבלים עליהם את פחת הנחושת, שככל שנשרפת הנחושת פוחתים דמיה\u0006 של הקלחת\u0005]\u0006 וכיון שכך הרי משלמים השוכרים עבור פחת הניכר לעין, וכגון זה ודאי מותר.","\u0003אמר רבה בר שילא אמר רב חסדא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רבה בר יוסף בר חמא אמר רב ששת: מעות של יתומים מותר להלוותן\u0004 באופן שהוא \u0003קרוב לשכר ורחוק להפסד.\u0004 שכיון שאין זו אלא אבק ריבית — אין אנו מחמירים במקום יתומים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 עיסקה של שותפות שעבור בעל הכסף התנאים הם \u0003קרוב לשכר ורחוק להפסד\u0004 — הרי המלוה \u0003רשע,\u0004 שלוקח ריבית. \u0003קרוב להפסד ורחוק לשכר\u0004 — \u0003חסיד,\u0004 שמחמיר על עצמו שלא להגיע אף לחשש ריבית, אם \u0003קרוב לזה ולזה\u0004 או \u0003רחוק מזה ומזה\u0004 — \u0003זו\u0004 היא \u0003מדת כל אדם,\u0004 שנוהג לפי שורת הדין.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה לרב יוסף: הני זוזי דיתמי היכי עבדינן להו\u0004 \u0005[כספי יתומים איך אנחנו עושים בהם]?\u0006 כלומר, מה עושים כדי לשמרם שלא יתבזבזו ויאבדו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מותבינן להו בי דינא ויהבינן להו זוזא זוזא\u0004 \u0005[מושיבים אנו עבורם בית דין\u0006 והם מחזיקים את הכסף \u0005ונותנים להם זוז זוז]\u0006 לפי צרכיהם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003והא קא כליא קרנא\u0004 \u0005[\u0006\u0005והרי כך כלה הקרן,\u0006 גוף הרכוש\u0005]\u0006 באופן זה, ונמצא שאין אנו אפוטרופסים ראויים ליתומים, שלא נשמר רכושם כראוי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003מר היכי עביד\u0004 \u0005[אדוני איך\u0006 הוא \u0005עושה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בדקינן גברא דאית ליה דהבא פריכא\u0004 \u0005[מחפשים אנו אדם שיש לו גרוטאות זהב],\u0006 כלומר, זהב שלא נעשו ממנו חפצים ותכשיטים, \u0003ונקטינן דהבא מיניה\u0004 \u0005[ואנחנו לוקחים,\u0006 קונים, \u0005את הזהב ממנו]\u0006 ואחר כך \u0003יהבינן להו ניהליה\u0004 \u0005[נותנים לו אותו,\u0006 את הזהב\u0005]\u0006 בצורת עיסקה באופן שיהיה \u0003קרוב לשכר ורחוק להפסד.\u0004 ומעירים: \u0003אבל דבר מסוים,\u0004 חפץ זהב גמור — \u0003לא, דלמא\u0004 \u0005[שמא]\u0006 \u0003פקדון נינהו\u0004 \u0005[הוא]\u0006 בידי המחזיק, \u0003ואתי מריה יהיב\u0004 \u0005[ויבוא בעליו ויתן]\u0006 \u0003סימנין ושקיל ליה\u0004 \u0005[ויקח אותו]\u0006 ויימצאו היתומים נפסדים. ולכן משתמשים רק בדבר שערכו מובטח ושאין אפשרות שיילקח מן המחזיק אותו.","על דרך זו של הבטחת כספי היתומים \u0003אמר רב אשי: תינח אי משתכח גברא דאית ליה דהבא פריכא\u0004 \u0005[נניח אם נמצא אדם שיש לו גרוטאות זהב],\u0006 ואולם \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא משתכח גברא דאית ליה דהבא פריכא ניכלו זוזי דיתמי\u0004 \u0005[יימצא אדם שיש לו גרוטאות זהב יכלו כספי יתומים]?\u0006 — ונמצא שזהירות יתירה זו עלולה להביא אף היא להפסד. \u0003אלא אמר רב אשי\u0004 כך עושים: \u0003חזינן גברא דמשפו נכסיה, ומהימן, ושמע דינא דאורייתא ולא מקבל שמתא דרבנן\u0004 \u0005[רואים אנו אדם שנכסיו שקטים\u0006 שאין ערעור על בעלותו עליהם, \u0005ו\u0006הוא איש \u0005נאמן, ושומע,\u0006 מציית, \u0005לדין תורה ואינו מקבל נידוי של חכמים],\u0006 כלומר, אדם שיודעים בו שמציית לדברי בית דין ברצון וללא צורך בכפיה, \u0003ויהבינן להו ניהליה בבי דינא\u0004 \u0005[ונותנים לו אותם,\u0006 את הכספים הללו \u0005בבית דין]\u0006 כעיסקה שהיא קרובה לשכר מלהפסד, ומשקיעים את כספי היתומים בדרך זו שהיא בטוחה ומכניסה."],["\u0003אין מקבלין צאן ברזל מישראל,\u0004 שאין מקבלים צאן (או שאר דברים) באופן שהמטפל מקבל עליו אחריות גמורה לשמור על ערכם במקרה של פחת או אבידה (מוות, גניבה), אלא רק מחצית הרווחים — \u0003מפני שהוא רבית.\u0004 שכיון שהקרן היא קצובה, ומוחזרים תמיד לבעלים, נמצא שכל סכום נוסף שמקבל – ריבית הוא על ההלוואה. \u0003אבל מקבלין צאן ברזל מן הגוים\u0004 שהרי אין לגביהם איסורי ריבית,","\u0003ולוין מהן\u0004 בריבית \u0003ומלוין אותן ברבית. וכן בגר תושב\u0004 גוי שחי בארץ ישראל וקיבל עליו שלא לעבוד עבודה זרה, אבל אם לא התגייר — לוה ומלוה בריבית, שהרי אינו ישראל. וכן \u0003מלוה ישראל מעותיו של גוי\u0004 לישראל אחר \u0003מדעת הגוי\u0004 בשליחותו, \u0003אבל לא מדעת ישראל.\u0004","ושואלים: \u0003למימרא דברשותא\u0004 \u0005[\u0006האם \u0005לומר\u0006 \u0003שברשות]\u0004 של ה\u0003מקבל קיימא\u0004 \u0005[עומד]\u0006 ה\"צאן ברזל\"? שכל עוד הוא מחזיק בהם הם כרכושו (שהרי מטעם זה נחשב הדבר כהלוואה שיש בה ריבית)? \u0003ורמינהו\u0004 \u0005[מטילים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003המקבל צאן ברזל מן הגוים\u0004 — ה\u0003ולדות פטורין מן הבכורה\u0004 ולכאורה מוכיח הדבר שהצאן נחשב כשייך עדיין לבעליו הגויים, ולכן אינו חייב בבכורה!","\u0003אמר אביי: לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 לענין בכורות כאשר בעל הצאן \u0003מקבל עליה אונסא וזולא\u0004 \u0005[עליו\u0006 אחריות \u0005לאונס\u0006 שיקרה לבהמה או \u0005הוזלה\u0006 במחיר\u0005]\u0006 ולכן נחשבת כשייכת עוד לבעליה הגויים. \u0003הא\u0004 \u0005[\u0006ו\u0005זה]\u0006 במשנתנו — ש\u0003לא קביל עליה אונסא וזולא\u0004 \u0005[קיבל עליו אונס וזול].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אי דקביל עליה מרה אונסא וזולא\u0004 \u0005[אם שקיבל עליו בעליה אונס והוזלה]\u0006 — \u0003צאן ברזל קרית ליה\u0004 \u0005[אתה קורא לזה]?\u0006 הלא זו היא עיסקת שותפות גמורה המותרת אף בישראל!","\u0003ועוד: אדתני סיפא\u0004 \u0005[ששנה בסוף\u0006 המשנה\u0005]:\u0006 \u0003אבל מקבלין צאן ברזל מן הגוים, ליפלוג בדידיה\u0004 \u0005[שיחלוק ב\u0006ענין זה \u0005עצמו]\u0006 שיש בו כמה צדדים, ויאמר: \u0003במה דברים אמורים\u0004 — ש\u0003לא קביל עליה אונסא וזולא\u0004 \u0005[קיבל על עצמו אונס והוזלה]\u0006 \u0003אבל\u0004 אם \u0003קביל מרה אונסא וזולא\u0004 \u0005[קיבל בעליה\u0006 \u0003אונס והוזלה]\u0004 — \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 מותר הדבר\u0005]!\u0006","\u0003אלא\u0004 עלינו לחזור מהסבר זה, ו\u0003אמר רבא: אידי ואידי\u0004 \u0005[זה וזה]\u0006 במשנתנו ולענין בכורות מדובר באופן ש\u0003לא קביל עליה מרה אונסא וזולא\u0004 \u0005[קיבל עליו בעליה אונס והוזלה],\u0006 \u0003וגבי\u0004 \u0005[ואצל]\u0006 \u0003בכורות היינו\u0004 \u0005[זה]\u0006 ה\u0003טעם\u0004 שה\u0003ולדות פטורין מן הבכורה: כיון דאי\u0004 \u0005שאם\u0006 משום מה \u0003לא יהיב זוזי אתי\u0004 \u0005[יתן\u0006 את ה\u0005כסף, יבוא]\u0006 \u0003גוי תפיס לה\u0004 \u0005[\u0006ו\u0005יתפוס אותה]\u0006 את ה\u0003בהמה\u0004 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא משכח לה\u0004 \u0005[ימצא אותה]\u0006 את ה\u0003בהמה תפיס להו\u0004 \u0005[יתפוס אותן]\u0006 את ה\u0003ולדות,\u0004 \u0003והוי ליה\u0004 \u0005[והרי זה]\u0006 מוכיח ש\u0003יד\u0004 ה\u0003גוי באמצע,\u0004 שיש לגוי בעלות מסויימת על גוף הוולדות.","וכלל בידינו: ש\u0003כל\u0004 בהמה שיש בבעלותה \u0003יד גוי באמצע\u0004 — \u0003פטור מן הבכורה.\u0004 אבל לגבי דיני ריבית בישראל — \"צאן ברזל\" הוא לגמרי בבעלותו של המקבל.","נוסף לדיון ההלכתי בדיני ריבית מביאים כמה דברי מוסר ואגדה בנושא זה. נאמר \u0003\"מרבה הונו בנשך ותרבית לחונן דלים יקבצנו\"\u0004 (משלי כח, ח). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לחונן דלים\",\u0004 כיצד מגיע כסף זה לחונן דלים? \u0003אמר רב: כגון שבור מלכא,\u0004 שבסופו של דבר מגיע הכסף למלכות והמלך הוא החונן דלים מרכושו של המלוה בריבית.","\u0003אמר רב נחמן, אמר לי הונא\u0004 (רב הונא): \u0003לא נצרכא\u0004 \u0005[נצרכה],\u0006 \u0003אלא\u0004 ש\u0003אפילו רבית\u0004 שנוטל הישראל מ\u0003גוי\u0004 — בסופו של דבר יורדת לטמיון ואינו מצליח. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן:\u0004 והלא נאמר \u0003\"לנכרי תשיך\u0004 ולאחיך לא תשיך\u0003\"\u0004 (דברים כג, כא), משמע שמותר הדבר, ו\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"תשיך\"\u0004 — \u0003לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003תשוך?\u0004 כלומר, תלוה בריבית ותקבל נשך? ודוחים: \u0003לא, תשיך\u0004 דווקא, כלומר, שאתה תשלם לו נשך.","ושואלים: וכי \u0003לא סגי דלאו הכי\u0004 \u0005[די בלא כך]?\u0006 כלומר, וכי בא הכתוב לחייבנו דווקא ללוות מן הגוי, ולשלם לו ריבית? ומשיבים: אין הכוונה שזו עצמה היא מצוה, אלא ללמד \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 את \u0003אחיך\u0004 הישראלי ש\u0003לא\u0004 תתן לו ריבית.","ומקשים: הלא \u0003אחיך בהדיא כתב ביה\u0004 \u0005[בפירוש כתוב בו]\u0006 באותו פסוק: \u0003\"ולאחיך לא תשיך\"!\u0004 ומשיבים: \u0003לעבור עליו ב'עשה' ו'לא תעשה',\u0004 שאם נותן ריבית לישראל עובר גם משום 'לא תעשה' של \"לא תשיך\" וגם משום מצות 'עשה' של \"לנכרי תשיך\".","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 קושיה אחרת ממה ששנינו במשנתנו: \u0003לוין מהן ומלוין אותם ברבית, וכן בגר תושב,\u0004 ומשמע שמותר לכתחילה! \u0003אמר רב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא: לא נצרכא\u0004 \u0005[נצרכה]\u0006 הלכה זו שבמשנה \u0003אלא\u0004"],["\u0003בכדי חייו\u0004 של המלוה, אבל לא לעשות זאת כעסק קבוע.","\u0003רבינא אמר: הכא\u0004 \u0005[כאן]\u0006 במשנתנו — \u0003בתלמידי חכמים עסקינן\u0004 \u0005[אנו עוסקים]\u0006 אשר להם התירו להלוות לגוי. ומסבירים: \u0003טעמא מאי גזור רבנן\u0004 \u0005[מה טעם גזרו חכמים]\u0006 שלא ילווה בריבית לגוי — \u0003שמא ילמוד ממעשיו,\u0004 שתוך כדי עסקים מתמידים עם הגוי יבוא ללמוד ממנו, \u0003וכיון\u0004 ש\u0003תלמיד חכם הוא\u0004 — \u0003לא ילמוד ממעשיו.\u0004","ומעירים, \u0003איכא דמתני לה להא\u0004 \u0005[יש ששונים,\u0006 לומדים, \u0005את\u0006 ההלכה \u0005הזו]\u0006 שאמר \u0003רב הונא אהא דתני\u0004 \u0005[על זו ששנה]\u0006 \u0003רב יוסף\u0004 שהביא את הברייתא הבאה, נאמר: \u0003\"אם כסף תלוה את עמי את העני עמך\"\u0004 (שמות כב, כד), וכך מלמדנו כתוב זה: אם באו ללות אצלך \u0003עמי וגוי\u0004 — \u0003עמי קודם,\u0004 שהרי מקדים בפסוק \"את עמי\". באו ללוות \u0003עני ועשיר\u0004 — \u0003עני קודם.\u0004 וממה שנאמר \"עמך\" למדים: \u0003ענייך,\u0004 קרובי משפחתך, \u0003ועניי עירך\u0004 — \u0003ענייך קודמין, עניי עירך ועניי עיר אחרת עניי עירך קודמין.\u0004","ודנים בדבר: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 אם באו ללוות אצלך \u0003עמי וגוי\u0004 — \u0003עמי קודם, פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 וכיצד יעלה על דעתנו שיקדים גוי לישראל? \u0003אמר רב נחמן אמר לי הונא\u0004 (רב הונא): \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 הלכה זו ללמד אלא ש\u0003אפילו\u0004 להלוות \u0003לגוי ברבית ולישראל בחנם\u0004 (ללא רווח), אף אז ראוי להקדים ולהלוות לישראל.","ועוד בענין ריבית, \u0003תניא\u0004 \u0005[שנויה\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יוסי: בא וראה סמיות\u0004 (עיוורון) \u0003עיניהם של מלוי ברבית\u0004 אם \u0003אדם קורא לחבירו \"רשע\"\u0004 בשוק — הרי האיש נעלב ו\u0003יורד עמו לחייו\u0004 ומציק לו בכל דרך על שקרא לו בשם גנאי זה. \u0003והם,\u0004 המלוים בריבית, \u0003מביאין עדים ולבלר\u0004 (סופר) \u0003וקולמוס ודיו, וכותבין וחותמין: פלוני זה כפר באלהי ישראל.\u0004 שהרי עצם שטר הריבית שעשה, כנגד האמור בתורה, הוא כפירה באלוקי ישראל.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: כל מי שיש לו מעות ומלוה אותם שלא ברבית\u0004 — \u0003עליו הכתוב אומר \"כספו לא נתן בנשך ושחד על נקי לא לקח עשה אלה לא ימוט לעולם\"\u0004 (תהלים טו, ה), ומן החיוב נלמד על השלילה: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003למדת\u0004 מכאן \u0003שכל המלוה\u0004 מעותיו לאחרים \u0003ברבית נכסיו מתמוטטין.\u0004 ומקשים: \u0003והא קא חזינן דלא מוזפי ברבית\u0004 \u0003וקא\u0004 \u0005[הרי אנו רואים\u0006 אנשים \u0005שאינם מלוים ו\u0006עם כל זה \u0005הם]\u0006 \u0003מתמוטטין!\u0004 \u0003אמר ר' אלעזר:\u0004 בכל זאת יש הבדל; \u0003הללו\u0004 שאינם מלווים בריבית \u0003מתמוטטין ועולין, והללו,\u0004 המלווים בריבית, \u0003מתמוטטין ואינן עולין.\u0004","ומעין אותו ענין בירידתם הזמנית של הישרים, נאמר \u0003\"למה תביט בוגדים תחריש כבלע רשע צדיק ממנו\"\u0004 (חבקוק א, יג), ועל כך \u0003אמר רב הונא: צדיק ממנו\u0004 — \u0003בולע\u0004 לפי שעה, ואולם \u0003צדיק גמור אינו בולע\u0004 כלל.","ולאחר דברים כלליים אלה אנו שבים לביאור משנתנו, ולפני כן מקדימים דיון יסודי יותר. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: גר צדק האמור לענין מכירה\u0004 לעבד, \u0003וגר תושב האמור לענין רבית, איני יודע מה הוא.\u0004 כלומר, אינני יודע לשם מה נכתב.","ומסבירים: \u0003גר צדק האמור לענין מכירה, דכתיב\u0004 \u0005[כתוב]\u0006 \u0003\"וכי ימוך אחיך עמך ונמכר לך\"\u0004 (ויקרא כה, לט) — ודרשו: \u0003ולא לך\u0004 לישראל בלבד, \u0003אלא\u0004 אף \u0003לגר, שנאמר:\u0004 \"ונמכר \u0003לגר\u0004 תושב עמך או לעקר משפחת גר\" (שם מז),","\u0003ולא\u0004 דווקא \u0003לגר צדק אלא\u0004 אף \u0003לגר תושב, שנאמר: \"לגר תושב\"\u0004 (שם). ומה שנאמר אחרי כן \u0003\"משפחת גר\"\u0004 — \u0003זה הגוי,\u0004 שהרי משפחת הגר משפחת גויים היא, ו\u0003כשהוא אומר \"או לעקר\"\u0004 (המתפרש כמו עיקר, שורש), הרי משמעו: \u0003\"זה הנמכר לעבודה זרה עצמה\".\u0004","ומעתה מבררים את הברייתא, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ולא לך אלא לגר, שנאמר: \"לגר\", למימרא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 מכאן שה\u0003גר קני\u0004 \u0005[קונה]\u0006 \u0003עבד עברי? ורמינהי\u0004 \u0005[ומטילים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003אין הגר נקנה\u0004 בתורת \u0003עבד עברי, ואין אשה וגר קונין עבד עברי.\u0004","ומסבירים את ההלכות הללו: \u0003לא נקנה בעבד עברי\u0004 משום שבדיני העבד העברי \u0003\"\u0004ויצא מעמך... \u0003ושב אל משפחתו\"\u0004 (שם מא) \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003והא ליכא\u0004 \u0005[וזה אינו],\u0006 שהרי הגר עם התגיירותו מנתק את הקשר המשפחתי עם משפחתו הגויית, ואין לו איפוא כל משפחה בין הגויים. ומה שנאמר \u0003ואין אשה וגר קונין עבד עברי\u0004 הטעם הוא: \u0003אשה\u0004 — \u0003לאו אורח ארעא\u0004 \u0005[אינו דרך ארץ]\u0006 שכן עלולים לחושדה שהיא קונה איש לעצמה. \u0003גר נמי\u0004 \u0005[גם כן]\u0006 \u0003גמירי\u0004 \u0005[למודים אנו\u0006 בהלכה\u0005]:\u0006 זה \u0003דמקני\u0004 \u0005[שנקנה\u0006 כעבד\u0005]\u0006 — \u0003קני\u0004 \u0005[קונה],\u0006 זה \u0003דלא מקני\u0004 \u0005[שאינו נקנה\u0006 כעבד\u0005]\u0006 — \u0003לא קני\u0004 \u0005[אינו קונה],\u0006 וכיון שהוכחנו שגר אינו נקנה כעבד — גם אינו קונה. וזה היה הקושי של רבי: שמאחר שאמרנו שאין הגר קונה עבד — מה טעם הזכיר זאת הכתוב?","\u0003אמר\u0004 לתרץ \u0003רב נחמן בר יצחק,\u0004 כך יש להבין: \u0003אינו קונה ודינו כישראל,\u0004 שגר אינו יכול לקנות עבד עברי כשאר ישראלים העושים כן, \u0003אבל קונה\u0004 עבד עברי, אלא שאז \u0003דינו כגוי\u0004 הקונה עבד עברי.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 עבד \u0003הנרצע,\u0004 שדינו אינו יוצא בשנה השביעית אלא רק ביובל, וכן \u0003הנמכר לגוי\u0004 — \u0003אינו עובד לא את הבן ולא את הבת,\u0004 אלא משתחרר עם מיתת האדון. ולכאורה תמוה, שאם אמנם נמכר העבד לגוי מדוע יקיימו בני הגוי את דיני התורה וישחררו את העבד? אלא ודאי הכוונה היא שנמכר לגר צדק, שדינו לענין זה כגוי, אבל הוא ובניו שומעים לדברי תורה. ואם כן, מצאנו עוד ראיה שגר יכול לקנות עבד עברי.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ואין אשה וגר קונין עבד עברי.\u0004 ושואלים: \u0003נימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 שברייתא זאת אינה \u0003כ\u0004דעת \u0003רבן שמעון בן גמליאל? דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003אשה קונה את השפחות, ואינה קונה את העבדים\u0004 כדי שלא לפגוע בצניעות. \u0003רבן שמעון בן גמליאל אומר: אף קונה את העבדים!\u0004 ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שברייתא זו כשיטת \u0003רבן שמעון בן גמליאל,\u0004 \u0003ו\u0004אולם הדבר \u0003לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003כאן\u0004 שאסרו — מדובר \u0003בעבד עברי, כאן\u0004 — שהתיר רבן שמעון בן גמליאל — הרי זה \u0003בעבד כנעני.\u0004","ומסבירים את טעם ההבדל: \u0003עבד עברי צניע\u0004 \u0005[צנוע]\u0006 \u0003לה\u0004 והיא בטוחה שלא יגלה את סודותיה, ולכן אסרו עליה לקנות עבד עברי, שלא תגיע לידי עבירה. אבל \u0003עבד כנעני פריץ\u0004 \u0005[פרוץ]\u0006 \u0003לה\u0004 בעיניה שיפרסם את הדבר ולכן לא תעבור עמו עבירה.","ושואלים: \u0003אלא הא דתני\u0004 \u0005[\u0006ברייתא \u0005זו ששנה]\u0006 \u0003רב יוסף,\u0004 \u0003ארמלתא\u0004 \u0005[אלמנה]\u0006 \u0003לא תרבי כלבא\u0004 \u0005[תגדל כלב]\u0006 שמא יחשדוה שמגדלת אותו לצורך משכב בהמה, \u0003ולא תשרי בר בי רב באושפיזא\u0004 \u0005[תחזיק תלמיד חכם\u0006 צעיר \u0005כאכסנאי\u0006 בביתה\u0005].\u0006 ויש לשאול: \u0003בשלמא בר בי רב צניע לה\u0004 \u0005[נניח בתלמיד חכם אסור\u0006 שהרי הוא \u0005צנוע בעיניה]\u0006 ובטוחה שאם תחטא עמו לא יספר, \u0003אלא כלבא\u0004 \u0005[הכלב],\u0006 \u0003כיון דמסריך בה מירתתא\u0004 \u0005[שיגרר אחריה, היא מפחדת]!\u0006 \u0003אמרי\u0004 \u0005[אומרים]\u0006 לתרץ: כלב \u0003כיון דכי שדיא ליה אומצא מסריך בתרה\u0004 \u0005[שכאשר\u0006 היא \u0005זורקת לו חתיכת בשר\u0006 הוא \u0005נגרר אחריה],\u0006 על כן \u0003אמרי אינשי\u0004 \u0005[יאמרו אנשים]:\u0006 \u0003משום אומצא דשדיא ליה\u0004 \u0005[חתיכת הבשר שהיא זורקת לו]\u0006 \u0003הוא דמסריך\u0004 \u0005[שנגרר],\u0006 ולא יבואו לחשדה בעבירה.","עד כאן דנו בקושי אחד של רבי, וקושי אחר היה: \u0003גר תושב האמור לענין רבית, מאי היא\u0004 \u0005[מה הוא\u0006 עניינו\u0005]?\u0006 \u0003דכתיב\u0004 \u0005[שכתוב]\u0006 בתורה: \u0003\"וכי ימוך אחיך ומטה ידו עמך והחזקת בו גר ותושב וחי עמך. אל תקח מאתו נשך ותרבית ויראת מאלהיך וחי אחיך עמך\"\u0004 (שם לה –לו), הרי שגר תושב אין לוקחים ממנו ריבית. \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005],\u0006 הרי נאמר במשנתנו: \u0003לוין מהן ומלוין אותן ברבית, וכן בגר תושב!\u0004","\u0003אמר רב נחמן בר יצחק: מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"אל תקח מאתם\"?\u0004 הלא \u0003\"מאתו\" כתיב\u0004 בלשון יחיד, ולכן יש להבין; \u0003מישראל\u0004 אל תקח.","על כתוב זה עצמו \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"אל תקח מאתו נשך ותרבית\"\u0004 — \u0003אבל אתה נעשה לו ערב\u0004 בעסקת ריבית."],["\u0003ערב למאן\u0004 \u0005[למי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ערב לישראל,\u0004 שמלוה בריבית \u0003והא תנא\u0004 \u0005[והרי שנה\u0006 החכם\u0005]:\u0006 \u0003אלו עוברין ב\"לא תעשה\": המלוה הלוה, הערב והעדים!\u0004","\u0003אלא\u0004 הכוונה היא \u0003לגוי\u0004 המלוה לישראל בריבית, ואולם גם אז קשה: \u0003וכיון דדיניה\u0004 \u0005[שדינו]\u0006 של ה\u0003גוי דאזיל בתר ערבא\u0004 \u0005[ש\u0006הוא \u0005הולך אחר הערב],\u0006 שבדיניהם יכול המלוה להקדים ולגבות מן הערב, יצטרך הערב לפרוע ולקבל את הכסף מחבירו הלווה, ונמצא כי \u0003איהו ניהו דקא שקיל מיניה רביתא\u0004 \u0005[הוא הוא שלוקח ממנו ריבית]!\u0006 וכיצד מותר הדבר?","\u0003אמר רב ששת:\u0004 כאן מדובר \u0003שקיבל עליו\u0004 הגוי \u0003לדון בדיני ישראל\u0004 ולכן יקדים להפרע מן הלווה. ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003קיבל עליו\u0004 הגוי \u0003לדון בדיני ישראל\u0004 — אם כן \u0003רבית נמי\u0004 \u0005[גם כן]\u0006 \u0003לא לשקול\u0004 \u0005[יקח],\u0006 שהרי בדיני ישראל אסור הדבר! \u0003אמר רב ששת:\u0004 כאן מדובר באופן \u0003שקיבל עליו\u0004 דיני ישראל \u0003לזו,\u0004 לענין סדרי ודרכי הפרעון, \u0003ולא קיבל עליו לזו\u0004 את איסורי התורה.","שנינו במשנה: \u0003מלוה ישראל מעותיו של גוי מדעת הגוי,\u0004 אבל לא מדעת ישראל. \u0003תנו רבנן\u0004 בברייתא שנינו: \u0003מלוה ישראל מעותיו של גוי מדעת הגוי אבל לא מדעת ישראל, כיצד?\u0004 — \u0003ישראל שלוה מעות מן הגוי ברבית וביקש להחזירם לו,\u0004 ובינתים \u0003מצאו ישראל אחר ואמר לו:\u0004 כיון שאתה אינך נזקק עוד לכספים אלה, ואני צריך אותם להלוואה, \u0003תנם לי ואני אעלה\u0004 (אשלם) \u0003לך\u0004 בתוספת ריבית \u0003כדרך שאתה מעלה לו\u0004 — \u0003אסור,\u0004 מפני שיש כאן מתן ריבית לישראל. \u0003ואם העמידו אצל גוי,\u0004 שהלווה הראשון הביא את השני אצל גוי, והסכים הגוי להסדר הזה — הרי זה \u0003מותר.\u0004","\u0003וכן גוי שלוה מעות מישראל ברבית וביקש להחזירם לו, מצאו ישראל אחר\u0004 לאותו גוי, \u0003ואמר לו: תנם לי ואני אעלה לך\u0004 ריבית \u0003כדרך שאתה מעלה לו\u0004 — \u0003מותר,\u0004 שהרי הוא משלם ריבית לגוי ולא לישראל. אבל \u0003אם העמידו אצל ישראל\u0004 — \u0003אסור.\u0004","ומבררים: \u0003בשלמא סיפא\u0004 \u0005[נניח בסופה\u0006 של ההלכה\u0005],\u0006 שאסרו לשלם כשישראל יודע בדבר — הרי זה משום \u0003חומרא\u0004 של חשש ריבית, \u0003אלא רישא\u0004 \u0005[\u0006במקרה \u0005הראשון]\u0006 שאמנם העמידו לפני הגוי, והרי משמעות הדבר שנעשה שליח לגוי, ואולם \u0003כיון\u0004 שעל פי ההלכה \u0003אין שליחות לגוי\u0004 ושליחו אינו נחשב כמוהו, אלא כעושה על דעת עצמו, אם כן, נמצא \u0003איהו ניהו דקא שקיל מיניה רביתא\u0004 \u0005[הוא הוא שלוקח ממנו ריבית],\u0006 ומדוע מתירה הברייתא?","\u0003אמר רב הונא בר מנוח משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון\u0004 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 הגוי בשעה שהחזיר לו הכסף: \u0003הניחם על גבי קרקע והיפטר,\u0004 ואחר כך הלך הישראל האחר ולקח. ומקשים: \u0003אי הכי, מאי למימרא\u0004 \u0005[אם כך, מה\u0006 יש \u0005לומר],\u0006 שאם החזיר לגוי את כספו — יש פה שתי הלואות שונות, שגוי הלוה לשני ישראלים ובוודאי מותר!","\u0003אלא\u0004 \u0003אמר רב פפא:\u0004 יש לשנות קצת את ההסבר, וכאן מדובר \u0003כגון שנטל ונתן ביד,\u0004 כלומר, שלקח הגוי את זה מיד הישראל הראשון והעבירו מיד לשני. ושואלים: \u0003ואכתי, מאי למימרא\u0004 \u0005[ועדיין, מה\u0006 יש \u0005לומר],\u0006 שהרי בבירור היתה זו הלוואה של גוי?! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 ה\u0003גוי גופיה כי עביד\u0004 \u0005[עצמו כאשר\u0006 הוא \u0005עושה]\u0006 ומלוה זאת — \u0003אדעתא\u0004 \u0005[על דעת]\u0006 ה\u0003ישראל קא גמיר ויהיב\u0004 \u0005[הוא גומר ונותן],\u0006 שהרי הוא סומך על נאמנותו של הלווה השני משום תווכו של הראשון, ואפשר היה לומר שהוא נחשב כמעורב בהלוואה, ולכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין חוששים לכך.","\u0003רב אשי אמר\u0004 שאפשר לתרץ באופן אחר: \u0003כי אמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006 את הכלל \u0003אין שליחות לגוי\u0004 — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 בהפרשת \u0003תרומה,\u0004 ששם נרמזה הלכה זו בתורה, \u0003אבל בכל התורה כולה\u0004 בשאר הלכות — \u0003יש שליחות לגוי.\u0004","ומעירים: \u0003והא\u0004 \u0005[ו\u0006סברה \u0005זו]\u0006 של \u0003רב אשי ברותא\u0004 \u0005[חיצונית]\u0006 \u0003היא,\u0004 שאיננה דבר שאפשר לסמוך עליו. כי, \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003תרומה\u0004 ש\u0003לא\u0004 עושים גוי שליח — משום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \"כן תרימו גם אתם תרומת ה'\" (במדבר יח, כח) ודורשים \u0003\"אתם\"\u0004 — \u0003\"גם אתם\",\u0004 כהשוואה: \u0003מה אתם\u0004 התורמים הנכם \u0003בני ברית\u0004 — \u0003אף שלוחכם נמי\u0004 \u0005[גם כן]\u0006 צריכים להיות \u0003בני ברית.\u0004","ואולם דין \u0003שליחות\u0004 שב\u0003כל התורה כולה נמי\u0004 \u0005[גם כן]\u0006 \u0003מתרומה גמרינן לה\u0004 \u0005[אנחנו לומדים אותו],\u0006 שזה המקור להנחה ששליחו של אדם כמותו, ואם כן, האמור בתרומה חל על כל דיני התורה. \u0003אלא\u0004 חייבים לומר שסברה זו שאמר \u0003רב אשי ברותא\u0004 \u0005[חיצונית]\u0006 \u0003היא\u0004 ואין להתחשב בה.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שבנוסח אחר \u0003אמר רב אשי: כי אמרינן\u0004 \u0005[כאשר אומרים אנו]\u0006 ש\u0003אין שליחות לגוי\u0004 — \u0003הני מילי אינהו לדידן\u0004 \u0005[דברים אלה\u0006 אמורים \u0005שהם\u0006 יהיו שלוחים \u0005עבורנו],\u0006 \u0003אבל אנן לדידהו הוינא להו שליח\u0004 \u0005[אבל אנחנו עבורם נעשים להם שלוחים].\u0006 ועל כך אמרו: \u0003והא\u0004 \u0005[ו\u0006סברה \u0005זו]\u0006 של \u0003רב אשי ברותא\u0004 \u0005[חיצונית]\u0006 \u0003היא,\u0004 והטעם: \u0003מאי שנא אינהו לדידן\u0004 \u0005[מה שונה הם עבורנו]\u0006 ש\u0003לא\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"אתם\",\u0004 ואילו \u0003\"גם אתם\"\u0004 בא \u0003לרבות שלוחכם\u0004 כמותכם, ומכתוב זה עצמו נובע גם: \u0003מה אתם בני ברית\u0004 — \u0003אף שלוחכם בני ברית.\u0004","ואם כן, \u0003אנן לדידהו נמי\u0004 \u0005[אנו עבורם גם כן]\u0006 \u0003מה אתם בני ברית קאמר\u0004 \u0005[אמר],\u0006 ושאינם בני ברית — לא למדנו שעושים שליח. \u0003אלא\u0004 ודאי \u0003הא\u0004 \u0005[\u0006סברה \u0005זו]\u0006 של \u0003רב אשי ברותא\u0004 \u0005[חיצנית]\u0006 \u0003היא\u0004 ואין לסמוך עליה.","\u0003רבינא אמר\u0004 תירוץ אחר: \u0003נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003שליחות לגוי לית ליה\u0004 \u0005[אין לו],\u0006 ואולם כוח \u0003זכיה\u0004 על ידי אחר הזוכה עבורו לפחות \u0003מדרבנן אית ליה\u0004 \u0005[מדברי סופרים יש לו],\u0006 \u0003מידי דהוי\u0004 \u0005[כמו שהוא\u0006 הדין\u0005]\u0006 ביחס ל\u0003קטן\u0004 מישראל. כי \u0003קטן לאו אף על גב דלית ליה\u0004 \u0005[באם לא אך על פי שאין לו]\u0006 דין \u0003שליחות,\u0004 שהרי אינו בר דעת,"],["\u0003אית ליה\u0004 \u0005[יש לו]\u0006 כח \u0003זכיה\u0004 על ידי אחר הזוכה עבורו \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 שאדם אחר יכול לזכות עבורו בדברים. אם כן, \u0003הכא נמי לא שנא\u0004 \u0005[כאן גם כן\u0006 הגוי \u0005אינו שונה]\u0006 ולכן אפשר לזכות עבור הגוי.","ודוחים: \u0003ולא היא\u0004 (ואינו כן), שיש להבדיל בין הדברים: \u0003ישראל אתי\u0004 \u0005[בא]\u0006 \u0003לכלל שליחות,\u0004 שגם אם קטן הוא עכשיו, לכשיגדל יהיה ראוי לשליחות, מה שאין כן \u0003גוי לא אתי\u0004 \u0005[אינו בא]\u0006 \u0003לכלל שליחות.\u0004 ולכן לא תקנו לו גם זכיה, ואם כן עלינו לחזור לתירוץ הראשון.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ישראל שלוה מעות מן הגוי ברבית,\u0004 והגוי \u0003זקפן\u0004 את דמי הריבית \u0003עליו במלוה,\u0004 שצירף את סכום הריבית לגוף ההלוואה עצמה, \u0003ונתגייר\u0004 אותו גוי; \u0003אם קודם שנתגייר זקפן עליו במלוה\u0004 — \u0003גובה\u0004 מן הישראל גם \u0003את הקרן וגובה את הרבית,\u0004 שהרי כבר נעשה הכל בהלוואה אחת. \u0003ואם לאחר שנתגייר זקפן עליו במלוה\u0004 — \u0003גובה את הקרן ואינו גובה את הרבית.\u0004","\u0003וכן גוי שלוה מעות מישראל ברבית וזקפן עליו במלוה ונתגייר\u0004 הלווה הגוי, \u0003אם עד שלא נתגייר זקפן עליו במלוה\u0004 — \u0003גובה\u0004 ממנו הישראל גם \u0003את הקרן וגובה את הרבית. אם משנתגייר זקפן עליו במלוה\u0004 — \u0003גובה את הקרן ואינו גובה את הרבית.\u0004","ואילו \u0003ר' יוסי אומר: גוי שלוה מעות מישראל ברבית\u0004 ונתגייר, \u0003בין כך ובין כך,\u0004 גם אם זקף את הריבית וצרפה לקרן לאחר זמן — \u0003גובה\u0004 המלוה ממנו \u0003את הקרן וגובה את הרבית. אמר רבא אמר רב חסדא אמר רב הונא: הלכה כר' יוסי. אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי\u0004 בהלכה זו, שלכאורה מנוגדת לעקרון שבהלכה הקודמת — \u0003כדי שלא יאמרו בשביל מעותיו נתגייר זה.\u0004 שיבואו לחשדו שנתגייר כדי שלא יצטרך לשלם את הריבית.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שטר שכתוב בו רבית\u0004 — \u0003קונסין אותו,\u0004 את המלוה, \u0003ואינו גובה לא את הקרן ולא את הרבית,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: גובה את הקרן ואינו גובה את הרבית.\u0004 ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 באיזה עיקרון \u0005נחלקו]?\u0006 ומסבירים: \u0003ר' מאיר סבר: קנסינן התירא\u0004 \u0005[קונסים אנו\u0006 גם את חלק \u0005ההיתר]\u0006 \u0003משום איסורא\u0004 \u0005[האיסור],\u0006 \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003לא קנסינן התירא\u0004 \u0005[אין אנו קונסים\u0006 גם את חלק \u0005היתר]\u0006 \u0003משום איסורא\u0004 \u0005[האיסור].\u0006","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003שטרי חוב המוקדמין\u0004 שכתב בהם תאריך לפני זמן ההלוואה — \u0003פסולים, והמאוחרין\u0004 — \u0003כשרין.\u0004 ושואלים: \u0003מוקדמין אמאי\u0004 \u0005[מדוע]\u0006 יהיו \u0003פסולין\u0004 לגמרי? \u0003נהי\u0004 \u0005[\u0006\u0005אם\u0006 \u0005אמנם]\u0006 ש\u0003לא גבו מזמן ראשון\u0004 הכתוב בהם, שהרי יכול להביא לידי הפסד לאנשים אחרים, לפחות \u0003ניגבו\u0004 \u0005[יגבו]\u0006 \u0003מזמן שני,\u0004 שבו היתה ההלוואה בפועל!","\u0003אמר ר' שמעון בן לקיש:\u0004 משנה זו \u0003במחלוקת\u0004 היא \u0003שנויה,\u0004 שאיננה כדברי הכל, אלא כשיטת \u0003ר' מאיר\u0004 היא, שאמר שקונסין היתר משום איסור. ואף כאן, כיון שטעה וכתב תאריך בלתי נכון העלול להביא לנזק — פסלו את השטר כולו. ו\u0003ר' יוחנן אמר: אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שמשנה זו \u0005כדברי\u0006 \u0005חכמים]\u0006 — כאן גזרו חכמים עצמם מטעם אחר: \u0003גזירה שמא יגבה מזמן ראשון,\u0004 שאם לא ייפסל השטר יסמכו עליו, ויבואו לגבות לפי התאריך הכתוב בו.","מסופר: \u0003ההוא גברא דמשכין ליה פרדיסא לחבריה, אכלה תלת שני\u0004 \u0005[אדם אחד משכן פרדס לחבירו\u0006 כבטחון להלוואה, ו\u0005אכל\u0006 המלוה את הפרדס במשך \u0005שלש שנים].\u0006 בסוף הזמן אמר המחזיק ללוה: \u0003אי מזבינת לה ניהלי\u0004 \u0005[אם מוכר אתה אותו,\u0006 את השדה, \u0005לי]\u0006 — \u0003מוטב\u0004 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003כבישנא לה\u0004 \u0005[אכבוש,\u0006 אסתיר \u0005אותו]\u0006 את \u0003שטר\u0004 ה\u0003משכנתא ואמינא\u0004 \u0005[ואומר]:\u0006 \u0003\"לקוחה היא בידי\",\u0004 שקניתי את השדה ואבדתי את שטר המכירה, וכיון שהיה השדה בחזקתי שלוש שנים לא אצטרך להביא הוכחות אחרות, שהרי כלל הוא שאחרי שלוש שנים של שימוש בשדה יש חזקת בעלות למשתמש בו.","כיון שראה הלווה שאינו יכול להשתמט נקט בדרכי ערמה: \u0003אזל, קם אקנייה\u0004 \u0005[הלך\u0006 אותו אדם \u0005עמד והקנה]\u0006 קודם את השדה \u0003לבנו\u0004 ה\u0003קטן\u0004 בשטר מתנה, \u0003והדר זבנה ניהליה\u0004 \u0005[ואחר\u0006 כך \u0005מכר לו]\u0006 את השדה. ולאחר מכן תבע מן הקונה לבטל את המכר, שהרי כשנמכר לא היה השדה שלו.","ומבררים את ההלכה: \u0003זביני\u0004 \u0005[המכירה]\u0006 \u0003ודאי לא הוי זביני\u0004 \u0005[היתה מכירה],\u0006 שהרי לא היתה השדה שלו. אלא השאלה היא: \u0003זוזי\u0004 \u0005[הדינרים]\u0006 ששילם הקונה האם \u0003כמלוה בשטר דמו\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006 ואז \u0003גובה מנכסים משועבדים\u0004 של המוכר שנמכרו במשך הזמן לאחרים, \u0003או דילמא\u0004 \u0005[שמא],\u0006 \u0003כמלוה על פה דמו\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006 \u0003ואינו גובה מנכסים משועבדים? אמר אביי: ולאו היינו\u0004 \u0005[והאם אין בעיה זו]\u0006 דומה לזו של \u0003ר' אסי,\u0004 ש\u0003אמר ר' אסי:\u0004"],["\u0003מודה בשטר שכתבו\u0004 — המלוה \u0003אינו צריך לקיימו\u0004 בבית דין, שהרי אין מערער על עצם ההתחייבות, \u0003וגובה מנכסים משועבדים.\u0004 ואף כאן, הרי המוכר מודה שקיבל את הכסף.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מי דמי\u0004 \u0005[האם דומה]\u0006 הדבר? \u0003התם\u0004 \u0005[שם]\u0006 \u0003ניתן\u0004 הדבר \u0003להכתב,\u0004 והשטר שנכתב יש בו ממש, ולכן אפשר לגבות בו. אבל \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003לא ניתן\u0004 הדבר \u0003להכתב,\u0004 שהרי כל המכירה כולה לא היה בה ממש, ובעל כרחו של המוכר היתה, וכיון שכך — אפשר לומר שהשטר בטל מעיקרו כמסמך פומבי, וממילא אינו גובה מנכסים משועבדים.","מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003מרימר וקאמר להא שמעתא\u0004 \u0005[ואמר את השמועה הזו]\u0006 כולה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא למרימר: אלא\u0004 אם מקבלים את שיטת רבא אם כן \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר\u0004 \u0003ר' יוחנן\u0004 בשטר מוקדם שפסולו הוא \u0003גזירה שמא יגבה מזמן ראשון, נימא\u0004 \u0005[שיאמר]\u0006 נימוק טוב יותר, כרבא: שהשטר המוקדם \u0003לא ניתן ליכתב! אמר ליה\u0004 \u0005[לו]\u0006 מרימר: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם,\u0006 בשטר מוקדם\u0005]\u0006 \u0003נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003לא ניתן ליכתב מזמן ראשון, אבל ניתן ליכתב מזמן שני,\u0004 שהרי עצם הנושא ניתן ליכתב. \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003לא ניתן ליכתב כלל.\u0004","ושואלים עוד: \u0003אלא הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003לשבח קרקעות כיצד\u0004 מוציאים? \u0003הרי שגזל שדה מחבירו ומכרה לאחר\u0004 והקונה \u0003השביחה, והרי היא יוצאה מתחת ידו\u0004 של המעבד, שהרי מתברר שקנה דבר שאינו שלו. \u0003כשהוא גובה\u0004 מן הגזלן שמכר לו את השדה — \u0003גובה את הקרן מנכסים משועבדים\u0004 של הגזלן, \u0003ושבח\u0004 שהשביח \u0003גובה מנכסים בני חורין. נימא\u0004 \u0005[נאמר]:\u0006 גם שם שעיסקת מכירה זו של הגזלן היא בגדר \u0003לא ניתן ליכתב\u0004 ולכן לא יגבה גם את הקרן!","ודוחים: \u0003הכי השתא\u0004 \u0005[איך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 הקונה מן הגזלן, יש משמעות לשטר המכירה לפי שיטות שונות, \u0003אי למאן דאמר ניחא ליה\u0004 \u0005[אם ל\u0006דעת \u0005מי שאומר\u0006 ש\u0005נוח לו]\u0006 ש\u0003לא נייקריה גזלנא\u0004 \u0005[יקרא לו גזלן],\u0006 \u0003אי למאן דאמר ניחא ליה דליקום בהימנותיה\u0004 \u0005[או ל\u0006דעת \u0005מי שאומר\u0006 ש\u0005נוח לו שישאר בנאמנותו],\u0006 ומשום כך הריהו \u0003מפייס ליה למריה ומוקים ליה לשטריה\u0004 \u0005[את בעליו\u0006 של השדה \u0005ו\u0006מנסה \u0005להעמיד את שטרו],\u0006 ששטר המכירה שכתב יהיה בו ממש. \u0003הכא, לאברוחי מיניה קמכוין, שטרא מקיים ליה\u0004 \u0005[כאן,\u0006 הרי \u0005להבריח ממנו\u0006 מן הקונה הוא \u0005מתכוון,\u0006 וכי \u0005יקיים לו\u0006 את \u0005שטרו],\u0006 ואם כן שטר זה לא היה בו כל ממש, ולא היתה כל כוונה לקיימו, ולכן אין אנחנו מתחשבים בו כלל.","\u0003אין פוסקין על הפירות\u0004 לקבוע מראש מחיר לפירות \u0003עד שיצא השער\u0004 שיקבע מחיר יציב עבור הפירות, שאם לא כן שמא קבע מחיר נמוך יותר, ונמצא כמלוה בריבית. ואם \u0003יצא השער\u0004 — \u0003פוסקין\u0004 גם אם אין הפירות מצויים עדיין בידי המוכר. והטעם: \u0003אף על פי שאין לזה יש לזה,\u0004 ולכן הרי זה קנין גמור משעת ההסכם.","\u0003היה הוא,\u0004 אותו אדם, שמקבל את הכסף \u0003תחילה\u0004 (ראשון) בין ה\u0003קוצרים,\u0004 ועדיין לא נקבע השער, \u0003פוסק עמו\u0004 וקוצב מחיר כרצונו \u0003על הגדיש\u0004 של תבואה שישנו כבר ברשותו, או \u0003על העביט\u0004 (כלי גדול לצבירה לצורך דריכה) \u0003של ענבים,\u0004 או \u0003על המעטן\u0004 (כלי לצבירה) \u0003של זיתים, ועל הביצים\u0004 (כדורים של חימר) \u0003של\u0004 ה\u0003יוצר, ועל הסיד\u0004 שכבר הגיע כמעט לגמר מלאכה \u0003מששקעו בכבשן.\u0004","\u0003ופוסק עמו\u0004 מחיר \u0003על הזבל כל ימות השנה,\u0004 שהרי הזבל בוודאי יהיה שם וכאילו היה מוכן מעכשיו. \u0003ר' יוסי אומר: אין פוסקין על הזבל אלא אם כן היתה לו\u0004 כבר ערימת \u0003זבל באשפה\u0004 שעליה יכול הקנין לחול מיד, \u0003וחכמים מתירים.\u0004","\u0003ופוסק עמו\u0004 אז גם \u0003בשער הגבוה,\u0004 כלומר, הרבה פירות במחיר הזול ביותר, שמתנה עם המוכר שהשער למכירה יהיה במחיר הזול ביותר שיהא למוצר זה במשך השנה. \u0003ר' יהודה אומר: אף על פי שלא פסק עמו\u0004 מראש \u0003בשער הגבוה\u0004 — \u0003יכול לומר\u0004 למוכר: \u0003תן לי כזה\u0004 לפי השער הגבוה שיש עכשיו, \u0003או תן לי את מעותי\u0004 בחזרה, שכיון שלא משך לא נעשה קנין. ואם נשתנה המחיר יכול לחזור בו תמיד מן העיסקה.","\u0003אמר ר' אסי אמר ר' יוחנן: אין פוסקין על השער שבשוק\u0004 משום שאיננו קבוע דיו, אלא על שער של מדינה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' אסי:\u0004 האם \u0003אמר ר' יוחנן אפילו כדורמוס\u0004 (בשוק הגדול) \u0003הזה,\u0004 שהוא שוק מרכזי? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא אמר ר' יוחנן אלא בשוק של עיירות, דלא קביעי תרעייהו\u0004 \u0005[שאין שערם קבוע]\u0006 שהוא תלוי בשווקים גדולים יותר.","ושואלים: \u0003ולמאן דסליק אדעתין מעיקרא\u0004 \u0005[ולמה שעלה על דעתנו מתחילה]\u0006 ש\u0003אמר ר' יוחנן אפילו כדורמוס הזה, אלא מתניתין דקתני\u0004 \u0005[משנתנו ששנה\u0006 בה\u0005]:\u0006 \u0003אין פוסקין על הפירות עד שיצא השער, יצא השער\u0004 — \u0003פוסקין, היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותה]\u0006 שאפשר לקבוע שער? ומשיבים: \u0003בחיטי דאכלבי וארבי, דמשוך תרעיה טפי\u0004 \u0005[בחיטים הבאים מהמחסנים\u0006 הגדולים \u0005ומן האוניות, שמשך שערם יותר]\u0006 לפי שמדובר בכמויות גדולות מאוד.","\u0003תנו רבנן\u0004 שנו חכמים: \u0003אין פוסקין על הפירות עד שיצא השער, יצא השער\u0004 — \u0003פוסקין, אף על פי שאין לזה יש לזה. היו\u0004 ה\u0003חדשות,\u0004 התבואה החדשה, \u0003מארבע\u0004 סאין בסלע \u0003וישנות משלש\u0004 — \u0003אין פוסקין\u0004 לפי שער החדשות \u0003עד שיצא השער\u0004 גם \u0003לחדש ו\u0004גם \u0003לישן.\u0004 כי לאחר זמן מסויים גם החדשות שוב אינן חדשות לגמרי, ומחירן עולה.","וכן \u0003היו לקוטות\u0004 שמלקטים חיטים משדות שונים, שטיבן אינו מעולה, \u0003מארבע\u0004 סאין בסלע, \u0003ולכל אדם משלש\u0004 — \u0003אין פוסקין\u0004 בשער הלקוטות \u0003עד שיצא השער ללוקט ולמוכר.\u0004","\u0003אמר רב נחמן: פוסקין ללקוטות כשער הלקוטות. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003לוקט\u0004 שיכול לקבוע מיד בשער הלקוטות — \u0003דאי לית ליה יזיף מלקוט חבריה\u0004 \u0005[שאם אין לו הוא לווה מלוקט חבירו]\u0006 תבואה זו, והרי היא כמצויה מיד בידו, \u0003בעל הבית נמי\u0004 \u0005[גם כן]\u0006 יכול לקבוע בשער הלקוטות, שאם אין לו \u0003יזיף מלקוט\u0004 \u0005[\u0006יכול \u0005ללוות מלוקט]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בעל הבית זילא ביה מילתא למיזף מלקוט\u0004 \u0005[בעל הבית בזוי\u0006 בעיניו הדבר \u0005ללוות מן הלוקט]\u0006 וכן יש צורך בקביעת שער מיוחד לבעלי בתים. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ אחר: \u0003מאן דיהיב זוזי\u0004 \u0005[מי שנותן זוזי,\u0006 כסף\u0005]\u0006 \u0003לבעל הבית\u0004 עבור תבואה — \u0003אפירי שפירי יהיב\u0004 \u0005[על פירות טובים\u0006 הוא \u0005נותן]\u0006 ואינו רוצה בתבואת הלקוטות.","\u0003אמר רב ששת אמר רב הונא: אין לוין על שער שבשוק,\u0004 שאין קונים כמות מסויימת על מנת לשלם אחר כך לפי השער שנקבע בשוק, אף על פי שיש תבואה במחיר זה במקום אחר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף בר חמא לרב ששת, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב יוסי בר אבא לרב ששת: ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב הונא הכי\u0004 \u0005[כך]?\u0006 \u0003והא בעי מיניה\u0004 \u0005[והרי שאלו ממנו]\u0006 \u0003מרב הונא:\u0004 \u0003הני\u0004 \u0005[אותם]\u0006 \u0003בני בי\u0004 \u0005[בית]\u0006 ה\u0003רב,\u0004 בני בית המדרש, \u0003דיזפי\u0004 \u0005[שלווין]\u0006 אוכל \u0003ב\u0004חודש \u0003תשרי ופרעי\u0004 \u0005[ופורעים]\u0006 את המחיר \u0003בטבת,\u0004 האם \u0003שרי\u0004 \u0005[מותר]\u0006 הדבר \u0003או אסיר\u0004 \u0005[אסור]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הא חיטי\u0004 \u0005[הרי\u0006 יש \u0005חיטים]\u0006 \u0003ב\u0004עיירה \u0003היני והא חיטי\u0004 \u0005[הרי\u0006 יש \u0005חיטים]\u0006 \u0003ב\u0004עיירה \u0003שילי, אי בעי\u0004 \u0003זבני ופרעי ליה\u0004 \u0005[\u0006ו\u0005אם היו רוצים\u0006 היו \u0005קונים ופורעים לו\u0006 מתחילה\u0005],\u0006 שכיון שבידם לפרוע בכל עת — אין בכך משום ריבית.","ומסבירים: \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003סבר\u0004 \u0005[חשב]\u0006 \u0003רב הונא\u0004 לומר ש\u0003אין לוין, כיון\u0004 ש\u0003שמעה להא\u0004 \u0005[לזו]\u0006 ש\u0003אמר רב שמואל בר חייא אמר ר' אלעזר: לוין,\u0004 חזר בו ו\u0003אמר איהו נמי\u0004 \u0005[הוא גם כן]:\u0006 \u0003לוין.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המוליך חבילה\u0004 של סחורה שקנה \u0003ממקום למקום,\u0004 שקנה אותה בזול ומוביל למקום שהיא ביוקר למוכרה שם, ו\u0003מצאו חבירו\u0004 בדרך \u0003ואמר לו: \"תנה לי\u0004 את החבילה \u0003ואני אעלה\u0004 (אשלם) \u0003לך כדרך שמעלים לך באותו מקום\u0004 שאליו אתה מוביל את סחורתך \u0003\",\u0004"],["אם החבילה \u0003ברשות מוכר,\u0004 שהוא מקבל על עצמו אחריות עבור כל נזק שיארע בדרך — \u0003מותר,\u0004 אם \u0003ברשות לוקח\u0004 — \u0003אסור\u0004 שיש בכך משום ריבית.","\u0003המוליך פירות ממקום למקום\u0004 ו\u0003מצאו חבירו ואמר לו: \"תנם לי ואני אעלה\u0004 (אשלם) \u0003לך פירות שיש לי באותו מקום\u0004 שאתה הולך אליו \u0003\",\u0004 \u0003אם יש לו פירות באותו מקום\u0004 — \u0003מותר, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אסור.\u0004 \u0003ו\u0004אולם \u0003החמרין\u0004 המוליכים סחורה ממקום למקום \u0003מעלים\u0004 (קוצבים מחיר) \u0003במקום היוקר כבמקום הזול\u0004 ומקבלים כסף, \u0003ואינן חוששין\u0004 —","אין רואים זאת כריבית הבאה בשל הקדמת התשלום. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003רב פפא אמר: ניחא להו דמגלו להו תרעא\u0004 \u0005[נוח להם שפותחים להם את השער],\u0006 כלומר, הם מרוצים למכור בפחות, שעל ידי כך הם מתחילים במסחר ויוצרים לעצמם לקוחות. \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא אמר: ניחא להו דמוזלי גבייהו\u0004 \u0005[נוח להם\u0006 משום \u0005שמוזילים להם]\u0006 את המחיר במקום שהם קונים, שכיון ששומעים שמכרו במחירי הפסד הם מקבלים סחורתם במחיר זול יותר.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה ההבדל ביניהם\u0006 הלכה למעשה\u0005]?\u0006 ומשיבים: \u0003איכא בינייהו תגרא חדתא\u0004 \u0005[יש ביניהם הבדל\u0006 לגבי \u0005סוחר,\u0006 חמר, \u0005חדש],\u0006 שלדעת האומר שהטעם הוא כדי לפתוח לפניהם את השוק — הרי הדבר אמור במיוחד בסוחר כזה. ולדעת האומר שהוא כדי לקבל סחורה בזול — הרי לתגר חדש לא יאמינו שמוכר בזול, ולא יוזילו לו.","מסופר: \u0003ב\u0004עיר \u0003סורא אזלי\u0004 \u0005[הולכים,\u0006 נמכרים\u0005]\u0006 \u0003ארבעה ארבעה\u0004 סאין בסלע, ובעיירה הסמוכה \u0003כפרי אזלן שיתא שיתא\u0004 \u0005[\u0006היו \u0005הולכים,\u0006 נמכרים, \u0005שש שש\u0006 סאין בסלע\u0005].\u0006 \u0003יהיב\u0004 \u0005[נתן]\u0006 \u0003רב זוזי לחמרי\u0004 \u0005[כסף לחמרים]\u0006 \u0003וקביל עליה אונסא דאורחא\u0004 \u0005[וקיבל על עצמו את אונס הדרך],\u0006 שאם תאבד הסחורה בדרך האחריות עליו, \u0003ושקיל מינייהו\u0004 \u0005[\u0006והיה \u0005לוקח מהם]\u0006 \u0003חמשה\u0004 סאים בסלע. ושואלים: \u0003ונשקול שיתא\u0004 \u0005[ושיקח שש]!\u0006 שהרי אם קיבל על עצמו את אונס הדרך אמרנו שמותר לעשות עיסקה כזו! ומשיבים: \u0003אדם חשוב שאני\u0004 \u0005[שונה],\u0006 שצריך להחמיר על עצמו ולהיזהר יותר ממראית עין של ריבית.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אסי מר' יוחנן: מהו לעשות בגרוטאות כן?\u0004 האם מותר לעשות הסכמים כגון אלה גם בגרוטאות של כסף וזהב וכיוצא בהן, ולאו דווקא בחיטה ופירות? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 כבר \u0003ביקש ר' ישמעאל בר' יוסי לעשות כן בכלי פשתן, ולא הניחו רבי. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בנוסח אחר: \u0003ביקש רבי לעשות בגרוטאות כן, ולא הניחו ר' ישמעאל בר' יוסי.\u0004 משמע שבאלה אין ראוי לעשות.","\u0003פרדיסא\u0004 \u0005[\u0006לגבי \u0005פרדס],\u0006 כלומר, לקנות מראש פירותיו של כרם שלם במחיר זול יותר, \u0003רב אסר ושמואל שרי\u0004 \u0005[התיר].\u0006 ומסבירים: \u0003רב אסר, כיון דלקמיה שויא טפי\u0004 \u0005[שלהבא\u0006 יהיה \u0005שווה יותר]\u0006 — \u0003מתחזי כי אגר נטר ליה\u0004 \u0005[נראה כ\u0006משלם \u0005לו\u0006 \u0005שכר\u0006 על \u0005המתנת\u0006 הכסף ברשותו\u0005]\u0006 וריבית הוא. \u0003ושמואל שרי\u0004 \u0005[התיר],\u0006 וטעמו: \u0003כיון דהוי ביה תיוהא\u0004 \u0005[שיכול להיות בו,\u0006 בכרם, \u0005קלקול]\u0006 והקונה קיבל על עצמו אחריות ההפסדים — \u0003לא מיחזי כי אגר נטר ליה\u0004 \u0005[אינו נראה כשכר המתנה לו].\u0006","\u0003אמר רב שימי בר חייא: ומודי\u0004 \u0005[ומודה]\u0006 \u0003רב בתורי דנפיש פסידייהו\u0004 \u0005[בשוורים שהפסדם מרובה],\u0006 שאם עשה הסכם כזה לגבי גידול שוורים הדבר מותר, משום שבזה מצוי מאד שיהא הפסד ניכר, ויש בכך השקעה ממשית בשותפות.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003שמואל להנהו דשבשי שבשא\u0004 \u0005[לאלה קוני זמורות הגפן],\u0006 שהיו משלמים מראש עבור הזמורות שיזמרו לאחר זמן, שכיון שהסיכון בכך הוא מעט — יש בו חשש ריבית, ולכן \u0003הפוכו בארעא, כי היכי דקני לכו גופא דארעא\u0004 \u0005[הפכו\u0006 קצת בעצמכם, עדרו קצת, \u0005בקרקע\u0006 זו \u0005כדי שיקנה לכם גוף הקרקע]\u0006 ועל ידי זה אתם נעשים שותפים בעבודה, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003הויא לכו\u0004 \u0005[תהיה לכם]\u0006 זאת \u0003כהלואה\u0004 \u0003ואסור\u0004 לקבל.","וכן \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא להנהו דמנטרי באגי\u0004 \u0005[לאלה ששומרים\u0006 את \u0005השדות]\u0006 עד זמן הקציר ומקבלים שכרם מן היבול: \u0003פוקו הפוכו בבי דרי, כי היכי\u0004 \u0005[צאו הפכו\u0006 קצת \u0005בגורן\u0006 וסייעו בעבודה, \u0005כדי]\u0006 ש\u0003לא תשתלם שכירות דידכו\u0004 \u0005[שלכם]\u0006 \u0003עד ההיא שעתא\u0004 \u0005[אותה שעה],\u0006 שאם אתם מסייעים גם בעבודה, נמצא ששכירותכם כפועלים נמשכת עד שהתבואה נגמרת ומגיעה לידכם, ולפי הכלל \u0003שכירות אינה משתלמת אלא בסוף,\u0004 ונמצא ש\u0003ההיא שעתא אוזולי דקא מוזלי גבייכו\u0004 \u0005[באותה שעה\u0006 שנותנים להם היבול אז הם \u0005מוזילים לכם]\u0006 ואין זה שכר ריבית על שאחרו את התשלום המגיע לכם זמן רב קודם לכן.","מסופר: \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרבא:\u0004 \u0003קא אכיל מר\u0004 \u0005[אדוני אוכל,\u0006 נהנה\u0005]\u0006 מ\u0003רבית,\u0004 ומדוע — \u0003דכולי עלמא\u0004 \u0005[שכל העולם]\u0006 המחכירים את שדותיהם לאריסים \u0003שקלי\u0004 \u0005[לוקחים,\u0006 מקבלים\u0005]\u0006 \u0003ארבעה\u0004 כורים מן התבואה \u0003ומסלקי לאריסא\u0004 \u0005[ומסלקים את\u0006 \u0003האריס]\u0004 \u0003ב\u0004חודש \u0003ניסן\u0004 שאז הוא קוצר את התבואה ונותן את חלקו, ו\u0003מר נטר להו\u0004 \u0005[ואדוני ממתין להם]\u0006 \u0003עד\u0004 חודש \u0003אייר\u0004 \u0003ושקיל שיתא\u0004 \u0005[ולוקח\u0006 מהם \u0005ששה\u0006 כורים\u0005],\u0006 והרי זאת ריבית עבור ההמתנה!","\u0003אמר להו\u0004 \u0005[להם]\u0006 להיפך: \u0003אתון קא עבדיתון\u0004 \u0005[אתם הם שעושים]\u0006 \u0003שלא כדין,\u0004 כי באמת כל \u0003ארעא\u0004 \u0005[קרקע]\u0006 \u0003לאריס\u0004 שמעבד אותה \u0003משתעבד\u0004 \u0005[\u0006היא \u0005משועבדת]\u0006 עד שיסיים לעבד אותה ולהוציא ממנה כל מה שאפשר לו להוציא, \u0003אי אתון מסלקיתו להו\u0004 \u0005[אם אתם מסלקים אותם\u0006 \u0003בניסן\u0004 — \u0003מפסידתו להו\u0004 \u0005[מפסידים אתם להם\u0006 \u0003בכמה\u0004 וכמה דברים שאינם מספיקים לקצור בשעה הראויה וללקט את כל מה אפשר מן השדה, ואילו \u0003אנא נטרנא להו\u0004 \u0005[אני ממתין להם]\u0006 \u0003עד אייר, ומרווחנא להו\u0004 \u0005[ומרוויח אני להם]\u0006 \u0003בכמה\u0004 וכמה דברים, שאני נוהג כהלכה ומקבל תשלום נאות על החכרת השדה למשך הזמן המתאים, ואתם מקפחים את האריס, אף שאתם מקבלים גם שכר פחות."],["\u0003רב מרי בר רחל משכן ליה ההוא\u0004 \u0005[אותו]\u0006 \u0003גוי ביתא\u0004 \u0005[בית]\u0006 עבור הלוואה שהלוה לו. \u0003הדר זבנה\u0004 \u0005[אחר\u0006 כך \u0005מכר]\u0006 הגוי אותו בית \u0003לרבא.\u0004 \u0003נטר תריסר ירחי שתא\u0004 \u0005[המתין\u0006 רב מרי בן רחל \u0005שנים עשר חדשי שנה],\u0006 \u0003שקל אגר ביתא\u0004 ו\u0003אמטי ליה\u0004 \u0005[לקח שכר הבית\u0006 ו\u0005הביא לו]\u0006 \u0003לרבא,\u0004 שהוא היה מעתה בעל אותו הבית. ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 בהתנצלות: \u0003האי\u0004 \u0005[זה]\u0006 ש\u0003לא אמטאי למר אגר ביתא\u0004 \u0005[הבאתי לאדוני\u0006 את \u0005שכר הבית]\u0006 \u0003עד האידנא\u0004 \u0005[עכשיו]\u0006 משום ש\u0003סתם משכנתא\u0004 היא לתקופה של \u0003שתא\u0004 \u0005[שנה],\u0006 \u0003אי בעי\u0004 \u0005[\u0006ו\u0005אם היה רוצה]\u0006 אותו \u0003גוי לסלקי\u0004 \u0005[לסלקני]\u0006 ממנו \u0003לא הוה מצי מסלק לי\u0004 \u0005[לא היה יכול לסלק\u0006 אותי\u0005],\u0006 ואם כן, במובן מסויים היה הבית כל אותה שנה ברשותי, ורק עכשיו עבר לגמרי לרשות רבא, \u0003השתא לשקול מר אגר ביתא\u0004 \u0005[עכשיו יקח אדוני את שכר הבית].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003אי הוה ידענא דהוה\u0004 \u0005[אם הייתי יודע ש\u0006בית זה \u0005היה]\u0006 \u0003ממושכן ליה למר\u0004 \u0005[לו לאדוני]\u0006 \u0003לא הוה זביננא ליה\u0004 \u0005[הייתי קונה אותו]\u0006 כלל. \u0003השתא\u0004 \u0005[עכשיו,\u0006 לפיכך\u0005]\u0006 \u0003כדיניהם\u0004 של הגויים \u0003עבדינן לך\u0004 \u0005[אעשה,\u0006 אנהג \u0005בך],\u0006 שהרי אני בא במקום הגוי כאן, ובדיניהם \u0003כל אימת\u0004 \u0005[מתי],\u0006 כל זמן ש\u0003לא\u0004 יכול הלווה \u0003מסלקי בזוזי\u0004 \u0005לסלק\u0006 את המלוה \u0005בכסף]\u0006 הוא גם \u0003לא שקיל אגר ביתא\u0004 \u0005[\u0006\u0005לוקח ממנו שכר הבית],\u0006 שהרי אין הגויים נמנעים מתשלום ריבית. ואם כן, \u0003אנא נמי\u0004 \u0005[אני גם כן]\u0006 \u0003לא שקילנא מינך אגר ביתא\u0004 \u0005[אקח ממך\u0006 את \u0005שכר הבית]\u0006 \u0003עד דמסלקנא\u0004 \u0005[שאסלק]\u0006 \u0003לך בזוזי\u0004 \u0005[את הכספים]\u0006 שחייבים לך.","מסופר, \u0003אמר ליה רבא מברניש לרב אשי: חזי מר רבנן דקא אכלי רביתא\u0004 \u0005[ראה אדוני את החכמים שאוכלים,\u0006 נהנים, \u0005מריבית],\u0006 \u0003דיהבי זוזי אחמרא\u0004 \u0005[שנותנים\u0006 לאנשים \u0005כסף\u0006 עבור \u0005יין]\u0006 \u0003ב\u0004חודש \u0003תשרי ומבחרי לה\u0004 \u0005[ובוררים\u0006 להם \u0005אותו]\u0006 אחר כך \u0003ב\u0004חודש \u0003טבת.\u0004 שאם היו לוקחים מיד — שמא היה מחמיץ, ועכשיו בשכר הקדמת התשלום הם מובטחים ביין שלא החמיץ!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אינהו נמי, אחמרא קא יהבי, אחלא\u0004 \u0005[הם\u0006 מתחילה \u0005גם כן על יין הם נתנו,\u0006 שילמו, ו\u0005על חומץ\u0006\u0005]\u0006 \u0003לא קא יהבי\u0004 \u0005[נתנו,\u0006 שילמו\u0005],\u0006 \u0003מעיקרא דחמרא\u0004 \u0005[\u0006ו\u0005מתחילה\u0006 ומה שהיה \u0005יין]\u0006 — \u0003חמרא\u0004 \u0005[יין\u0006 הוא\u0005],\u0006 \u0003דחלא\u0004 \u0005[\u0006ומה שהיה \u0005חומץ]\u0006 — \u0003חלא\u0004 \u0005חומץ\u0006 הוא\u0005],\u0006 אלא שלא ידעו ו\u0003ההיא שעתא\u0004 \u0005[ובאותה שעה]\u0006 \u0003הוא דקמבחרי\u0004 \u0005[ש\u0006הם \u0005בוחרים]\u0006 את היין שקנו בשעתו.","מסופר: \u0003רבינא הוה יהיב זוזי\u0004 \u0005[היה נותן,\u0006 משלם, \u0005כסף]\u0006 מראש \u0003לבני אקרא\u0004 \u0005[מבצר]\u0006 \u0003שנוותא ושפכי ליה טפי כופיתא\u0004 \u0005[ו\u0006היו \u0005שופכים לו כד\u0006 אחד \u0005יותר]\u0006 במתנה, אם כי לא היה כלל תנאי כזה ביניהם. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב אשי\u0004 לשאול אם יש בזה משום ריבית. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי שרי\u0004 \u0005[האם מותר]\u0006 לעשות זאת? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין, אחולי הוא דקא מחלי גבך\u0004 \u0005[כן, מחילה היא שהם מוחלים לך]\u0006 על מידה מדוייקת, כדי להיות ביחסים טובים ולא כתמורה בעד הקדמת התשלום.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003הא ארעא לאו דידהו\u0004 \u0005[הרי הקרקע לא שלהם]\u0006 \u0003היא!\u0004 שהם היו מעבדים שדותיהם של אנשים שעזבו את שדותיהם משום שלא יכלו לשלם מיסים, ואלה היו משלמים את מיסי הקרקע ומשתמשים בה. ונמצא שמחלו על דבר שאינו שלהם! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי לא כן היא, \u0003ארעא לטסקא משעבדא\u0004 \u0005[הקרקע משועבדת\u0006 לתשלום \u0005המסים]\u0006 למלכות. \u0003ומלכא\u0004 \u0005[המלך]\u0006 \u0003אמר: מאן דיהיב טסקא\u0004 \u0005[מי שנותן\u0006 את \u0005המס]\u0006 — הוא \u0003ליכול ארעא\u0004 \u0005[יאכל\u0006 מפירות \u0005הקרקע]\u0006 ולכן משלמי המיסים יש להם בעלות על היין מכוח דין המלכות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא: חזי מר הני רבנן דיהבי זוזי אכרגא דאינשי ומשעבדי בהו טפי\u0004 \u0005[ראה אדוני את החכמים הללו שנותנים את דמי הגולגולת של אנשים ומעבידים אותם\u0006 אחר כך \u0005הרבה]\u0006 יותר מן התמורה הראויה עבור תשלום מס זה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003השתא איכו שכיבא\u0004 \u0005[אמר לו: עכשיו אילו הייתי מת]\u0006 \u0003לא אמרי לכו הא מילתא\u0004 \u0005[הייתי אומר לכם דבר זה],\u0006 כלומר, טוב עשית שהזכרת לי הלכה זו. \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב ששת: מוהרקייהו דהני בטפסא דמלכא מנח\u0004 \u0005[כתב העבדות של\u0006 כל \u0005אלה באוצרו של המלך מונח]\u0006 שכל בני המדינה נחשבים עבדיו, \u0003ומלכא\u0004 \u0005[והמלך]\u0006 \u0003אמר: מאן דלא יהיב כרגא לשתעביד למאן דיהיב כרגא\u0004 \u0005[מי שאיננו משלם דמי גולגולת שישתעבד למי שמשלם דמי גולגולת]\u0006 ומכוח דין המלכות יכולים הם לעבוד באלה כמה שירצו.","מסופר: \u0003רב סעורם אחוה\u0004 \u0005[אחיו]\u0006 של \u0003רבא הוה תקיף אינשי דלא מעלו ומעייל להו בגוהרקא\u0004 \u0005[רב סעורם אחיו של רבא היה תופס אנשים שאינם הגונים ומכניס אותם לשאת את אפיריונו]\u0006 של \u0003רבא.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: שפיר קא עבדת\u0004 \u0005[יפה עשית],\u0006 \u0003דתנינא\u0004 \u0005[ש\u0006כן \u0005שנינו]:\u0006 \u0003ראית\u0004 אדם מישראל \u0003שאינו נוהג כשורה, מנין שאתה רשאי להשתעבד בו\u0004 — \u0003תלמוד לומר: \"לעולם בהם תעבדו ובאחיכם\"\u0004 (ויקרא כה, מו) — שאף באחיכם מותר לפעמים לנהוג כבעבדים. \u0003יכול אפילו נוהג כשורה\u0004 יעשו לו כן — \u0003תלמוד לומר\u0004 הפסוק בשלמותו: \u0003\"ובאחיכם בני ישראל איש באחיו\u0004 לא תרדה בו בפרך\u0003\"\u0004(שם).","\u0003אמר רב חמא: האי מאן דיהיב זוזי לחבריה למיזבן ליה חמרא\u0004 \u0005[מי שנותן כסף לחבירו לקנות לו יין]\u0006 \u0003ופשע\u0004 \u0005[והתרשל]\u0006 אותו אדם \u0003ולא זבין ליה\u0004 \u0005[קנה לו]\u0006 — \u0003משלם ליה\u0004 \u0005[לו]\u0006 \u0003כדקא אזיל אפרוותא\u0004 \u0005[כמו שהולך,\u0006 נמכר היין \u0005בנמל]\u0006 של \u0003זולשפט\u0004 ששם היה שוק היינות הגדול, ולפי המחיר שם יקנה לו יין, אפילו המחיר יותר על מה שנתן לו בשעתו.","\u0003אמר אמימר: אמריתא לשמעתא קמיה\u0004 \u0005[אמרתי את השמועה,\u0006 ההלכה \u0005הזו לפני]\u0006 \u0003רב זביד מנהרדעא,\u0004 ומששמעה \u0003אמר\u0004 לי: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב חמא\u0004 — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא כשאמר לו קנה לי \u0003\"יין\" סתם\u0004 ולא פירש איזה, \u0003אבל ב\"יין זה\",\u0004 שפירש מין היין שרוצה בו — \u0003לא\u0004 אמר, ואינו חייב לקנות ביותר, כי \u0003מי יימר דמזבני ליה ניהליה\u0004 \u0005[מי אמר שימכרו לו אותו]?\u0006 ונמצא שמתחילה לא היה קנין ברור, וההתחייבות של המקבל היא רק להחזיר את הכסף, ובזה אין להוסיף על הסכום מפני הריבית.","\u0003רב אשי אמר: אפילו\u0004 אמר לו \u0003\"יין סתם\"\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 חייב לקנות ביותר מכדי הסכום שנתן לו, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003אסמכתא היא,\u0004 שכל שפורע לו יותר מכפי שקיבל מתחילה — הרי הוא כהתחייבות לשלם קנס והיא אסמכתא, \u0003ואסמכתא לא קניא\u0004 \u0005[אינה קונה],\u0006 שאין קנין מועיל לגבי קבלת קנס על עצמו.","ושואלים: \u0003ולרב אשי מאי שנא מהא דתנן\u0004 \u0005[מה שונה\u0006 הדבר \u0005ממה ששנינו\u0006 במשנה\u0005]\u0006 לגבי חוזה שכירת קרקעות שכותב האריס: \u0003\"אם אוביר,\u0004 אשאיר את השדה בור \u0003ולא אעביד\u0004 \u0005[אעבד]\u0006 אותו \u0003אשלם במיטבא\"\u0004 \u0005[במיטב],\u0006 ונמצא שהאריס משלם על מה שהפסיד לבעלים בחוסר מעשה, ומדוע לא ישלם גם כן? ומשיבים: \u0003התם\u0004 \u0005[שם\u0006 בעיבוד השדה\u0005]\u0006 הדבר \u0003בידו\u0004 אם לעבוד או לא לעבוד,"]]};
